INSERT INTO public.lms_authors (id, auth_user_id, slug, name, role, bio, quote, credentials, photo, listed, created_at, updated_at, background, profile_facts, profile_blocks, experience_badge, achievement_badge, consultation_enabled, consultation_title, consultation_summary, consultation_points, consultation_contact_url) VALUES ('4dc0b1a7-f044-4482-a2ee-a2342abe2e18', 'bdc98ead-08d6-4869-ae09-cd154030e339', 'po-dzin', '⛩️', '🌚', '🌝', '🌞', NULL, '{"alt": "⛩️", "src": "https://ibqexzkvtdmvuxenmvpy.supabase.co/storage/v1/object/public/course-media/authors/bdc98ead-08d6-4869-ae09-cd154030e339/6355012d-b7b4-4067-b3eb-ef9f3cd5114a/1600.webp", "cropX": 31, "cropY": 50}', true, '2026-08-29 19:51:59.681975+00', '2026-08-29 19:51:59.681975+00', '{"src": "https://ibqexzkvtdmvuxenmvpy.supabase.co/storage/v1/object/public/course-media/authors/bdc98ead-08d6-4869-ae09-cd154030e339/backgrounds/0f4f208d-20ec-47ce-aec8-cdfad7e240d1/1600.webp"}', '[")"]', NULL, '1000', 'Да', false, NULL, NULL, NULL, NULL);
INSERT INTO public.lms_authors (id, auth_user_id, slug, name, role, bio, quote, credentials, photo, listed, created_at, updated_at, background, profile_facts, profile_blocks, experience_badge, achievement_badge, consultation_enabled, consultation_title, consultation_summary, consultation_points, consultation_contact_url) VALUES ('1c365b92-7d0c-44a9-a6df-45d49c31be4c', 'a68003e9-e804-4d1c-96d0-08b2d770a6d6', 'koriakin', 'Євгеній Корякін', 'Засновник проекту CenterWay', 'Дослідник і практик аюрведи та сучасної дієтології, йога терапевт, остіопат', 'Здоров''я починається там, де закінчується метушня. А кожен наступний крок стає усвідомленою частиною буття', '["Магістр комплементарної медицини, 20 років досвіду", "Автор методик з дієтології та детоксикації", "Йога- та аюрведа-терапевт, переможець «Битви титанів»"]', '{"alt": "Євгеній Корякін", "src": "https://ibqexzkvtdmvuxenmvpy.supabase.co/storage/v1/object/public/course-media/authors/a68003e9-e804-4d1c-96d0-08b2d770a6d6/3a3ffe13-b1db-4a37-9962-f8a19a1e9aa4/1600.webp", "cropX": 51, "cropY": 19, "avatarCropX": 65, "avatarCropY": 0}', true, '2026-08-26 14:39:02.183192+00', '2026-08-26 14:39:02.183192+00', '{"src": "https://ibqexzkvtdmvuxenmvpy.supabase.co/storage/v1/object/public/course-media/authors/a68003e9-e804-4d1c-96d0-08b2d770a6d6/backgrounds/835c049f-c7f7-456b-b4e2-ee879cc3114e/1600.webp", "cropX": 32, "cropY": 48}', '["20 років практики", "Магістр комплементарної медицини та інтегративної психології", "Інструктор з йоги та практикуючий йогін", "Засновник проекту CenterWay", "Аюрведична дієтологія — Керала, Індія", "Заслужений натуропат Європи"]', '[{"id": "story", "body": "Привіт! Давайте знайомитись: я — Євгеній Корякін, дослідник і практик аюрведи, магістр комплементарної медицини і засновник центру CenterWay.\n\nУ дитинстві я хотів бути лікарем, а питання здоров’я і розвитку фізичної форми людини цікавили мене завжди. Любов до фізкультури і філософських наук підштовхнула мене до вивчення тіла людини як предмета вищого творіння.\n\nТехнічна освіта не задовольняла сутність мого внутрішнього світу. Я почав цікавитись йогою і масажем, а практики і філософія показали мені шлях. Масаж став провідником у світ тонкого устрою реальності — у світ без слів і концепцій.", "kind": "text", "label": "Про автора", "title": "Мій шлях до CenterWay"}, {"id": "education-path", "kind": "timeline", "items": ["Київський політехнічний інститут, інформатика і обчислювальна техніка.", "2009 р. — базовий курс класичного, антицелюлітного і дитячого масажу; повний курс тайського масажу.", "2010–2011 рр. — Інститут натуральної медицини, Ганновер, спеціальність «бакалавр натуральної медицини».", "2010–2013 рр. — оздоровчий центр Healsyjoy: китайські масажні техніки, гуа-ша, хіромасаж живота, моделювання і лімфодренаж обличчя.", "2012 р. — Чакрапані аюрведа-клініка, напрям «аюрведична марма-терапія».", "2012–2013 рр. — Інститут міждисциплінарних досліджень і освіти, Ганновер: магістр комплементарної медицини і інтегративної психології.", "Магістерська робота: «Способи корекції ваги і очищення організму з допомогою засобів аюрведи».", "2014 р. — засновано центр CenterWay.", "2016 р. — Сіббі Керала Аюрведа-центр, Індія: аюрведична дієтологія, стиль життя і йога-терапія.", "2017 р. — орден «Заслужений натуропат Європи».", "2019 р. — мануальне м''язове тестування в кінезіології, школа «Реабілітолог»", "2022 р. — мікрокінезітерапія, приватні навчальні курси"], "label": "Освіта і шлях", "title": "Від технічної освіти до системи CenterWay"}]', '20 років практики', 'Засновник CenterWay', true, 'Аюрведична консультація', 'Персональна онлайн-консультація до 90 хвилин: стан, харчування, ритм і зрозумілий план на 2–4 тижні.', '["розбір поточного стану, конституції, харчування і ритму", "онлайн-зустріч тривалістю до 90 хвилин", "персональні пріоритети та план дій на 2–4 тижні"]', 'https://t.me/E_Koriakin');
INSERT INTO public.lms_courses (id, slug, title, program_slug, brand, locale, translation_group_id, status, version, summary, schedule, entitlement_product_codes, created_at, updated_at, author_id, theme, cover, sort_order, tagline, results, visibility, review_status, review_note, submitted_at, approved_at, approved_by, pending_content, pending_review_status, pending_review_note, pending_submitted_at, pending_updated_at, revision_seq, draft_generation, published_revision_id, audience, format, access_note, author_note, author_profile_id, pretitle, posttitle, kind, categories, duration_days) VALUES ('c4a91d3e-0000-4000-8000-000000000001', 'way21', 'Шлях 21 — інтегративна детокс-програма', 'way21', 'centerway', 'uk', 'way21', 'published', 6, '"Програма перекладає принципи аюрведичного очищення у структуровану 21-денну програму: підготовка, м''яке виведення перевантаження, підтримка травлення, трав''яний супровід і повернення до стабільного ритму. Це wellness-освіта і направлена практика, а не медичне лікування."', '{"mode": "daily", "start": "purchase", "reminderHour": 9}', '{way21,way21-support,detox21,shlyah21}', '2026-08-19 14:47:30.81773+00', '2026-09-08 15:24:04.379328+00', NULL, NULL, '{"alt": "Обкладинка програми «Шлях 21»", "src": "/cw/platform/programs/way21-home-desktop-v1.webp"}', 3, '21-денна аюрведична програма розвантаження: харчування, трави, режим і щоденні опори без жорсткого тиску.', '["Сильне травлення без важкості після їжі", "Менше набряків, чистіша шкіра, рівна енергія", "Стабільний сон і спокійніший емоційний фон", "Харчові звички, які лишаються після програми", "Розуміння своєї конституції замість чергової чужої дієти"]', 'listed', 'approved', NULL, NULL, '2026-08-23 09:13:29.52411+00', NULL, NULL, NULL, NULL, NULL, NULL, 0, 2, NULL, '["Ви вже «чистились» — і за кілька тижнів усе поверталось назад", "Важкість у тілі, набряки, травлення то є, то немає", "Хочете керувати вагою без жорстких дієт і голодування наосліп", "Готові тримати режим двадцять один день, а не шукати чарівну пігулку"]', '["Три фази за двадцять один день: підготовка, глибоке очищення, вихід", "Фітопротокол: склад трьох зборів і як їх заварювати", "Харчування і режим дня під вашу конституцію", "Вебінари й відеоінструкції до процедур", "Рецепти, чек-листи й щоденна звітність"]', 'доступ до матеріалів лишається після програми', NULL, '1c365b92-7d0c-44a9-a6df-45d49c31be4c', NULL, 'інтегративна детокс-програма', 'course', '["cleansing", "nutrition"]', 21);
INSERT INTO public.lms_courses (id, slug, title, program_slug, brand, locale, translation_group_id, status, version, summary, schedule, entitlement_product_codes, created_at, updated_at, author_id, theme, cover, sort_order, tagline, results, visibility, review_status, review_note, submitted_at, approved_at, approved_by, pending_content, pending_review_status, pending_review_note, pending_submitted_at, pending_updated_at, revision_seq, draft_generation, published_revision_id, audience, format, access_note, author_note, author_profile_id, pretitle, posttitle, kind, categories, duration_days) VALUES ('1082476a-db78-4dd2-ad51-da4001d3a9ec', 'novyi-kurs-3', 'Новий курс 3', 'novyi-kurs-3', 'centerway', 'uk', '45ff5be7-be9e-4e8d-b082-3aa750a15127', 'draft', 2, '"[ЗАПОВНИ: про що цей курс]"', '{"mode": "open"}', '{}', '2026-08-28 16:05:47.348054+00', '2026-08-30 18:01:50.228174+00', 'a68003e9-e804-4d1c-96d0-08b2d770a6d6', NULL, NULL, 8, NULL, NULL, 'hidden', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.lms_courses (id, slug, title, program_slug, brand, locale, translation_group_id, status, version, summary, schedule, entitlement_product_codes, created_at, updated_at, author_id, theme, cover, sort_order, tagline, results, visibility, review_status, review_note, submitted_at, approved_at, approved_by, pending_content, pending_review_status, pending_review_note, pending_submitted_at, pending_updated_at, revision_seq, draft_generation, published_revision_id, audience, format, access_note, author_note, author_profile_id, pretitle, posttitle, kind, categories, duration_days) VALUES ('3bf946d7-31a1-4767-b9fd-409310e58956', 'novyi-kurs-4', 'Новий курс 4', 'novyi-kurs-4', 'centerway', 'uk', 'ec9aefcc-be1e-4304-aa04-59c01fb20ce1', 'draft', 1, '"[ЗАПОВНИ: про що цей курс]"', '{"mode": "open"}', '{}', '2026-09-09 10:48:35.199919+00', '2026-09-09 10:48:35.773359+00', 'a68003e9-e804-4d1c-96d0-08b2d770a6d6', NULL, NULL, NULL, NULL, NULL, 'hidden', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.lms_courses (id, slug, title, program_slug, brand, locale, translation_group_id, status, version, summary, schedule, entitlement_product_codes, created_at, updated_at, author_id, theme, cover, sort_order, tagline, results, visibility, review_status, review_note, submitted_at, approved_at, approved_by, pending_content, pending_review_status, pending_review_note, pending_submitted_at, pending_updated_at, revision_seq, draft_generation, published_revision_id, audience, format, access_note, author_note, author_profile_id, pretitle, posttitle, kind, categories, duration_days) VALUES ('cc7b01ee-0000-4000-8000-000000000001', 'irem-gymnastics', 'IREM Гімнастика', 'irem', 'centerway', 'uk', 'irem-gymnastics', 'published', 1, '"IREM збирає прості рухові техніки у послідовну практику: розігрів, дихання, мобільність, робота з напруженням і повернення уваги до сигналів тіла. Сім днів ідуть по порядку, від простого до глибшого, щоб тіло встигало за темпом."', '{"gate": "soft", "mode": "daily", "start": "purchase"}', '{irem-gymnastics,ivem-gimnastika,irem}', '2026-08-23 20:30:18.344421+00', '2026-09-08 15:24:02.454266+00', NULL, '{"scale": "regular", "palette": "mineral", "headingFont": "editorial"}', '{"alt": "Обкладинка курсу «ІВЕМ гімнастика»: килимок, скакалка й утяжелитель для тренування", "src": "/cw/platform/programs/irem-hero-desktop-v2.webp", "cropX": 68, "cropY": 50, "mobileSrc": "/cw/platform/programs/irem-card-v1.png", "mobileCropX": 50, "mobileCropY": 15}', 5, 'Щоденна рухова практика для контакту з тілом, м''якшої мобільності, енергії і зняття побутової напруги.', '["Сила, мобільність і дихання ростуть в одній практиці, а не в трьох різних", "Менше скутості в суглобах, більше амплітуди й легкості", "Рівна енергія протягом дня замість ривків і провалів", "Ритм, який тримається, бо кожен день має свій фокус", "Опора для продовження після основного циклу"]', 'listed', 'draft', NULL, NULL, NULL, NULL, '{"id": "cc7b01ee-0000-4000-8000-000000000001", "kind": "course", "slug": "irem-gymnastics", "brand": "centerway", "cover": {"alt": "Обкладинка курсу «ІВЕМ гімнастика»: килимок, скакалка й утяжелитель для тренування", "src": "/cw/platform/programs/irem-hero-desktop-v2.webp", "cropX": 50, "cropY": 50, "mobileSrc": "/cw/platform/programs/irem-card-v1.png", "wideCropY": 61, "mobileCropX": 50, "mobileCropY": 52}, "theme": {"scale": "regular", "palette": "mineral", "headingFont": "editorial"}, "title": "ІВЕМ Гімнастика", "locale": "uk", "status": "draft", "modules": [{"id": "cc7b01ee-0100-4000-8000-000000000001", "slug": "before-start", "order": 1, "title": "Перед стартом", "lessons": [{"id": "cc7b01ee-0101-4000-8000-000000000001", "slug": "general-recommendations", "order": 1, "title": "Загальний опис та рекомендації", "blocks": [{"id": "general-recommendations-text-1", "type": "rich_text", "content": [{"kind": "p", "text": "Вітаємо у всесвіті шанувальників гімнастики та здорового образу життя! У цьому кабінеті 7 уроків вправ на кожен день тижня. Дивлячись відео-урок, можна спочатку, для навчання, виконувати вправи або синхронно з відео, або ставити на паузу і виконувати у своєму темпі, - як комфортніше. Всі ці вправи згруповані таким чином, щоб доповнювати одна одну як у комплексі одного дня занять, так і у цілісному комплексі занять всього тижня. Вони однаково підходять і новачкам, і практикуючим будь-якого рівня підготовки. Головне - завжди тренуватися і навантажуватися згідно відчуттям тіла на момент тренування. Тобто, якщо є відчуття, що треба трохи менше навантажитись, або, навпаки, трохи більше - все це можна й потрібно завжди регулювати амплітудою та швидкістю рухів, інтенсивністю та зусиллям, кількістю повторень та підходів. Для початку постійних щоденних тренувань починайте з понеділка - так швидше можна увійти у ритм кожного дня. Спочатку спробуйте на першому тижні мінімальні для себе навантаження для того, щоб сформувати чіткий тілесний відгук по конкретному дню і загалом по всьому тижню. Таким чином, далі вже буде зрозуміло, який середній рівень навантаження буде потрібен у наступних тренуваннях. В середньому, при щоденних тренуваннях індивідуальний початковий робочій тонус тіла може бути досягнутий приблизно за місяц тренувань. Також, якщо спочатку немає можливості або наміру тренуватися кожного дня, можна використовувати програму тренувать будь-якого дня тижня. Всі вони цілісні та сбалансовані для цього дня. Це дає можливість підтримувати себе у гарній формі у своєму форматі тренувань. Але для 100% гарантованного ефекту ми рекомендуємо щоденні тренування, у відповідності до програми комплексу вправ конкретного дня тижня. За для цього притримуйтесь, будь ласка, наступних правил: 1. ЗАВЖДИ робити гімнастику — щодня. Не робити від неї перерв. Не пропускати через хворобу (це допомагає швидше одужати). У разі травми зменшити навантаження в тих вправах, які більше перевантажують травмовану частину тіла (усе за відчуттями), але виконувати ВСІ вправи дня. Не пропускати через обставини (не встиг, пізно прокинувся, рано зустріч тощо) — усе рівно, зробити в будь-який інший час дня (навіть перед сном) або максимально швидко для поточного дня за рахунок швидкості виконання, але виконати ВСІ вправи (у середньому можна вкластися в 40 хвилин, якщо дуже потрібно). 2. Виконувати потрібно ВСІ вправи і ЗАВЖДИ, орієнтуючись на ВІДЧУТТЯ в тілі — регулювати навантаження інтенсивністю, зусиллям, швидкістю виконання, амплітудою та кількістю повторень. 3. Намагатися робити гімнастику після ранкових процедур, перед сніданком, натщесерце. Якщо в якийсь день критично немає такої можливості — усе рівно, зробити в будь-який інший час із не надто навантаженим шлунком, або якщо дуже голодні — перед самою гімнастикою з’їсти швидкі вуглеводи в помірній кількості, наприклад, солодкий батончик. 4. Завжди пити воду до і під час гімнастики по 150–200 мл за раз — за 30 хв до початку, безпосередньо перед початком гімнастики та під час гімнастики, з інтервалом у 30 хвилин між прийомами. 5. Якщо раптом усе ж ніяк не змогли зробити сьогодні — ОБОВ’ЯЗКОВО зробіть наступного дня гімнастику за планом наступного дня, ніби нічого не сталося. 6. Лінуватися можете, коли хочете, але гімнастику робіть щодня 💪 Це поступово сформує стиль ''життя в гімнастиці'', який і дозволить тілу та розуму бути функціональними кожного дня на потязі усього життя."}]}]}, {"id": "cc7b01ee-0101-4000-8000-000000000002", "slug": "exercise-description", "order": 2, "title": "Опис вправ", "blocks": [{"id": "exercise-description-text-1", "type": "rich_text", "content": [{"kind": "h3", "text": "Інтегральна відновлювальна енергомоделююча гімнастика"}, {"kind": "p", "text": "Опис вправ"}, {"kind": "p", "text": "1 частина"}, {"kind": "p", "text": "Виділення енергії та прокачування енергетичних насосів"}, {"kind": "p", "text": "1. Вправа"}, {"kind": "p", "text": "Обертання на п''ятах, руки в сторони"}, {"kind": "p", "text": "Основна позиція - стоячи прямо, руки прямі в сторони долонями вгору."}, {"kind": "p", "text": "Повертаємось праворуч на місці, дрібно переступаючи ногами з пальців в п''яту 24-32 рази до злиття видимого в одну лінію, потім повільно, але впевнено зупиняємось і опускаємо руки."}, {"kind": "p", "text": "2. Вправа"}, {"kind": "p", "text": "Підняття прямих ніг лежачи, підборіддя до грудей"}, {"kind": "p", "text": "Основна позиція – лежачи на спині, руки прямі вздовж тіла долонями до підлоги."}, {"kind": "p", "text": "На вдиху одночасно підіймаємо прямі ноги, максимально натягуючи пальці на себе і не відриваючи від підлоги поперек, та підіймаємо голову, притискаючи підборіддя до грудей. На видиху – опускаємо. 12 разів"}, {"kind": "p", "text": "3. Вправа"}, {"kind": "p", "text": "Прогинання назад, стоячи на колінах та пальцях ніг."}, {"kind": "p", "text": "Основна позиція - стоячи на колінах і пальцях ніг, долони з притиснутими пальцями під сідницями, підборіддя притиснуте до грудей."}, {"kind": "p", "text": "На вдиху вигинаємось назад, закидаючи голову, на видиху - повертаємося у вихідне положення, 12 разів"}, {"kind": "p", "text": "4. Вправа"}, {"kind": "p", "text": "Підняття корпусу \"лавка\""}, {"kind": "p", "text": "Основна позиція – сидячи на підлозі, ноги та корпус прямі, руки прямі вздовж тулуба долонями на підлозі, пальці притиснуті та спрямовані вперед."}, {"kind": "p", "text": "На вдиху піднімаємо таз вгору, коліна під 90 град, стопи притиснуті до підлоги, руки прямо долонями до підлоги, корпус рівний, паралельно до підлоги, голова відкинута назад. На видиху повертаємось у вихідне положення. 12 разів"}, {"kind": "p", "text": "5. Вправа"}, {"kind": "p", "text": "Прогин спини - згинання з опорою на прямі ноги та руки - \"індійські віджимання\""}, {"kind": "p", "text": "Вихідна позиція – у нахилі, руки прямі приблизно за метр перед собою, пальці притиснуті, спрямовані вперед, долони на підлозі, ноги прямі на ширині плечей, стопи притиснуті до підлоги, підборіддя притиснуте до грудей."}, {"kind": "p", "text": "Робимо вдих і розгинаємось, не відриваючи долонь та стоп від підлоги, ноги та руки прямі, спина прогинається назад, голова максимально відхиляється назад. Робимо видих і повертаємось у вихідне положення. 12 разів"}]}, {"id": "exercise-description-text-2", "type": "rich_text", "content": [{"kind": "p", "text": "2 частина"}, {"kind": "p", "text": "Наповнення та перерозподіл енергії"}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Формування енергетичної оболонки"}, {"kind": "p", "text": "Початкова позиція – стоячи, ноги на ширині плечей. Нахиляємося вниз, руками «зачерпуємо» енергію і на вдиху підіймаємо вгору над головою, на видиху – опускаємо долонями вниз. Руки торкаються підлоги. Спочатку робимо з боків, потім попереду себе і потім позаду себе."}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Наповнення енергією простору"}, {"kind": "p", "text": "Ноги на ширині плечей, руки підіймаємо на вдиху долонями вгору з боків, потім на видиху опускаємо долонями вниз перед собою і внизу спереду перекладаємо назад і торкається пальцями ззаду. Так робимо чотири рази, повертаючись до чотирьох сторін світу."}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Розтирання рук з обертанням стоячи."}, {"kind": "p", "text": "Руки перед собою, розтираємо долоні одна об одну до відчуття «гарячого» тепла. Потім розтираємо зовнішню сторону долоні лівою рукою праву, і навпаки, і всі пальці. Після цього складаємо пальці в замок і робимо обертання у різні боки руками у замку. У кожну сторону 12 разів, а потім залишаючи пальці в замку, робимо хвилю 12 разів в обидві сторони. Потім складаємо долоні разом перед грудьми і опускаємо та підіймаємо пальці вниз-вгору 12 разів, потім з''єднуємо зовнішньою стороною кисті і також обертаємо кистями вгору-вниз 12 разів, амплітуда максимальна."}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Перекочування стопи з пальців на п''яту і назад."}, {"kind": "p", "text": "Спираємось на ліву ногу, правою ногою спочатку наступаємо на пальці, потім переводимо пальці у вертикальне положення, торкаємося зовнішньою стороною пальців підлоги, потім перекочуємо на п''яту, піднімаючи стопу вгору, пальці відтягуємо на себе, і так, туди і назад, 12 повторень, спочатку правою ногою, потім лівою."}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Обертання та згинання пальців рук"}, {"kind": "p", "text": "Руки тримаємо перед собою. Починаючи з мізинця, прямими пальцями обертаємо праворуч і ліворуч по 12 разів у послідовності: мізинець - безіменний - середній - вказівний - великий палець. Потім великим пальцем правої руки притискаємо мізинець лівої руки кінчиком до долоні, складаючи його, і в складеному стані ще раз щільно притискаємо до долоні, натискаючи великим пальцем правої руки на складений мізинець від його основи до першого згину."}, {"kind": "p", "text": "Потім беремо зовнішньою стороною вказівного та середнього пальця правої руки як «веделкою» мізинець лівої руки та відводимо його максимально назад. Потім, так само, всі інші пальці до великого."}, {"kind": "p", "text": "Після цього долонею лівої руки притискаємо прямий великий палець правої руки до внутрішньої сторони передпліччя, потім правою рукою великий палець лівої руки, і навпаки, всього 32 рази."}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Обертання стопи з опорою на пальці ніг."}, {"kind": "p", "text": "Пальцями правої ноги упираємось у підлогу, опора на ліву ногу. Обертаємо стопою з опорою на пальці вліво і вправо по 12 разів, потім міняємо ноги – відповідно, стоїмо на правій нозі, обертаємо лівою стопою."}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Відштовхування кулаками."}, {"kind": "p", "text": "Вихідна позиція – ноги на ширині плечей, руки стиснуті в кулаках та зігнуті перед собою. Від грудей робимо вдих, на видиху відштовхуємо кулаками від себе повітря 12 разів."}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Обертання кулаками та прямими долонями перед собою."}, {"kind": "p", "text": "Початкова позиція – стоячи, руки прямі. Стискаємо долоні в кулаки і обертаємо поперемінно та синхронно на внутрішній і зовнішній бік 12 разів, потім теж робимо відкритою долонею."}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Обертання прямими руками вздовж осі рук."}, {"kind": "p", "text": "Руки прямо перед собою, обертаємо вліво-вправо поперемінно змінюючи бік, усередину та назовні щодо осі прямих рук, 12 разів."}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Очищаюче дихання хвилею з напругою рук і кистей, стиснутих у кулаки. Виконується 36 разів. Спочатку робимо гучний вдих і шумний видих нижньою частиною живота (дихання діафрагмою), одночасно на видиху стискаючи кулаки і напружуючи прямі руки, опущені вниз, 12 разів. Потім продовжуємо те саме і додаємо рух ребрами - ребра звужуються і розширюються - наповнюється та очищається нижня частина легень - теж 12 разів. І потім, продовжуючи дихати животом і ребрами, підключаємо верхню частину грудей: піднімаємо її та опускаємо – наповнюючи та очищуючи повний об''єм легень."}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Обертання стопою на піднятій нозі стоячи."}, {"kind": "p", "text": "Стоїмо на лівій нозі і підіймаємо праву пряму ногу над підлогою. Обертаємо стопою ліворуч і праворуч, на внутрішній і зовнішній бік 12 разів, потім міняємо ногу."}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Обертання в ліктьових суглобах."}, {"kind": "p", "text": "Руки убік, плечі вільні. Обертаємо передпліччям щодо ліктів на внутрішню та зовнішню сторону синхронно, лікті та плечі нерухомі в одній лінії, горизонтально. Потім синхронно вліво та вправо. Потім обертаємо поперемінно вліво-вправо, всередину та назовні - кожен рух 12 разів. Закінчуємо обертанням назовні кілька разів."}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Обертання в колінних суглобах."}, {"kind": "p", "text": "Початкове положення стоячи на лівій нозі - права нога зігнута в коліні і піднята на 45 градусів, стегно до коліна нерухоме. Робимо обертання гомілки на внутрішню та зовнішню сторону відносно коліна 12 разів. Гомілка і стопа розслаблені, допомагаємо обертанню гомілки стегном. Потім ноги міняємо."}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "ÐÐ°ÑINSERT INTO public.lms_courses (id, slug, title, program_slug, brand, locale, translation_group_id, status, version, summary, schedule, entitlement_product_codes, created_at, updated_at, author_id, theme, cover, sort_order, tagline, results, visibility, review_status, review_note, submitted_at, approved_at, approved_by, pending_content, pending_review_status, pending_review_note, pending_submitted_at, pending_updated_at, revision_seq, draft_generation, published_revision_id, audience, format, access_note, author_note, author_profile_id, pretitle, posttitle, kind, categories, duration_days) VALUES ('fb5d1cf1-05b4-552a-9794-cf14a20e85f6', 'natural-body', 'Природнє тіло з Аюрведою', 'natural-body', 'centerway', 'uk', 'natural-body', 'published', 1, '"21 урок про базові принципи Аюрведи, харчування, добовий ритм і баланс дош — із практичною інструкцією та матеріалами."', '{"gate": "soft", "mode": "sequential"}', '{natural-body,ideal-body}', '2026-08-23 17:45:06.766178+00', '2026-09-08 15:24:03.130838+00', NULL, '{"scale": "regular", "palette": "mineral", "headingFont": "editorial"}', '{"alt": "Обкладинка курсу «Природнє тіло з Аюрведою»", "src": "/cw/platform/programs/ideal-body-hero-desktop-v2.webp", "cropX": 70, "cropY": 50, "mobileSrc": "/cw/platform/programs/ideal-body-card-v1.png", "mobileCropX": 50, "mobileCropY": 16}', 4, '21 основний урок, щоб зібрати харчування і ритм під свою конституцію.', '["Розуміння базових принципів аюрведи й теорії дош", "Щоденний ритм харчування, пиття і руху, зібраний під вас", "Уміння розрізняти властивості продуктів та їх поєднання", "Орієнтири для балансу Вата, Пітта і Капха"]', 'listed', 'approved', NULL, NULL, '2026-08-26 16:58:40.715+00', 'bdc98ead-08d6-4869-ae09-cd154030e339', NULL, NULL, NULL, NULL, NULL, 0, 0, NULL, '["Хочете зрозуміти, що підходить саме вашому тілу, а не чергова дієта для всіх", "Плутаєтесь у порадах про харчування і не знаєте, з чого почати", "Цікавить аюрведа як система, а не набір рецептів", "Готові вчитися послідовно, у своєму темпі"]', '["Двадцять один основний урок з відео до кожного", "Теорія дош, смаків і властивостей продуктів", "Розбір денного циклу харчування і режиму", "Рецепти солодощів, дозволених на програмі"]', 'доступ до матеріалів лишається після програми', NULL, '1c365b92-7d0c-44a9-a6df-45d49c31be4c', NULL, NULL, 'course', '["nutrition"]', 21);
INSERT INTO public.lms_courses (id, slug, title, program_slug, brand, locale, translation_group_id, status, version, summary, schedule, entitlement_product_codes, created_at, updated_at, author_id, theme, cover, sort_order, tagline, results, visibility, review_status, review_note, submitted_at, approved_at, approved_by, pending_content, pending_review_status, pending_review_note, pending_submitted_at, pending_updated_at, revision_seq, draft_generation, published_revision_id, audience, format, access_note, author_note, author_profile_id, pretitle, posttitle, kind, categories, duration_days) VALUES ('0faafa48-0f49-4f38-927a-210eec33b8df', 'soul-daily-ritual', 'Soul Daily Ritual', 'soul-daily-ritual', 'centerway', 'uk', '5a909026-43ad-4e21-bb78-9d57d1d461e6', 'published', 365, '"Щоденний протокол відновлення ДИХАННЯ • ТІЛО • БАЛАНС Три короткі ритуали, які допомагають зупинитися • відчути тіло • повернутися до себе"', '{"mode": "open"}', '{course:novyi-kurs-5}', '2026-08-28 16:18:51.757402+00', '2026-09-08 15:48:08.626692+00', 'a68003e9-e804-4d1c-96d0-08b2d770a6d6', '{"scale": "generous", "palette": "herbs", "headingFont": "ui"}', '{"alt": "Це логотип програми.", "src": "https://ibqexzkvtdmvuxenmvpy.supabase.co/storage/v1/object/public/course-media/courses/0faafa48-0f49-4f38-927a-210eec33b8df/bf5329ba-c61b-4c54-b5f5-27cab2867b6c/1600.webp", "cropX": 50, "cropY": 50, "wideCropY": 68, "mobileCropX": 99, "mobileCropY": 59}', NULL, 'CENTER WAY  ×  SOULSPA', '["Три точки повернення до себе протягом дня", "Спокійніший ранок, зібраніший день, легший вечір", "Контакт із диханням і тілом без окремого заняття", "Тиждень практики, який видно у власному трекері"]', 'listed', 'approved', NULL, '2026-08-31 13:05:08.657+00', '2026-08-31 13:05:57.592+00', 'a68003e9-e804-4d1c-96d0-08b2d770a6d6', '{"id": "0faafa48-0f49-4f38-927a-210eec33b8df", "kind": "checklist", "slug": "soul-daily-ritual", "brand": "centerway", "cover": {"alt": "Це логотип програми.", "src": "https://ibqexzkvtdmvuxenmvpy.supabase.co/storage/v1/object/public/course-media/courses/0faafa48-0f49-4f38-927a-210eec33b8df/bf5329ba-c61b-4c54-b5f5-27cab2867b6c/1600.webp", "cropX": 50, "cropY": 50, "wideCropY": 68, "mobileCropX": 99, "mobileCropY": 59}, "theme": {"scale": "generous", "palette": "herbs", "headingFont": "ui"}, "title": "Soul Daily Ritual", "format": ["Текстові інструкції "], "locale": "uk", "status": "draft", "modules": [{"id": "a2d89899-ffa8-4114-9b4e-a2c3f2167713", "slug": "module-1", "order": 1, "title": "DAILY RESET ", "lessons": [{"id": "d908afe9-4250-4a2e-b6ef-c2264f93a1d8", "slug": "lesson-1", "order": 1, "title": "ЯК КОРИСТУВАТИСЯ", "blocks": [{"id": "1ac2c299-35f5-4264-8c35-8dc4fef8729a", "type": "rich_text", "content": [{"kind": "p", "text": "Цей протокол створений як проста домашня практика між процедурами, тілесними заняттями та періодами відновлення. Його ритм — м’який рух від активації вранці до фокусування вдень і заспокоєння ввечері."}]}, {"id": "04dacc60-17c5-43fe-9632-9c745ffe9e9d", "text": "ПРИНЦИП Не потрібно змінювати весь день. Іноді достатньо змінити спосіб, у який ви дихаєте.", "type": "quote", "author": "Веди"}, {"id": "3d168c22-f656-4daf-89bd-bc945728e009", "type": "rich_text", "content": [{"kind": "h3", "text": "М’яка рамка практики"}, {"kind": "ul", "items": ["Оберіть стійке, комфортне положення та залишайтеся в межах природного дихання"]}, {"kind": "ul", "items": ["Не форсуйте амплітуду, затримку або тривалість; якість важливіша за інтенсивність"]}, {"kind": "ul", "items": ["Після практики коротко відмітьте, що змінилося у вашому стані."]}]}, {"id": "a883ea9e-2ea0-4595-9c03-f9094c14bc76", "text": [{"bold": true, "text": "БЕЗПЕКА "}, {"text": "Практикуйте без болю, запаморочення чи надмірного зусилля. Якщо техніка викликає дискомфорт — припиніть її та зверніться до фахівця. Матеріал не замінює медичну консультацію. "}], "type": "boundary_note"}], "summary": "Один день. Три точки повернення. "}, {"id": "24905938-5840-4dc2-a9a4-fe8668f3f4ee", "slug": "urok-2", "order": 2, "title": "01  /  MORNING", "blocks": [{"id": "1ff32ed6-42f8-4110-b541-b3fe0daa85f5", "text": "Ранковий ритуал для м’якого пробудження тіла, уваги та дихального патерну. ", "type": "boundary_note"}, {"id": "2712110c-3bac-44fc-a463-3d3eaba0a8b0", "step": 1, "text": "Фокус: діафрагма та відчуття простору в зоні нижніх ребер.", "type": "protocol_step", "title": "Міофасціальний реліз", "timing": "Виконати 3–4 цикли."}, {"id": "0dd0250f-1881-4ffd-a408-ca1d81280e1b", "type": "rich_text", "content": [{"kind": "ul", "items": ["Лягти на спину, коліна зігнуті, стопи на підлозі.", "Зробити спокійний глибокий видих.", "М’яко розмістити пальці під реберною дугою.", "На вдиху — зменшити тиск і розслабитися.", "На видиху — дуже делікатно поглибити контакт.", "Виконати 3-4 цикли "]}]}, {"id": "911498d5-f165-4cf7-9ff3-1d882d2b39dd", "step": 2, "text": "у перекладі з санскриту — «замок зльоту/підйому» або «черевний замок». Це класичний йогічний замок (бандха), який виконується шляхом повного видиху та втягування органів черевної порожнини вгору та під ребра.", "type": "protocol_step", "title": "Уддіяна бандха", "timing": "3–5 циклів  •  затримка 5–10 секунд"}, {"id": "f15687fd-0482-4883-84ae-4a4296f6b068", "type": "rich_text", "content": [{"kind": "ul", "items": ["Стати, трохи зігнути коліна, руки — на стегна.", "Повністю видихнути.", "Затримати дихання.", "Виконати м’який «хибний вдих» без набору повітря.", "Дозволити животу втягнутися під ребра.", "Утримувати 5–10 секунд.", "Плавно відпустити та відновити дихання."]}]}, {"id": "ac9d84d3-8239-45cc-89ac-d6501f65aa57", "text": "КЛЮЧ Практика виконується без силового напруження. Язик може м’яко лежати біля верхнього піднебіння.", "type": "quote", "author": "Автор"}], "summary": "RESET • Очищення & потік "}, {"id": "9e21e8f8-87ef-4501-81f8-cce0234f9b69", "slug": "urok-3", "order": 3, "title": "02  /  DAY", "blocks": [{"id": "ad1f032e-aac0-492b-832e-d838737b3616", "text": [{"bold": true, "text": "Коротка пауза серед дня, щоб повернути увагу до тіла та зменшити темп.", "italic": true}], "type": "lesson_objective"}, {"id": "3b29c78e-ad2c-4d9f-97d8-0076b6fb39dd", "step": 1, "text": "Coherent Breathing — це техніка повільного керованого дихання, яка синхронізує дихальний цикл із серцевим ритмом і артеріальним тиском, вводячи організм у стан максимальної фізіологічної рівноваги.", "type": "protocol_step", "title": "Резонансне дихання", "timing": "5,5 сек  ВДИХ  5,5 сек ВИДИХ  10 хв РИТМ"}, {"id": "430abdb9-6dd1-4178-b4d4-846396b5a525", "text": [{"bold": true, "text": "Техніка виконання"}], "type": "lesson_objective"}, {"id": "37eefcf8-a803-4e5d-a790-5c225e778f8b", "type": "rich_text", "content": [{"kind": "ul", "items": ["Сісти з комфортною прямою спиною.", "Розслабити плечі та щелепу.", "Повільно вдихати через ніс — 5,5 секунди.", "Без паузи плавно видихати — 5,5 секунди.", "Утримувати увагу на м’якому русі нижніх ребер.", "Продовжувати 10 хвилин."]}]}, {"id": "c367c5f7-c71c-40e3-99f4-84fe06f384de", "type": "rich_text", "content": [{"kind": "p", "text": [{"bold": true, "text": "Фізіологічний ефект"}]}, {"kind": "ul", "items": ["Максимізація варіабельності серцевого ритму (HRV): Серцевий ритм починає гармонійно коливатися в унісон із диханням і коливаннями кров''яного тиску (хвилі Траубе-Херинга-Маєра).", "Балансування нервової системи: Стимулює парасимпатичну нервову систему через активацію блукаючого нерва (vagus), знижуючи рівень стресу, кортизолу та тривожності"]}, {"kind": "p", "text": "Користь: Покращує концентрацію уваги, стабілізує артеріальний тиск, знімає напругу з діафрагми та допомагає швидко відновити ресурс нервової системи. Зазвичай практикується сесіями по 5–10 хвилин на день."}]}, {"id": "d547f21b-8f87-48b2-8ba1-ea709e8d5fcc", "text": "КЛЮЧ Не намагайтеся вдихнути більше повітря. Дихання має залишатися тихим, плавним і комфортним.", "type": "quote"}], "summary": "FOCUS • Фокус & центр"}, {"id": "12b6a0fe-b4b2-4394-87b7-2043672d8957", "slug": "urok-4", "order": 4, "title": "03  /  EVENING", "blocks": [{"id": "9574012e-7a84-488e-871d-200fcf14f48c", "text": "Вечірній ритуал для уповільнення, переходу від активності до спокою та підготовки до сну.", "type": "lesson_objective"}, {"id": "79d77ab1-1d0c-4c25-8c93-1fb675167d41", "step": 1, "text": "(часто плутають або поєднують з Наді Шодхана) — це класична пранаяма змінного дихання через праву і ліву ніздрі, яка перекладається як «природне і протилежне» або «за шерстю і проти шерсті». У класичній хатха-йозі це базовий етап освоєння дихальних практик перед складнішими затримками.", "type": "protocol_step", "title": "Анулома Вілома", "timing": "Співвідношення 1 : 2  •  10–15 хвилин"}, {"id": "90f34fdc-6e82-4ba4-b088-7bf576568af7", "type": "rich_text", "content": [{"kind": "p", "text": [{"bold": true, "text": "Техніка виконання"}]}, {"kind": "p", "text": "Сядьте зручно, спина пряма без напруги. Праву руку складіть у Насагра Мудру."}, {"kind": "p", "text": "ОДИН ЦИКЛ"}, {"kind": "ul", "items": ["Закрити праву ніздрю великим пальцем.", "Вдих через ліву — 4 рахунки.", "Закрити ліву, відкрити праву.", "Видих через праву — 8 рахунків.", "Вдих через праву — 4 рахунки.", "Видих через ліву — 8 рахунків.", "Повторювати 10–15 хвилин"]}]}, {"id": "0118c6c4-05b7-4ca8-9844-4e98045e98b9", "text": [{"bold": true, "text": "Завершення:"}, {"text": " Залиштеся на кілька природних циклів дихання та дозвольте тілу перейти до спокою без додаткового зусилля. "}], "type": "quote", "author": "Автор"}, {"id": "f5c590fb-69b4-4b94-b9e8-2ff9209da392", "text": [{"bold": true, "text": "КЛЮЧ"}, {"text": " Не форсуйте довжину видиху. Якщо співвідношення 1:2 некомфортне, скоротіть рахунок, зберігаючи м’якість."}], "type": "boundary_note"}], "summary": "RESTORE • Баланс & відновлення"}, {"id": "bd551583-57e9-4c84-9bf6-fc4d011cced9", "slug": "urok-5", "order": 5, "title": "ТИЖНЕВИЙ ТРЕКЕР • 7 ДНІВ", "blocks": [{"id": "c54aa337-2df2-4821-ad78-c5b67a8bdc99", "text": "Відмічайте практику без оцінювання. Завдання трекера — бачити ритм, а не вимагати ідеальності.", "type": "lesson_objective"}, {"id": "028364d7-c852-4135-b812-afd66afd0d65", "head": ["ДЕНЬ", "MORNING", "DAY", "EVENING"], "rows": [["Понеділок", "☐", "☐", "☐"], ["Вівторок", "☐", "☐", "☐"], ["Середа", "☐", "☐", "☐"], ["Четвер ", "☐", "☐", "☐"], ["П’ятниця", "☐", "☐", "☐"], ["Субота", "☐", "☐", "☐"], ["Неділя", "☐", "☐", "☐"]], "type": "table"}], "summary": "MY DAILY RHYTHM"}, {"id": "2fc58ff6-90a8-432e-8ac1-a9c7c057d0c7", "slug": "urok-6", "order": 6, "title": "Бонус", "blocks": [{"id": "a0850379-154a-4c9a-a0ba-8642942c4ffa", "type": "video", "videoId": "uoXBYxPAOXo", "provider": "youtube", "durationMin": 12}], "summary": "Відео урок з дихальної гімнастика   "}]}], "results": ["Проста кожноденна система, що тримає в ясності", "Три блоки дихальних вправ: ранок, день, вечір", "М''яке пробудження, ясність розуму, спокійний фокус", "Система, без зайвих витрат часу "], "summary": "Щоденний протокол відновлення ДИХАННЯ • ТІЛО • БАЛАНС Три короткі ритуали, які допомагають зупинитися • відчути тіло • повернутися до себе", "tagline": "CENTER WAY  ×  SOULSPA", "version": 366, "audience": ["Молодим мамам, що потребують особливої уваги", "Людям що працюють у складних графіках", "Всім, кому потрібна чітка система "], "schedule": {"mode": "open"}, "visibility": "listed", "programSlug": "soul-daily-ritual", "translationGroupId": "5a909026-43ad-4e21-bb78-9d57d1d461e6", "entitlementProductCodes": ["course:novyi-kurs-5"]}', 'draft', NULL, NULL, '2026-09-05 07:25:53.29+00', 0, 396, NULL, '["Ви хочете зупинятися серед дня, а не тільки ввечері", "День іде на автоматі, а тіло згадується, лише коли болить", "Потрібен короткий ритуал, а не ще одна довга програма", "Підходить будь-кому — це три точки повернення в звичайному дні"]', '["Три короткі ритуали: ранок, день, вечір", "Інструкція, як користуватися протоколом", "Тижневий трекер на сім днів", "Бонус: відеоурок з дихальної гімнастики"]', 'доступ до матеріалів лишається після курсу', NULL, '1c365b92-7d0c-44a9-a6df-45d49c31be4c', NULL, NULL, 'checklist', '["movement"]', NULL);
INSERT INTO public.lms_courses (id, slug, title, program_slug, brand, locale, translation_group_id, status, version, summary, schedule, entitlement_product_codes, created_at, updated_at, author_id, theme, cover, sort_order, tagline, results, visibility, review_status, review_note, submitted_at, approved_at, approved_by, pending_content, pending_review_status, pending_review_note, pending_submitted_at, pending_updated_at, revision_seq, draft_generation, published_revision_id, audience, format, access_note, author_note, author_profile_id, pretitle, posttitle, kind, categories, duration_days) VALUES ('b7e6f2a1-0000-4000-8000-000000000001', 'reset-day', 'Розвантажувальний день — практикум з умовного голодування', 'reset-day', 'centerway', 'uk', 'reset-day', 'published', 12, '"Один розвантажувальний день — це три дні уваги та дисципліни: підготовка, сам день і коректний вихід."', '{"mode": "open"}', '{reset-day,mini-detox}', '2026-08-15 14:04:44.229989+00', '2026-09-08 15:24:03.564088+00', NULL, NULL, '{"alt": "Обкладинка практикуму «Розвантажувальний день»", "src": "/cw/platform/programs/reset-day-hero-desktop-v2.webp", "cropX": 66, "cropY": 50, "mobileSrc": "/cw/platform/programs/reset-day-card-v1.png", "mobileCropX": 50, "mobileCropY": 15}', 2, 'Вийти з кола «стрес → їжа → провина» за три дні', '["Спокій замість тривоги вже наприкінці дня", "Легкість у тілі й більше енергії", "Повертається смак до їжі, а провина після неї зникає", "Відчуття, що керуєте ви, а не їжа"]', 'listed', 'approved', NULL, NULL, '2026-08-22 14:28:55.65551+00', NULL, '{"id": "b7e6f2a1-0000-4000-8000-000000000001", "kind": "mini", "slug": "reset-day", "brand": "centerway", "cover": {"alt": "Обкладинка практикуму «Розвантажувальний день»", "src": "/cw/platform/programs/reset-day-hero-desktop-v2.webp", "cropX": 66, "cropY": 50, "mobileSrc": "/cw/platform/programs/reset-day-card-v1.png", "mobileCropX": 50, "mobileCropY": 15}, "title": "Розвантажувальний день — практикум з умовного голодування", "format": ["Стратегія трьох днів — покроковий план, що і коли робити", "Чек-лист голодування, щоб пройти день без зривів", "Дихальна гімнастика, яка знімає тягу заїдати стрес", "Рецепти-солодощі без стрибків інсуліну", "Відео-інструкції на кожному кроці", "6 варіантів адаптації під ваш стан"], "locale": "uk", "status": "draft", "modules": [{"id": "b7e6f2a1-0000-4000-8000-000000000011", "slug": "before-start", "order": 1, "title": "Перед стартом", "lessons": [{"id": "b7e6f2a1-0000-4000-8000-000000000100", "slug": "intro", "order": 1, "title": "Технічна інформація по проходженню практикуму", "blocks": [{"id": "intro-objective", "text": "Перед стартом: як влаштований практикум, де підтримка і що важливо розуміти про сам формат.", "type": "lesson_objective"}, {"id": "intro-boundary-main", "text": "Один розвантажувальний день — це три дні уваги та дисципліни. Некоректно починати голодування чи умовне голодування, не підготувавшись до нього належним чином. У деяких випадках необхідна консультація фахівця. В іншому випадку — ви можете собі нашкодити.", "type": "boundary_note"}, {"id": "intro-video", "type": "video", "title": "Вітальне відео", "videoId": "KzIq5GgcyvA", "provider": "youtube"}, {"id": "intro-support", "type": "rich_text", "content": [{"kind": "h3", "text": "Технічні непорозуміння по практикуму"}, {"kind": "p", "text": "Якщо у вас виникнуть технічні непорозуміння по проходженню практикуму на платформі, не будуть відкриватися уроки чи виникнуть проблеми зі входом у кабінет — одразу напишіть у телеграм."}]}, {"id": "intro-support-cta", "href": "https://telegram.me/centerway_support_bot", "type": "cta", "label": "Технічна підтримка CenterWay"}], "summary": "Прочитайте обов''язково.", "durationMin": 6}, {"id": "b7e6f2a1-0000-4000-8000-000000000104", "slug": "routine", "order": 2, "title": "Розпорядок дня для 1, 2 і 3 етапу", "blocks": [{"id": "routine-objective", "text": "Цей розпорядок діє всі три дні практикуму. Час прийому їжі відрізняється за конституцією — знайди свій розділ.", "type": "lesson_objective"}, {"id": "routine-video", "type": "video", "title": "Про розпорядок дня", "videoId": "CrqxIvVQZ04", "provider": "youtube"}, {"id": "routine-step-1", "step": 1, "type": "protocol_step", "title": "Раннє пробудження, гігієна", "timing": "до 07:00"}, {"id": "routine-step-2", "step": 2, "type": "protocol_step", "title": "2 склянки теплої води і дихальна гімнастика", "timing": "після пробудження"}, {"id": "routine-meals-vata", "type": "rich_text", "content": [{"kind": "h3", "text": "Час прийому їжі — для Вата доші"}, {"kind": "p", "text": [{"bold": true, "text": "Варіант 1. "}, {"text": "До 8:30 сніданок — через 3 години перекус — 12:00-14:00 обід — через 3 години перекус — 18:00-20:00 вечеря. Останній прийом їжі не пізніше, ніж за 2 години до сну."}]}, {"kind": "p", "text": [{"bold": true, "text": "Варіант 2. "}, {"text": "До 8:30 сніданок — через 3 години другий сніданок — 12:00-14:00 обід — через 3 години другий обід — 18:00-20:00 вечеря. Останній прийом їжі не пізніше, ніж за 2 години до сну. Відмінність цієї концепції в тому, що ми ділимо їжу рівномірно на 5 прийомів."}]}]}, {"id": "routine-meals-pitta", "type": "rich_text", "content": [{"kind": "h3", "text": "Час прийому їжі — для Пітта доші"}, {"kind": "p", "text": "До 8:30 сніданок — 12:00-14:00 обід — 18:00-20:00 вечеря. Останній прийом їжі не пізніше, ніж за 2 години до сну."}, {"kind": "p", "text": "Перекуси можуть мати місце за умови додаткових фізичних навантажень і у випадку, якщо вам це рекомендовано на першій консультації."}]}, {"id": "routine-meals-kapha", "type": "rich_text", "content": [{"kind": "h3", "text": "Час прийому їжі — для Капха доші"}, {"kind": "p", "text": "До 11:00 тільки пиття — 11:00-13:00 перший і основний прийом їжі за добу — 18:00 легка вечеря. Додаткові прийоми їжі небажані."}]}, {"id": "routine-sleep", "type": "rich_text", "content": [{"kind": "h3", "text": "Час сну"}, {"kind": "p", "text": "Лягаємо спати не пізніше 23:00, при цьому вимикаємо всі екрани."}, {"kind": "p", "text": "Протягом дня намагаємося не працювати, лежачи у спальні. Ваш розум повинен чітко знати, що ліжко — це місце для сну."}, {"kind": "h3", "text": "Тривалість сну"}, {"kind": "p", "text": "7-10 годин у залежності від ваших конституційних особливостей, пори року і наявності патологічних процесів. Максимально пізній час для пробудження — 08:00."}, {"kind": "ul", "items": [[{"bold": true, "text": "Вата"}, {"text": " — 7 годин."}], [{"bold": true, "text": "Пітта"}, {"text": " — 8 годин."}], [{"bold": true, "text": "Капха"}, {"text": " — 8-10 годин."}]]}]}], "summary": "Спільна основа для всіх трьох етапів: пробудження, час прийому їжі за конституцією, сон.", "durationMin": 9}], "summary": "Технічні моменти і розпорядок дня, спільний для всіх трьох етапів. Прочитай до того, як почнеш."}, {"id": "b7e6f2a1-0000-4000-8000-000000000010", "slug": "route", "order": 2, "title": "Три етапи", "lessons": [{"id": "b7e6f2a1-0000-4000-8000-000000000101", "slug": "day-1", "order": 1, "title": "Етап 1. Підготовка", "blocks": [{"id": "d1-objective", "text": "Сьогодні ти готуєш тіло до розвантажувального дня: правильний ранок і вечеря з достатньою кількістю клітковини.", "type": "lesson_objective"}, {"id": "d1-morning-head", "type": "rich_text", "content": [{"kind": "h3", "text": "Ранок"}]}, {"id": "d1-step-1", "step": 1, "text": [{"text": "П''ємо 2 склянки теплої води — обов''язково теплої. Можна додати "}, {"bold": true, "text": "лимон"}, {"text": " (для Вата доші), "}, {"bold": true, "text": "мед"}, {"text": " (для Пітта і Капха доші), "}, {"bold": true, "text": "соду"}, {"text": " (для Капха доші, допустимо для Пітта доші, під контролем фахівця — для Вата доші)."}], "type": "protocol_step", "title": "2 склянки теплої води", "timing": "після пробудження"}, {"id": "d1-step-2", "step": 2, "text": "Можна розтягнути на 30 хвилин. Після того, як вода випита, переходимо до дихальних вправ.", "type": "protocol_step", "title": "П''ємо спокійно, не поспішаючи", "timing": "до 30 хвилин"}, {"id": "d1-breathing-video", "type": "video", "title": "Дихальна гімнастика", "videoId": "bl2IeHS1YH8", "provider": "youtube"}, {"id": "d1-evening-head", "type": "rich_text", "content": [{"kind": "h3", "text": "Вечір"}, {"kind": "p", "text": "Вечеря напередодні розвантажувального дня повинна містити достатню кількість клітковини і відбутися не пізніше 18:00."}, {"kind": "h3", "text": "Варіанти вечері напередодні"}]}, {"id": "d1-dinner-1", "text": "Вживати з топленим маслом (Вата, Пітта). Сира морква або печена, але вживаємо без масла — для Капха доші.", "type": "practice_block", "title": "1. Запечена морква"}, {"id": "d1-dinner-2", "text": "Печемо або варимо в «мундирі» буряк, моркву, ріпу, селеру, топінамбур, яблука (всі конституції).", "type": "practice_block", "title": "2. Овочі в «мундирі»"}, {"id": "d1-dinner-3", "text": "Гарбузовий чи морквяний суп-пюре (Пітта і Вата).", "type": "practice_block", "title": "3. Суп-пюре"}, {"id": "d1-dinner-4", "text": "Для Капха доші можна зробити огірковий суп — рецепт у розділі «Рецепти супів».", "type": "practice_block", "title": "4. Огірковий суп"}, {"id": "d1-recipes-cta", "href": "/learn/reset-day/recipes", "text": "Усі рецепти супів для підготовки і розвантажувального дня.", "type": "cta", "label": "Відкрити рецепти"}, {"id": "d1-checklist", "type": "checklist", "items": [{"id": "d1-c1", "text": "Ранок: 2 склянки теплої води випито спокійно"}, {"id": "d1-c2", "text": "Зроблено дихальну гімнастику"}, {"id": "d1-c3", "text": "Вечеря була овочевою і не пізніше 18:00"}, {"id": "d1-c4", "text": "Я обрав(-ла) варіант розвантажувального дня і підготував(-ла) продукти"}], "title": "Чек-лист підготовки", "requiredForCompletion": true}, {"id": "d1-boundary", "text": "Якщо у вашому випадку після овочевої вечері зранку немає дефекації — зверніться до фахівця. У подальшому ми повинні виправити цей недолік.", "type": "boundary_note"}], "summary": "Ранок на теплій воді і диханні, ввечері — овочева вечеря до 18:00.", "dayIndex": 1, "durationMin": 12}, {"id": "b7e6f2a1-0000-4000-8000-000000000102", "slug": "day-2", "order": 2, "title": "Етап 2. Розвантажувальний день (умовне голодування)", "blocks": [{"id": "d2-objective", "text": "Сьогодні ти проходиш розвантажувальний день за одним із шести варіантів. Обери варіант зранку — і далі жодних рішень.", "type": "lesson_objective"}, {"id": "d2-video", "type": "video", "title": "Про розвантажувальний день", "videoId": "g2KPHmoO0wI", "provider": "youtube"}, {"id": "d2-intro", "type": "rich_text", "content": [{"kind": "p", "text": "У даному мануалі представлені варіанти розвантажувального дня, без екстриму. Більш складні варіанти необхідно проводити після індивідуальної консультації."}, {"kind": "h3", "text": "Варіанти розвантажувального дня"}]}, {"id": "d2-variant-1", "text": "Протягом дня їмо тільки рис басматі з топленим маслом. Дозволено не гострі спеції. Їжу можна вживати кожні 3 години, але потроху, якщо хочеться їсти, та 2-3 рази, якщо їсти не хочеться. Вечеря о 18:00 — печена морква. Питний режим: 1 раз на годину 30-120 мл теплої води. Цей варіант можуть виконувати всі без виключення, у тому числі й діти. Рекомендовано для Вата доші.", "type": "practice_block", "title": "1. Рис басматі з топленим маслом"}, {"id": "d2-variant-2", "text": "Весь день їмо овочевий суп (вибираємо до 5-ти овочів). Їжу можна вживати кожні 3 години, але потроху. Вечеря о 18:00 — печена морква. Питний режим: 1 раз на годину 30-120 мл теплої води. Цей варіант можуть виконувати всі без виключення, у тому числі й діти.", "type": "practice_block", "title": "2. Овочевий суп"}, {"id": "d2-variant-3", "text": "Будь-який сирий овоч чи фрукт. Можна вживати кожну годину 1 плід. Вибираємо овочі і фрукти у відповідності до своєї індивідуальної конституції. Питний режим: 1 раз на годину 30-120 мл теплої води або води кімнатної температури (для Пітта доші).", "type": "practice_block", "title": "3. Сирий овоч або фрукт"}, {"id": "d2-variant-4", "text": [{"text": "Сік вживаємо у порції 350 мл 1 раз на 1-3 години. Також можна пити теплу воду у відповідності із рекомендаціями вище. "}, {"bold": true, "text": "Вата доша: "}, {"text": "морква, буряк, апельсин, гарбуз, виноград, гранат, абрикоса, персик. "}, {"bold": true, "text": "Пітта доша: "}, {"text": "яблуко, зелень, гранат, виноград, морква, буряк, картопля. "}, {"bold": true, "text": "Капха доша: "}, {"text": "зелень, гранат, зелене яблуко, огірок, капуста."}], "type": "practice_block", "title": "4. Соковий день"}, {"id": "d2-variant-5", "text": "Весь день проводимо на теплій воді і трав''яних чаях. В воду можна додавати мед або топлене масло — не змішувати. У випадку сильної слабкості чи головного болю увечері їмо овочевий суп. У такий день увечері гарно прийняти теплу ванну (для інших варіантів це також рекомендовано).", "type": "practice_block", "title": "5. Тепла вода і трав''яні чаї"}, {"id": "d2-variant-6", "text": "Весь день тільки на воді і трав''яних чаях.", "type": "practice_block", "title": "6. Тільки вода і трав''яні чаї"}, {"id": "d2-teas", "type": "rich_text", "content": [{"kind": "h3", "text": "Трав''яні чаї для 5 і 6 варіанту"}, {"kind": "p", "text": [{"bold": true, "text": "Трав''яний збір: "}, {"text": "насіння кропу, кмину, фенхелю і листя меліси. Усе змішуємо 1 до 1, потім подрібнюємо і настоюємо 5 ч.л. на 1 літр води (температура води 80 градусів), далі настоюємо в термосі 40 хв і вживаємо протягом дня, як чай."}]}, {"kind": "p", "text": [{"bold": true, "text": "Або чай з куркуми: "}, {"text": "1 ч.л. куркуми заливаємо 1 л води температурою 80 градусів, настоюємо 40 хв і вживаємо протягом дня, як чай."}]}]}, {"id": "d2-recipes-cta", "href": "/learn/reset-day/recipes", "text": "Рецепти супів для розвантажувального дня.", "type": "cta", "label": "Відкрити рецепти"}, {"id": "d2-checklist", "type": "checklist", "items": [{"id": "d2-c1", "text": "Я обрав(-ла) варіант зранку й не змінював(-ла) його протягом дня"}, {"id": "d2-c2", "text": "Питний режим дотриманий"}, {"id": "d2-c3", "text": "Вечір пройшов спокійно, без «доїдання» перед сном"}], "title": "Чек-лист розвантажувального дня", "requiredForCompletion": true}, {"id": "d2-boundary", "text": "Більш складні варіанти розвантажувального дня можливі лише після того, як вам стало абсолютно комфортно проводити день на воді.", "type": "boundary_note"}], "summary": "Шість варіантів проходження дня — обери один і не змінюй його протягом дня.", "dayIndex": 2, "durationMin": 16}, {"id": "b7e6f2a1-0000-4000-8000-000000000103", "slug": "day-3", "order": 3, "title": "Етап 3. Вихід", "blocks": [{"id": "d3-objective", "text": "Сьогодні ти виходиш із розвантажувального дня. Варіант виходу залежить від того, який варіант дня ти проходив(-ла).", "type": "lesson_objective"}, {"id": "d3-video", "type": "video", "title": "Про вихід", "videoId": "yhST6Ew48Zo", "provider": "youtube"}, {"id": "d3-step-1", "step": 1, "type": "protocol_step", "title": "Теплий душ", "timing": "вранці"}, {"id": "d3-exit-common", "type": "rich_text", "content": [{"kind": "h3", "text": "Варіанти виходу"}, {"kind": "p", "text": "У всіх випадках, крім першого і шостого, снідаємо розварений рис басматі."}, {"kind": "p", "text": "У першому варіанті на сніданок їмо будь-яку звичну для вас їжу, крім кави."}]}, {"id": "d3-exit-six", "type": "rich_text", "content": [{"kind": "h3", "text": "Вихід після шостого варіанту"}, {"kind": "p", "text": [{"bold": true, "text": "Самсараяна крама"}, {"text": " — градуйована дієта:"}]}, {"kind": "ol", "items": [[{"bold": true, "text": "Манда"}, {"text": " — рисовий відвар"}], [{"bold": true, "text": "Пейя"}, {"text": " — рисовий суп"}], [{"bold": true, "text": "Вілепі"}, {"text": " — густий рисовий суп"}], [{"bold": true, "text": "Одана"}, {"text": " — варений рис"}], [{"bold": true, "text": "Юша"}, {"text": " — суп з машу"}], [{"bold": true, "text": "Кічарі"}, {"text": " — суміш рису з машем"}]]}, {"kind": "p", "text": "Маш (Mung Bean) є традиційною культурою, яка вирощується в Південній та Східній Азії вже протягом тисячоліть. Ймовірно, маш має своє походження в Індії, де він вперше був вирощений більше 4 000 років тому."}]}, {"id": "d3-checklist", "type": "checklist", "items": [{"id": "d3-c1", "text": "Вранці прийнято теплий душ"}, {"id": "d3-c2", "text": "Сніданок відповідав моєму варіанту виходу"}, {"id": "d3-c3", "text": "Я не компенсував(-ла) вчорашній день"}], "title": "Чек-лист виходу", "requiredForCompletion": true}, {"id": "d3-boundary", "text": "Правильний вихід — запорука успіху. Некоректний вихід може призвести до неприємних наслідків.", "type": "boundary_note"}, {"id": "d3-faq", "type": "faq_block", "items": [{"id": "d3-faq-1", "answer": "Доступ лишається назавжди — повторюй тоді, коли відчуваєш потребу, а не за розкладом.", "question": "Як часто можна повторювати цей цикл?"}, {"id": "d3-faq-2", "answer": "Якщо відчуваєш, що готовий(-а) до глибшого рівня — наступний крок це «Шлях 21», повна 21-денна програма очищення.", "question": "Що далі після цього циклу?"}]}, {"id": "d3-next", "href": "/programs/way21", "text": "Сподобалась легкість? Є глибший рівень.", "type": "cta", "label": "Подивитись «Шлях 21»"}], "summary": "Правильний вихід — запорука успіху. Некоректний вихід може призвести до неприємних наслідків.", "dayIndex": 3, "durationMin": 10}], "summary": "Підготовка, розвантажувальний день і вихід. Прочитай усі три етапи наперед — до другого дня треба підготуватись заздалегідь."}, {"id": "b7e6f2a1-0000-4000-8000-000000000012", "slug": "materials", "order": 3, "title": "Додаткові матеріали", "lessons": [{"id": "b7e6f2a1-0000-4000-8000-000000000105", "slug": "recipes", "order": 1, "title": "Рецепти супів", "blocks": [{"id": "rec-objective", "text": "П''ять супів для підготовки і для розвантажувального дня. Кожен рецепт позначено за конституцією — обери свій.", "type": "lesson_objective"}, {"id": "rec-1", "type": "rich_text", "content": [{"kind": "h3", "text": "1. Легке огіркове гаспачо"}, {"kind": "p", "text": "Рецепт на 2-4 порції."}, {"kind": "p", "text": "Варимо в ідеалі на пару: 1 свіжий лук порей і 1 зубчик часнику — давленого. Варимо 5 хв, щоб знизити гостроту з овочів. Далі чистимо від шкіри 3 середні огірки і ріжемо їх великими скибками. Беремо ½ стакану дрібно нарізаної петрушки."}, {"kind": "p", "text": "Скласти огірки, петрушку, лук порей, часник у блендер і додати:"}, {"kind": "ul", "items": ["Сік 1 лимону", "1 склянка охолодженого бульйону від овочів", "3-5 с.л оливкової олії", "сіль за смаком, але все одно трошки", "⅛ ч.л каєнського перцю", "⅛ ч.л чорного перцю"]}, {"kind": "p", "text": "Збити в блендері 30-60 сек, до однорідної маси."}, {"kind": "p", "text": [{"bold": true, "text": "Рецепт гарно підходить Капха доші"}, {"text": ", не зловживаючи — для Вати і Пітти."}]}]}, {"id": "rec-2", "type": "rich_text", "content": [{"kind": "h3", "text": "2. Суп із брокколі"}, {"kind": "p", "text": "Рецепт на 2-4 порції."}, {"kind": "p", "text": "Варимо в ідеалі на пару: 1-2 склянки нарізаного брокколі, включаючи верхню частину ніжки. 1 ст.л нарізаного луку порей або звичайний лук (лук не обов''язково). Варимо 3-5 хв."}, {"kind": "p", "text": "Складаємо в блендер:"}, {"kind": "ul", "items": ["2 ст.л сирих волоських горіхів чи кешью", "Сіль за смаком"]}, {"kind": "p", "text": "Гомогенізуємо горіхи і додаємо варені овочі, подрібнюємо до однорідної консистенції. Можна додати перець за смаком."}, {"kind": "p", "text": [{"bold": true, "text": "Рецепт підходить всім конституціям."}]}]}, {"id": "rec-3", "type": "rich_text", "content": [{"kind": "h3", "text": "3. Поживний овочевий суп"}, {"kind": "p", "text": "Рецепт на 4 порції."}, {"kind": "ul", "items": ["½ склянки ячмінної крупи", "8-10 склянок чистої води", "1 ч.л лаврового листа", "1 ч.л солі, чи за смаком"]}, {"kind": "p", "text": "Поки все вариться, додаємо:"}, {"kind": "ul", "items": ["2 моркви нарізані і ненарізана зелень від моркви — її можна не їсти, але вона надасть приємний смак і корисні властивості", "2 пучка селери дрібно нарізати", "1 склянка нарізаної петрушки", "2 ст.л нарізаного луку (необов''язково)", "1 зубок часнику, не очищений від шкіри", "1-3 склянки картоплі або ріпи (для Капхи точно ріпа)"]}, {"kind": "p", "text": "Варите 40-50 хв, потім додати:"}, {"kind": "ul", "items": ["1 невеликий пучок шпинату", "½ ч.л сушеного чебрецю", "чорний перець за смаком"]}, {"kind": "p", "text": "Після цього ще варити 2-5 хв і в кінці можна додати гхі, особливо для Вата доші."}, {"kind": "p", "text": [{"bold": true, "text": "Добре підходить Вата конституції"}, {"text": ", гарно для ослабленої Пітта конституції, для Капхи — без гхі і картоплі. Не екадашний рецепт."}]}]}, {"id": "rec-4", "type": "rich_text", "content": [{"kind": "h3", "text": "4. Суп «шатаварі»"}, {"kind": "p", "text": "Рецепт на 4 порції."}, {"kind": "p", "text": "Тушити декілька хвилин у сковорідці з товстим дном:"}, {"kind": "ul", "items": ["1 невелика цибулина", "2 зубчики часнику, давленого", "2 стакана різаної спаржі"]}, {"kind": "p", "text": "Тушимо на невеликій кількості топленого масла гхі. Додаємо 4 склянки води і варити 30-40 хв, або менше, до приємного стану."}, {"kind": "p", "text": "В цей час подрібнюємо ½ склянки соняшникового насіння. Коли овочі готові, додаємо бульйон у насіння і повільно перемішуємо у блендері; овочі також можна подрібнити або залишити цілими."}, {"kind": "p", "text": "У кінці додаємо сіль та перець за смаком та ¼ подрібненого мускатного горіха."}, {"kind": "p", "text": [{"bold": true, "text": "Підходить всім конституціям"}, {"text": ", Вата дошу укріплює."}]}]}, {"id": "rec-5", "type": "rich_text", "content": [{"kind": "h3", "text": "5. Буряковий суп «Борщ»"}, {"kind": "p", "text": "Рецепт на 2 порції."}, {"kind": "p", "text": "У чотирьох склянках води варимо 3 середні, дрібно нарізані буряки — якщо молоді, то можна з бадиллям. 1 см кореня імбиру, очищеного. Накрити кришкою і варити приблизно 40 хв."}, {"kind": "p", "text": "Коли готово, у блендері подрібнюємо до консистенції густого супу. Додаємо сіль, перець за смаком. Оливкову олію першого холодного віджиму — 1-3 ст.л."}, {"kind": "p", "text": [{"bold": true, "text": "Підходить всім конституціям."}]}]}], "summary": "Рецепти супів для проведення розвантажувального дня в аюрведичній концепції.", "durationMin": 8}], "summary": "Довідник, до якого повертаєшся під час підготовки і самого дня.", "reference": true}], "results": ["Спокій замість тривоги вже наприкінці дня", "Легкість у тілі й більше енергії", "Повертається смак до їжі, а провина після неї зникає", "Відчуття, що керуєте ви, а не їжа"], "summary": "Один розвантажувальний день — це три дні уваги та дисципліни: підготовка, сам день і коректний вихід.", "tagline": "Вийти з кола «стрес → їжа → провина» за три дні", "version": 13, "audience": ["Заїдаєте стрес: емоції тягнуть до холодильника, навіть коли ви не голодні", "У харчуванні немає ритму — то переїдання, то пропущені прийоми", "Тіло важке, енергії немає, а настрій стрибає протягом дня", "Хочете почати з м''якого кроку, а не з жорсткої дієти"], "schedule": {"mode": "open"}, "posttitle": "практикум з умовного голодування", "sortOrder": 2, "accessNote": "доступ назавжди", "authorNote": "Цей 3-денний формат я зібрав як найм''якший перший крок до здорових стосунків із їжею.", "categories": ["nutrition", "cleansing"], "visibility": "listed", "programSlug": "reset-day", "durationDays": 3, "translationGroupId": "reset-day", "entitlementProductCodes": ["reset-day", "mini-detox"]}', 'changes_requested', 'Потрібні зміни', '2026-08-31 13:11:09.149+00', '2026-08-31 13:03:03.192+00', 1, 27, NULL, '["Заїдаєте стрес: емоції тягнуть до холодильника, навіть коли ви не голодні", "У харчуванні немає ритму — то переїдання, то пропущені прийоми", "Тіло важке, енергії немає, а настрій стрибає протягом дня", "Хочете почати з м''якого кроку, а не з жорсткої дієти"]', '["Стратегія трьох днів — покроковий план, що і коли робити", "Чек-лист голодування, щоб пройти день без зривів", "Дихальна гімнастика, яка знімає тягу заїдати стрес", "Рецепти-солодощі без стрибків інсуліну", "Відео-інструкції на кожному кроці", "6 варіантів адаптації під ваш стан"]', 'доступ назавжди', 'Цей 3-денний формат я зібрав як найм''якший перший крок до здорових стосунків із їжею.', '1c365b92-7d0c-44a9-a6df-45d49c31be4c', NULL, 'практикум з умовного голодування', 'mini', '["nutrition", "cleansing"]', 3);
INSERT INTO public.lms_courses (id, slug, title, program_slug, brand, locale, translation_group_id, status, version, summary, schedule, entitlement_product_codes, created_at, updated_at, author_id, theme, cover, sort_order, tagline, results, visibility, review_status, review_note, submitted_at, approved_at, approved_by, pending_content, pending_review_status, pending_review_note, pending_submitted_at, pending_updated_at, revision_seq, draft_generation, published_revision_id, audience, format, access_note, author_note, author_profile_id, pretitle, posttitle, kind, categories, duration_days) VALUES ('a3f1c7d2-0000-4000-8000-000000000001', 'short', 'Short-Перезавантаження', 'reboot', 'centerway', 'uk', 'short', 'published', 2, '"Тілесний міні-курс на сім днів: комплекс гімнастики на 10 хвилин, ранковий очисний і вечірній заспокійливий дихальні комплекси та докладні розбори технік."', '{"gate": "soft", "mode": "daily", "start": "purchase", "reminderHour": 9}', '{short,reboot}', '2026-08-26 19:13:01.64095+00', '2026-09-08 15:24:03.955794+00', NULL, NULL, '{"alt": "Обкладинка міні-курсу «Short-Перезавантаження»", "src": "/cw/platform/programs/reboot-hero-desktop-v2.webp", "cropX": 68, "cropY": 50, "mobileSrc": "/cw/platform/programs/reboot-card-v1.png", "mobileCropX": 50, "mobileCropY": 18}', 1, 'Десять хвилин на день, з яких починається практика.', '["Менше стресу і спокійніший сон уже за перший тиждень", "Більше енергії протягом дня, без провалів після обіду", "Менше скутості в шиї, плечах і спині — повертається амплітуда", "Спосіб перезавантажитись за десять хвилин у будь-який момент дня"]', 'listed', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 5, NULL, '["Біль і скутість у спині, шиї чи плечах від сидячої роботи", "Стрес і тривожність, які тіло тримає в напрузі", "Постійна втома й поганий сон, а на зал немає ні часу, ні сил", "Будь-який вік і будь-яка форма — удома, без обладнання"]', '["Комплекс «Перезавантаження» — базові десять хвилин на день", "Ранковий очисний і вечірній заспокійливий дихальні комплекси", "Шість відео, з них три — докладні розбори техніки", "П''ятнадцять вправ і технік з покроковим описом", "Три чек-листи-нагадувалки й дайджест усіх матеріалів"]', 'доступ назавжди', NULL, NULL, NULL, NULL, 'mini', '["movement"]', 7);
