INSERT INTO public.lms_modules (id, course_id, slug, title, "order", summary, created_at, updated_at, reference) VALUES ('b7e6f2a1-0000-4000-8000-000000000011', 'b7e6f2a1-0000-4000-8000-000000000001', 'before-start', 'Перед стартом', 1, '"Технічні моменти і розпорядок дня, спільний для всіх трьох етапів. Прочитай до того, як почнеш."', '2026-08-17 08:38:55.06062+00', '2026-09-08 15:24:03.375422+00', false);
INSERT INTO public.lms_modules (id, course_id, slug, title, "order", summary, created_at, updated_at, reference) VALUES ('b7e6f2a1-0000-4000-8000-000000000010', 'b7e6f2a1-0000-4000-8000-000000000001', 'route', 'Три етапи', 2, '"Підготовка, розвантажувальний день і вихід. Прочитай усі три етапи наперед — до другого дня треба підготуватись заздалегідь."', '2026-08-15 14:04:44.649201+00', '2026-09-08 15:24:03.375422+00', false);
