INSERT INTO public.lms_modules (id, course_id, slug, title, "order", summary, created_at, updated_at, reference) VALUES ('7be10864-7465-5aa6-8569-af9766770368', 'fb5d1cf1-05b4-552a-9794-cf14a20e85f6', 'nutrition', 'Харчування і ритм дня', 3, '"Властивості продуктів, поєднання, добові цикли і побудова денного харчування."', '2026-08-23 17:45:06.94052+00', '2026-09-08 15:24:02.831778+00', false);
