INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('cc7b01ee-0101-4000-8000-000000000002', 'cc7b01ee-0000-4000-8000-000000000001', 'cc7b01ee-0100-4000-8000-000000000001', 'exercise-description', 'Опис вправ', 2, NULL, NULL, NULL, '[{"id": "exercise-description-text-1", "type": "rich_text", "content": [{"kind": "h3", "text": "Інтегральна відновлювальна енергомоделююча гімнастика"}, {"kind": "p", "text": "Опис вправ"}, {"kind": "p", "text": "1 частина"}, {"kind": "p", "text": "Виділення енергії та прокачування енергетичних насосів"}, {"kind": "p", "text": "1. Вправа"}, {"kind": "p", "text": "Обертання на п''ятах, руки в сторони"}, {"kind": "p", "text": "Основна позиція - стоячи прямо, руки прямі в сторони долонями вгору."}, {"kind": "p", "text": "Повертаємось праворуч на місці, дрібно переступаючи ногами з пальців в п''яту 24-32 рази до злиття видимого в одну лінію, потім повільно, але впевнено зупиняємось і опускаємо руки."}, {"kind": "p", "text": "2. Вправа"}, {"kind": "p", "text": "Підняття прямих ніг лежачи, підборіддя до грудей"}, {"kind": "p", "text": "Основна позиція – лежачи на спині, руки прямі вздовж тіла долонями до підлоги."}, {"kind": "p", "text": "На вдиху одночасно підіймаємо прямі ноги, максимально натягуючи пальці на себе і не відриваючи від підлоги поперек, та підіймаємо голову, притискаючи підборіддя до грудей. На видиху – опускаємо. 12 разів"}, {"kind": "p", "text": "3. Вправа"}, {"kind": "p", "text": "Прогинання назад, стоячи на колінах та пальцях ніг."}, {"kind": "p", "text": "Основна позиція - стоячи на колінах і пальцях ніг, долони з притиснутими пальцями під сідницями, підборіддя притиснуте до грудей."}, {"kind": "p", "text": "На вдиху вигинаємось назад, закидаючи голову, на видиху - повертаємося у вихідне положення, 12 разів"}, {"kind": "p", "text": "4. Вправа"}, {"kind": "p", "text": "Підняття корпусу \"лавка\""}, {"kind": "p", "text": "Основна позиція – сидячи на підлозі, ноги та корпус прямі, руки прямі вздовж тулуба долонями на підлозі, пальці притиснуті та спрямовані вперед."}, {"kind": "p", "text": "На вдиху піднімаємо таз вгору, коліна під 90 град, стопи притиснуті до підлоги, руки прямо долонями до підлоги, корпус рівний, паралельно до підлоги, голова відкинута назад. На видиху повертаємось у вихідне положення. 12 разів"}, {"kind": "p", "text": "5. Вправа"}, {"kind": "p", "text": "Прогин спини - згинання з опорою на прямі ноги та руки - \"індійські віджимання\""}, {"kind": "p", "text": "Вихідна позиція – у нахилі, руки прямі приблизно за метр перед собою, пальці притиснуті, спрямовані вперед, долони на підлозі, ноги прямі на ширині плечей, стопи притиснуті до підлоги, підборіддя притиснуте до грудей."}, {"kind": "p", "text": "Робимо вдих і розгинаємось, не відриваючи долонь та стоп від підлоги, ноги та руки прямі, спина прогинається назад, голова максимально відхиляється назад. Робимо видих і повертаємось у вихідне положення. 12 разів"}]}, {"id": "exercise-description-text-2", "type": "rich_text", "content": [{"kind": "p", "text": "2 частина"}, {"kind": "p", "text": "Наповнення та перерозподіл енергії"}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Формування енергетичної оболонки"}, {"kind": "p", "text": "Початкова позиція – стоячи, ноги на ширині плечей. Нахиляємося вниз, руками «зачерпуємо» енергію і на вдиху підіймаємо вгору над головою, на видиху – опускаємо долонями вниз. Руки торкаються підлоги. Спочатку робимо з боків, потім попереду себе і потім позаду себе."}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Наповнення енергією простору"}, {"kind": "p", "text": "Ноги на ширині плечей, руки підіймаємо на вдиху долонями вгору з боків, потім на видиху опускаємо долонями вниз перед собою і внизу спереду перекладаємо назад і торкається пальцями ззаду. Так робимо чотири рази, повертаючись до чотирьох сторін світу."}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Розтирання рук з обертанням стоячи."}, {"kind": "p", "text": "Руки перед собою, розтираємо долоні одна об одну до відчуття «гарячого» тепла. Потім розтираємо зовнішню сторону долоні лівою рукою праву, і навпаки, і всі пальці. Після цього складаємо пальці в замок і робимо обертання у різні боки руками у замку. У кожну сторону 12 разів, а потім залишаючи пальці в замку, робимо хвилю 12 разів в обидві сторони. Потім складаємо долоні разом перед грудьми і опускаємо та підіймаємо пальці вниз-вгору 12 разів, потім з''єднуємо зовнішньою стороною кисті і також обертаємо кистями вгору-вниз 12 разів, амплітуда максимальна."}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Перекочування стопи з пальців на п''яту і назад."}, {"kind": "p", "text": "Спираємось на ліву ногу, правою ногою спочатку наступаємо на пальці, потім переводимо пальці у вертикальне положення, торкаємося зовнішньою стороною пальців підлоги, потім перекочуємо на п''яту, піднімаючи стопу вгору, пальці відтягуємо на себе, і так, туди і назад, 12 повторень, спочатку правою ногою, потім лівою."}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Обертання та згинання пальців рук"}, {"kind": "p", "text": "Руки тримаємо перед собою. Починаючи з мізинця, прямими пальцями обертаємо праворуч і ліворуч по 12 разів у послідовності: мізинець - безіменний - середній - вказівний - великий палець. Потім великим пальцем правої руки притискаємо мізинець лівої руки кінчиком до долоні, складаючи його, і в складеному стані ще раз щільно притискаємо до долоні, натискаючи великим пальцем правої руки на складений мізинець від його основи до першого згину."}, {"kind": "p", "text": "Потім беремо зовнішньою стороною вказівного та середнього пальця правої руки як «веделкою» мізинець лівої руки та відводимо його максимально назад. Потім, так само, всі інші пальці до великого."}, {"kind": "p", "text": "Після цього долонею лівої руки притискаємо прямий великий палець правої руки до внутрішньої сторони передпліччя, потім правою рукою великий палець лівої руки, і навпаки, всього 32 рази."}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Обертання стопи з опорою на пальці ніг."}, {"kind": "p", "text": "Пальцями правої ноги упираємось у підлогу, опора на ліву ногу. Обертаємо стопою з опорою на пальці вліво і вправо по 12 разів, потім міняємо ноги – відповідно, стоїмо на правій нозі, обертаємо лівою стопою."}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Відштовхування кулаками."}, {"kind": "p", "text": "Вихідна позиція – ноги на ширині плечей, руки стиснуті в кулаках та зігнуті перед собою. Від грудей робимо вдих, на видиху відштовхуємо кулаками від себе повітря 12 разів."}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Обертання кулаками та прямими долонями перед собою."}, {"kind": "p", "text": "Початкова позиція – стоячи, руки прямі. Стискаємо долоні в кулаки і обертаємо поперемінно та синхронно на внутрішній і зовнішній бік 12 разів, потім теж робимо відкритою долонею."}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Обертання прямими руками вздовж осі рук."}, {"kind": "p", "text": "Руки прямо перед собою, обертаємо вліво-вправо поперемінно змінюючи бік, усередину та назовні щодо осі прямих рук, 12 разів."}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Очищаюче дихання хвилею з напругою рук і кистей, стиснутих у кулаки. Виконується 36 разів. Спочатку робимо гучний вдих і шумний видих нижньою частиною живота (дихання діафрагмою), одночасно на видиху стискаючи кулаки і напружуючи прямі руки, опущені вниз, 12 разів. Потім продовжуємо те саме і додаємо рух ребрами - ребра звужуються і розширюються - наповнюється та очищається нижня частина легень - теж 12 разів. І потім, продовжуючи дихати животом і ребрами, підключаємо верхню частину грудей: піднімаємо її та опускаємо – наповнюючи та очищуючи повний об''єм легень."}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Обертання стопою на піднятій нозі стоячи."}, {"kind": "p", "text": "Стоїмо на лівій нозі і підіймаємо праву пряму ногу над підлогою. Обертаємо стопою ліворуч і праворуч, на внутрішній і зовнішній бік 12 разів, потім міняємо ногу."}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Обертання в ліктьових суглобах."}, {"kind": "p", "text": "Руки убік, плечі вільні. Обертаємо передпліччям щодо ліктів на внутрішню та зовнішню сторону синхронно, лікті та плечі нерухомі в одній лінії, горизонтально. Потім синхронно вліво та вправо. Потім обертаємо поперемінно вліво-вправо, всередину та назовні - кожен рух 12 разів. Закінчуємо обертанням назовні кілька разів."}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Обертання в колінних суглобах."}, {"kind": "p", "text": "Початкове положення стоячи на лівій нозі - права нога зігнута в коліні і піднята на 45 градусів, стегно до коліна нерухоме. Робимо обертання гомілки на внутрішню та зовнішню сторону відносно коліна 12 разів. Гомілка і стопа розслаблені, допомагаємо обертанню гомілки стегном. Потім ноги міняємо."}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "ÐÐ°ÑINSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('cc7b01ee-0101-4000-8000-000000000003', 'cc7b01ee-0000-4000-8000-000000000001', 'cc7b01ee-0100-4000-8000-000000000001', 'exercise-sequence-reminders', 'Нагадувалки про послідовність вправ', 3, NULL, NULL, NULL, '[{"id": "exercise-sequence-reminders-text-1", "type": "rich_text", "content": [{"kind": "p", "text": "ÐÐ½ÑÐµÐ³ÑÐ°Ð»ÑÐ½Ð° Ð²ÑÐ´Ð½Ð¾Ð²Ð»ÑÐ²Ð°Ð»ÑÐ½Ð° ÐµÐ½ÐµÑÐ³Ð¾Ð¼Ð¾Ð´ÐµÐ»ÑÑÑÐ° Ð³ÑÐ¼Ð½Ð°ÑÑÐ¸ÐºÐ°"}, {"kind": "p", "text": "1 ÑÐ°ÑÑÐ¸Ð½Ð° ð«"}, {"kind": "p", "text": "ÐÐ¸Ð´ÑÐ»ÐµÐ½Ð½Ñ ÐµÐ½ÐµÑÐ³ÑÑ ÑÐ° Ð¿ÑÐ¾ÐºÐ°ÑÑÐ²Ð°Ð½Ð½Ñ ÐµÐ½ÐµÑÐ³ÐµÑÐ¸ÑÐ½Ð¸ÑINSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('cc7b01ee-0201-4000-8000-000000000001', 'cc7b01ee-0000-4000-8000-000000000001', 'cc7b01ee-0200-4000-8000-000000000001', 'day-1', 'Урок №1. Понеділок', 1, 1, NULL, NULL, '[{"id": "ivem-day-1-objective", "text": "Пройти авторську практику для дня «Понеділок».", "type": "lesson_objective"}, {"id": "ivem-day-1-boundary", "text": "Практика має освітній і wellness-формат та не замінює медичну діагностику чи лікування. Зупиніть вправу, якщо вона викликає біль, запаморочення або інше погіршення самопочуття, і за потреби зверніться до кваліфікованого фахівця.", "type": "boundary_note"}, {"id": "ivem-day-1-video", "type": "video", "title": "Урок №1. Понеділок", "videoId": "Fi_UvWuXdeY", "provider": "youtube"}, {"id": "ivem-day-1-text-1", "type": "rich_text", "content": [{"kind": "h3", "text": "Інтегральна відновлювальна енергомоделююча гімнастика"}, {"kind": "p", "text": "Опис вправ"}, {"kind": "p", "text": "1 частина"}, {"kind": "p", "text": "Виділення енергії та прокачування енергетичних насосів"}, {"kind": "p", "text": "1. Вправа"}, {"kind": "p", "text": "Обертання на п''ятах, руки в сторони"}, {"kind": "p", "text": "Основна позиція - стоячи прямо, руки прямі в сторони долонями вгору."}, {"kind": "p", "text": "Повертаємось праворуч на місці, дрібно переступаючи ногами з пальців в п''яту 24-32 рази до злиття видимого в одну лінію, потім повільно, але впевнено зупиняємось і опускаємо руки."}, {"kind": "p", "text": "2. Вправа"}, {"kind": "p", "text": "Підняття прямих ніг лежачи, підборіддя до грудей"}, {"kind": "p", "text": "Основна позиція – лежачи на спині, руки прямі вздовж тіла долонями до підлоги."}, {"kind": "p", "text": "На вдиху одночасно підіймаємо прямі ноги, максимально натягуючи пальці на себе і не відриваючи від підлоги поперек, та підіймаємо голову, притискаючи підборіддя до грудей. На видиху – опускаємо. 12 разів"}, {"kind": "p", "text": "3. Вправа"}, {"kind": "p", "text": "Прогинання назад, стоячи на колінах та пальцях ніг."}, {"kind": "p", "text": "Основна позиція - стоячи на колінах і пальцях ніг, долони з притиснутими пальцями під сідницями, підборіддя притиснуте до грудей."}, {"kind": "p", "text": "На вдиху вигинаємось назад, закидаючи голову, на видиху - повертаємося у вихідне положення, 12 разів"}, {"kind": "p", "text": "4. Вправа"}, {"kind": "p", "text": "Підняття корпусу \"лавка\""}, {"kind": "p", "text": "Основна позиція – сидячи на підлозі, ноги та корпус прямі, руки прямі вздовж тулуба долонями на підлозі, пальці притиснуті та спрямовані вперед."}, {"kind": "p", "text": "На вдиху піднімаємо таз вгору, коліна під 90 град, стопи притиснуті до підлоги, руки прямо долонями до підлоги, корпус рівний, паралельно до підлоги, голова відкинута назад. На видиху повертаємось у вихідне положення. 12 разів"}, {"kind": "p", "text": "5. Вправа"}, {"kind": "p", "text": "Прогин спини - згинання з опорою на прямі ноги та руки - \"індійські віджимання\""}, {"kind": "p", "text": "Вихідна позиція – у нахилі, руки прямі приблизно за метр перед собою, пальці притиснуті, спрямовані вперед, долони на підлозі, ноги прямі на ширині плечей, стопи притиснуті до підлоги, підборіддя притиснуте до грудей."}, {"kind": "p", "text": "Робимо вдих і розгинаємось, не відриваючи долонь та стоп від підлоги, ноги та руки прямі, спина прогинається назад, голова максимально відхиляється назад. Робимо видих і повертаємось у вихідне положення. 12 разів"}]}]', '2026-08-23 20:30:19.041894+00', '2026-09-08 15:24:02.326472+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('cc7b01ee-0201-4000-8000-000000000002', 'cc7b01ee-0000-4000-8000-000000000001', 'cc7b01ee-0200-4000-8000-000000000001', 'day-2', 'Урок №2. Вівторок', 2, 2, NULL, NULL, '[{"id": "ivem-day-2-objective", "text": "Пройти авторську практику для дня «Вівторок».", "type": "lesson_objective"}, {"id": "ivem-day-2-boundary", "text": "Практика має освітній і wellness-формат та не замінює медичну діагностику чи лікування. Зупиніть вправу, якщо вона викликає біль, запаморочення або інше погіршення самопочуття, і за потреби зверніться до кваліфікованого фахівця.", "type": "boundary_note"}, {"id": "ivem-day-2-video", "type": "video", "title": "Урок №2. Вівторок", "videoId": "QbApKfbkE64", "provider": "youtube"}, {"id": "ivem-day-2-text-1", "type": "rich_text", "content": [{"kind": "h3", "text": "Інтегральна відновлювальна енергомоделююча гімнастика"}, {"kind": "p", "text": "Опис вправ"}, {"kind": "p", "text": "1 частина"}, {"kind": "p", "text": "Виділення енергії та прокачування енергетичних насосів"}, {"kind": "p", "text": "Вправа."}, {"kind": "ul", "items": ["Вправа."]}, {"kind": "p", "text": "«Сходинка»"}, {"kind": "p", "text": "Початкове положення – стоїмо на пальцях ніг на високому порозі чи сходинці, руками притримуємося для збереження рівноваги."}, {"kind": "p", "text": "ÐÐ° Ð²Ð´Ð¸ÑINSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('cc7b01ee-0201-4000-8000-000000000003', 'cc7b01ee-0000-4000-8000-000000000001', 'cc7b01ee-0200-4000-8000-000000000001', 'day-3', 'Урок №3. Середа', 3, 3, NULL, NULL, '[{"id": "ivem-day-3-objective", "text": "Пройти авторську практику для дня «Середа».", "type": "lesson_objective"}, {"id": "ivem-day-3-boundary", "text": "Практика має освітній і wellness-формат та не замінює медичну діагностику чи лікування. Зупиніть вправу, якщо вона викликає біль, запаморочення або інше погіршення самопочуття, і за потреби зверніться до кваліфікованого фахівця.", "type": "boundary_note"}, {"id": "ivem-day-3-video", "type": "video", "title": "Урок №3. Середа", "videoId": "AIB-lWhtyO0", "provider": "youtube"}, {"id": "ivem-day-3-text-1", "type": "rich_text", "content": [{"kind": "h3", "text": "Інтегральна відновлювальна енергомоделююча гімнастика"}, {"kind": "p", "text": "Опис вправ"}, {"kind": "p", "text": "1 частина"}, {"kind": "p", "text": "Виділення енергії та прокачування енергетичних насосів"}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "\"Масайські\" стрибки - підстрибування вгору з однієї точки"}, {"kind": "p", "text": "Стоїмо прямо, ноги разом."}, {"kind": "p", "text": "Максимально підстрибуємо вертикально вгору, трохи допомагаючи собі руками, 12 разів"}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Згинання рук з максимальною напругою знизу – вгору"}, {"kind": "p", "text": "Початкове положення – стоячи, руки вздовж тіла, кулаки стиснуті."}, {"kind": "p", "text": "На видиху повільно з максимальною напругою згинаємо руки в ліктях внутрішньою стороною кулаків до грудей. На вдиху вільно опускаємо, 12 разів"}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Біг на місці із захлестом п''ятами по сідницях"}, {"kind": "p", "text": "Вихідна позиція – стоячи, руки зігнуті у ліктях."}, {"kind": "p", "text": "Біжимо на місці, захльостуючи ногами назад і ударяючи п''ятами по сідницях, 24 рази"}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Згинання рук із зусиллям від боків до середини грудей"}, {"kind": "p", "text": "Початкове положення – стоячи, руки відведені убік, кулаки стиснуті."}, {"kind": "p", "text": "На видиху повільно з максимальною напругою рук та грудних м''язів зводимо руки до центру грудей, на вдиху відводимо убік, 12 разів"}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Біг на місці з підняттям колін"}, {"kind": "p", "text": "Початкове положення – стоячи, руки зігнуті у ліктях."}, {"kind": "p", "text": "Біжимо на місці, максимально високо підіймаючи коліна, 24 рази"}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Розгинання рук із зусиллям від середини грудей убік"}, {"kind": "p", "text": "Початкове положення – стоячи, руки притиснуті до центру грудей, кулаки стиснуті."}, {"kind": "p", "text": "На видиху, повільно з максимальною напругою розгинаємо руки в сторони задньою поверхнею руки нагору, на вдиху повертаємо до грудей, 12 разів"}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Стрибки навприсядки"}, {"kind": "p", "text": "Вихідне положення - сидячи навприсядки, руки зігнуті в ліктях."}, {"kind": "p", "text": "Стрибаємо навприсядки вперед 6 разів, назад 6 разів, в один бік 6 разів, в інший бік 6 разів"}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Згинання рук з напругою верхньої частини спини та шиї"}, {"kind": "p", "text": "Початкове положення – стоячи, руки вздовж тіла, кулаки стиснуті, верхня частина кулаків дивиться вперед."}, {"kind": "p", "text": "На видиху повільно з максимальною напругою згинаємо руки в ліктях, зовнішньою стороною кулаків вгору, плечі піднімаємо, на вдиху опускаємо, 12 разів"}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Згинання рук із зусиллям від боків до голови"}, {"kind": "p", "text": "Початкове положення – стоячи, руки в сторони долонями догори, кулаки стиснуті."}, {"kind": "p", "text": "На видиху з максимальною напругою згинаємо руки до голови, на вдиху повертаємо у вихідне положення, 12 разів"}]}]', '2026-08-23 20:30:19.041894+00', '2026-09-08 15:24:02.326472+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('cc7b01ee-0201-4000-8000-000000000004', 'cc7b01ee-0000-4000-8000-000000000001', 'cc7b01ee-0200-4000-8000-000000000001', 'day-4', 'Урок №4. Четвер', 4, 4, NULL, NULL, '[{"id": "ivem-day-4-objective", "text": "Пройти авторську практику для дня «Четвер».", "type": "lesson_objective"}, {"id": "ivem-day-4-boundary", "text": "Практика має освітній і wellness-формат та не замінює медичну діагностику чи лікування. Зупиніть вправу, якщо вона викликає біль, запаморочення або інше погіршення самопочуття, і за потреби зверніться до кваліфікованого фахівця.", "type": "boundary_note"}, {"id": "ivem-day-4-video", "type": "video", "title": "Урок №4. Четвер", "videoId": "eRbMV23uM84", "provider": "youtube"}, {"id": "ivem-day-4-text-1", "type": "rich_text", "content": [{"kind": "h3", "text": "Інтегральна відновлювальна енергомоделююча гімнастика"}, {"kind": "p", "text": "Опис вправ"}, {"kind": "p", "text": "1 частина"}, {"kind": "p", "text": "Виділення енергії та прокачування енергетичних насосів"}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "«Сходинка»"}, {"kind": "p", "text": "Початкове положення – стоїмо на пальцях ніг на високому порозі чи сходинці, руками притримуємося для збереження рівноваги."}, {"kind": "p", "text": "На вдиху максимально опускаємо п''яти нижче порога, на видиху максимально підіймаємось вище порога кілька підходів по 12 разів. Кількість підходів визначаємо індивідуально до досягнення легкого дискомфорту, у середньому – 3-5"}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "ÐÑÐ´ÑÑÑÐ¸Ð±ÑÐ²Ð°Ð½Ð½Ñ ÑÐ· Ð¿ÑÐ¸ÑÑÐ´Ð°Ð½Ð½ÑÐ¼ 90 Ð³ÑÐ°Ð´"}, {"kind": "p", "text": "Початкове положення – стоячи, ноги широко розставлені."}, {"kind": "p", "text": "На вдиху присідаємо до 90 град, на видиху підстрибуємо, 3-5 підходів по 12 разів"}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Присідання на верхній частині стопи із опорою на руки."}, {"kind": "p", "text": "Вихідне положення - опора на зовнішню сторону пальців стопи, ноги прямі, корпус нахилений вперед, руки впираються в лаву, стілець, диван."}, {"kind": "p", "text": "На вдиху опускаємось на коліна і сідаємо на п''яти, на видиху, перерозподіляючи вагу частково на руки, підіймаємось у вихідне положення 12 разів"}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Підняття корпусу лежачи з опорою п''ятами на лаву"}, {"kind": "p", "text": "Вихідна позиція - лежачи на спині, ноги на ширині плечей, зігнуті в колінах на 90 град, п''яти лежать на лаві, стільці, дивані, руки прямі вздовж тіла долонями до підлоги."}, {"kind": "p", "text": "На видиху підіймаємо таз і випрямляємо ноги, на вдиху опускаємося у вихідну позицію, 12 разів. Кількість підходів – 3-5 до досягнення легкого дискомфорту."}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Віджимання різними способами"}, {"kind": "p", "text": "Початкове положення - горизонтальне, з опорою на прямі руки та пальці прямих ніг, при полегшенні – коліна лежать на лаві, стільці."}, {"kind": "p", "text": "Виконуємо по колу 6 видів віджимань:"}, {"kind": "p", "text": "1й – руки розставлені широко з боків, опора на долоні, пальці спрямовані в сторони, вдих унизу, видих угорі, амплітуда максимальна"}, {"kind": "p", "text": "2й – руки стоять вузько, ліктями убік, опора на долоні, кінчики пальців рук торкаються і спрямовані один до одного."}, {"kind": "p", "text": "3-й – руки на ширині плечей, опора на долоні, пальці спрямовані вперед."}, {"kind": "p", "text": "4й - руки на ширині плечей, опора на кулаки, великі пальці притиснуті."}, {"kind": "p", "text": "5й – лікті притиснуті до боків, опора на долоні, пальці спрямовані назад"}, {"kind": "p", "text": "6й – руки на ширині плечей, опора на пальці"}, {"kind": "p", "text": "Чередуємо 6 видів віджимань по колу по четвергах і суботах - робимо по 1 підходу 3-4 видами (1,2,3 або 1,2,3,4 вид віджимання в четвер, відповідно 4 або 5 вид у суботу і 5,6,1 або 6,1,2,3й наступного четверга і т.д."}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Підняття корпусу з нахилу сидячи"}, {"kind": "p", "text": "Вихідне положення - сидячи, коліна розведені убік, долоні разом перед грудьми."}, {"kind": "p", "text": "ÐÐ° Ð²Ð´Ð¸ÑINSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('da06afae-87ac-5ce2-9fec-ac49bc743e0d', 'fb5d1cf1-05b4-552a-9794-cf14a20e85f6', '8170e82a-2913-5543-8a56-09ca20ce698c', 'course-instruction', 'Інструкція по проходженню програми «Природнє тіло з Аюрведою»', 2, NULL, NULL, NULL, '[{"id": "course-instruction-objective", "text": "Перед стартом зібрати режим харчування, пиття, руху, звітності та матеріали програми в один маршрут.", "type": "lesson_objective"}, {"id": "instruction-boundary", "text": "Схеми харчування, дихальні вправи й трав''яний настій у цьому уроці не є універсальним призначенням. Враховуйте свій стан, діагнози, ліки та індивідуальні реакції; за сумнівів погодьте зміни з лікарем або іншим кваліфікованим фахівцем.", "type": "boundary_note"}, {"id": "course-instruction-text-1", "type": "rich_text", "content": [{"kind": "h3", "text": "Відео огляд інструкції"}]}, {"id": "course-instruction-video-2-1", "type": "video", "title": "Інструкція по проходженню програми Природнє тіло з Аюрведою — відео", "videoId": "NesQ7kKRr7U", "provider": "youtube"}, {"id": "course-instruction-text-3", "type": "rich_text", "content": [{"kind": "h3", "text": [{"bold": true, "text": "Короткий Тест"}, {"text": "на визначення конституції тіла (доші) 12 питань -"}, {"href": "/dosha-test", "text": "тут"}, {"text": "."}]}]}, {"id": "course-instruction-image-4", "alt": "Яблука, чайник і намисто на дерев''яній поверхні як образ щоденного ритму", "src": "/cw/courses/natural-body/instruction-ayurvedic-rhythm.webp", "type": "image"}, {"id": "course-instruction-text-5", "type": "rich_text", "content": [{"kind": "h3", "text": [{"bold": true, "text": "Час прийому їжі"}]}, {"kind": "h3", "text": [{"bold": true, "text": "Для вата доші"}]}, {"kind": "p", "text": [{"bold": true, "text": "Варіант 1"}]}, {"kind": "p", "text": "До 8:30 сніданок - через 3 години перекус - 12:00-14:00 обід - через 3 години перекус - 18:00-20:00 вечеря. Останній прийом їжі не пізніше, ніж за 2 години до сну."}, {"kind": "p", "text": [{"bold": true, "text": "Варіант 2"}]}, {"kind": "p", "text": "До 8:30 сніданок - через 3 другий сніданок (перекус) - 12:00-14:00 обід - через 3 другий обід (перекус) - 18:00-20:00 вечеря. Останній прийом їжі не пізніше, ніж за 2 години до сну. Відмінність цієї концепції в тому, що ми ділимо їжу рівномірно на 5 прийомів."}, {"kind": "h3", "text": [{"bold": true, "text": "Для Пітта доші"}]}, {"kind": "p", "text": "До 8:30 сніданок - 12:00-14:00 обід - 18:00-20:00 вечеря. Останній прийом їжі не пізніше, ніж за 2 години до сну. Перекуси можуть бути допустимі при додатковому фізичному навантаженні і у випадку, якщо це вам рекомендували на першій консультації."}, {"kind": "h3", "text": [{"bold": true, "text": "Для Капха доші"}]}, {"kind": "p", "text": "До 11:00 тільки пиття - 11:00-13:00 перший і основний прийом їжі за добу - 18:00 легка вечеря. Додаткові прийоми їжі не бажано."}]}, {"id": "course-instruction-text-6", "type": "rich_text", "content": [{"kind": "h3", "text": [{"bold": true, "text": "Список несприятливих продуктів для харчування людини, за винятком ситуацій критичної необхідності або приватного дослідження (у другому випадку будьте готові прийняти виклик від організма)"}]}, {"kind": "ol", "items": ["Тютюн, алкоголь, наркотики", "Цукор, будь-яке борошно вищого гатунку, барвники консерванти, стабілізатори, розпушувачі і інші продукти, які були створені у хімічних лабораторіях.", "Промислові соуси, консерви, хліб, кондитерські вироби, каші швидкого приготування, макаронні вироби із борошна вищого сорту.", "Смажена на олії їжа. Виключаючи топлене вершкове масло, кокосову і оливкову олії. Ідеальний варіант - це пасерувати спеції на олії і додавати їх разом з олією за 5 хв до закінчення процесу приготування їжі.", "Продукти тваринного походження допустимі у правильних комбінаціях, з достатніми харчовими паузами і достатнім фізичним навантаженням."]}, {"kind": "p", "text": "Автор курсу радить не будувати довгостроковий раціон переважно з цих продуктів і спостерігати за індивідуальною реакцією організму."}, {"kind": "p", "text": "Продукти, що підходять для харчування у відповідності з вашими конституційними особливостями - за посиланнями нижче:"}, {"kind": "h3", "text": [{"bold": true, "href": "https://docs.google.com/document/d/1yGLuQhEYs-4kfLp38CmRA1XWaExeiP70CxUdwOASnxY/edit", "text": "Вата Доша"}]}, {"kind": "h3", "text": [{"bold": true, "href": "https://docs.google.com/document/d/1fTViU8gLdD0Xtdvo8NI5nen-i_Rjsxis0ny1QDPu_vE/edit", "text": "Пітта Доша"}]}, {"kind": "h3", "text": [{"bold": true, "href": "https://docs.google.com/document/d/1mFM4ig2z5hcyJXyyFtd-bwPJptIZeIRedxQWBKG3aBI/edit", "text": "Капха Доша"}]}]}, {"id": "course-instruction-video-7-1", "type": "video", "title": "Інструкція по проходженню програми Природнє тіло з Аюрведою — відео", "videoId": "CD4WhXNjMes", "provider": "youtube"}, {"id": "course-instruction-image-8", "alt": "Приготування різнокольорових овочів у воку", "src": "/cw/courses/natural-body/instruction-cooking-vegetables.webp", "type": "image"}, {"id": "course-instruction-text-9", "type": "rich_text", "content": [{"kind": "h3", "text": [{"bold": true, "text": "Способи приготування їжі"}]}, {"kind": "h3", "text": [{"bold": true, "text": "Для Вата Доші"}]}, {"kind": "ul", "items": ["Варена м''яка їжа + масло", "Тушкована м''яка їжа + масло", "Парова м''яка їжа + масло", "Запечена в духовці + масло", "Жарена на відкритому вогні + масло", "Жарена на сковороді без олії + масло", "Запечені фрукти", "Сирі фрукти", "Сирі овочі + крупа + масло"]}, {"kind": "h3", "text": [{"bold": true, "text": "Для Пітта Доші"}]}, {"kind": "ul", "items": ["Варена їжа + помірна кількість масла", "Тушкована їжа + помірна кількість масла", "Сирі овочі + помірна кількість масла", "Сирі фрукти", "Парова їжа + помірна кількість масла", "Жарена на сковороді без олії + помірна кількість масла", "Жарена на відкритому вогні + масло"]}, {"kind": "h3", "text": [{"bold": true, "text": "Для Капха Доші"}]}, {"kind": "ul", "items": ["Сирі овочі + мінімально масла", "Сирі фрукти + мінімально масла", "Печена їжа + мінімально масла", "Жарена на вогні + мінімальна кількість масла", "Жарена на сковороді без олії + мінімальний об’єм масла", "Парова їжа + мінімальна кількість масла", "Тушена їжа + мінімальна кількість масла", "Варена їжа + мінімальна кількість масла", "Вся їжа повинна залишатися твердою, крупи розсипчасті, овочі недоварені."]}]}, {"id": "course-instruction-image-10", "alt": "Чотири приклади порцій, співвіднесених із розміром долонь", "src": "/cw/courses/natural-body/instruction-portion-guide.webp", "type": "image"}, {"id": "course-instruction-text-11", "type": "rich_text", "content": [{"kind": "h3", "text": [{"bold": true, "text": "Розмір порцій"}]}, {"kind": "h3", "text": [{"bold": true, "text": "Правило 1. Скільки терпить око"}]}, {"kind": "p", "text": "Це означає, що усю їжу, яку ви збираєтесь з’їсти потрібно викласти у велику відкриту тарілку, включаючи усі соуси, десерти і інше. Оцінити поглядом. І якщо ви вважаєте, що цього достатньо, то так і лишайте. Якщо мало - покладіть ще, якщо багато - приберіть зайве, не починаючи їсти. Після того, як ви оцінили кількість їжі, як достатню - починаємо їсти. У процесі нічого не додаємо. Але якщо ви не можете з’їсти все, що в тарілці - не доїдайте."}, {"kind": "h3", "text": [{"bold": true, "text": "Правило 2. Правило долоні."}]}, {"kind": "ul", "items": ["Сирий салат - 2 долоні з гіркою", "Рагу, суп або термічно оброблений салат, термічно оброблені фрукти - 2 долоні без гірки", "Крупа - 1 долоня без гірки", "Будь-яка білкова їжа - 1 долоня без пальців"]}, {"kind": "p", "text": [{"bold": true, "text": "Олії"}]}, {"kind": "ul", "items": ["Вата доша 5-7 ст.л. в день", "Пітта доша 3-5 ст.л. в день", "Капха доша 3 ст.л. в день"]}, {"kind": "h3", "text": [{"bold": true, "text": "Правило 3. Може бути підрахунок калорій, якщо є бажання вести математичний облік."}]}, {"kind": "p", "text": "У будь-якому випадку ви кожного дня відправляєте звіт про минулий день куратору і він контролює об''єми вашої їжі."}, {"kind": "p", "text": "Ви не повинні голодувати і переїдати. У цих випадках ваше меню не стане вам служити у довгу."}, {"kind": "h3", "text": [{"bold": true, "text": "Приклад звітів нижче"}]}, {"kind": "p", "text": [{"bold": true, "href": "https://docs.google.com/drawings/d/1bsvCEqa1gUKceYU9xHf1lK0QdTgjUUc4tFMKtDu3rUQ/edit?usp=sharing", "text": "Таблиця на листі А4"}]}, {"kind": "p", "text": "або"}, {"kind": "p", "text": [{"bold": true, "href": "https://docs.google.com/spreadsheets/d/1eRGp3u6_SzouBn2BNLjjoYFy4HyGi3S14pseAbCD8Yw/edit#gid=0", "text": "Google таблиця"}]}, {"kind": "p", "text": [{"bold": true, "text": "На груповій програмі використовуємо"}, {"bold": true, "href": "https://docs.google.com/document/d/1asJSbV6Vg-cvFuD06gccYdkAj_y2iuSOaLt46TZDK9U/edit", "text": "такий варіант"}]}]}, {"id": "course-instruction-image-12", "alt": "Приклад заповненої таблиці харчування, сну і спорту", "src": "/cw/courses/natural-body/instruction-report-table.webp", "type": "image"}, {"id": "course-instruction-text-13", "type": "rich_text", "content": [{"kind": "h3", "text": [{"bold": true, "text": "Розпорядок дня і розподіл продуктів у ньому:"}]}, {"kind": "p", "text": [{"bold": true, "text": "1. Максимально раннє пробудження"}]}, {"kind": "p", "text": [{"bold": true, "text": "2. Повільне пиття теплої води."}]}, {"kind": "p", "text": "Випиваємо 2 стакана, розтягуючи на 10-30 хв. В ідеалі в процесі чи після пиття повинен відбутися “стул”. Якщо цього не відбувається, то рекомендується до прочитання книга Свамі Шівананди “Йога терапія”, розділ “сахаджа басті крійя” і практикувати ту схему крії, яка відповідає вашій симптоматиці. Навіть якщо “стул” не відбувся, переходимо до наступного пункту."}, {"kind": "p", "text": [{"bold": true, "text": "3. Робимо дихальну гімнастику"}]}, {"kind": "ul", "items": ["Капалабхаті – різкі короткі видихи, животом, через ніс. Динаміка повинна бути такою, щоб слиз легко відділявся. 108 повторень.", "Удіяна бандха – вакуумне втягування живота на затримки дихання після видиху. Затримуємо дихання стільки, скільки комфортно. 3 повторення.", "Випинання - втягування живота, на затримки дихання після видиху. Робимо удіяна бандху, але не тримаємо її, а відпускаємо і підтягуємо. Кількість маніпуляцій в одній затримці – комфортне. Усього 3 підходи.", "Повторюємо 3тю вправу, тільки стараємося максимально випнути і втягнути живіт. Більше уваги приділяємо фазі, яка дається складніше. 3 підходи.", "Повторюємо 4ту вправу, тільки випинання і втягування живота робимо різко і динамічно. 3 підходи."]}, {"kind": "p", "text": "Перейти до будь-яких фізичних навантажень. Продовжуючи вправи ще щонайменше 20 хв. Можна скористатися відео із розширеним комплексом дихальної гімнастики. Замість гімнастики може бути прогулянка чи пробіжка 3-10 км."}]}, {"id": "course-instruction-video-14-1", "type": "video", "title": "Інструкція по проходженню програми Природнє тіло з Аюрведою — відео", "videoId": "uoXBYxPAOXo", "provider": "youtube"}, {"id": "course-instruction-video-15-1", "type": "video", "title": "Інструкція по проходженню програми Природнє тіло з Аюрведою — відео", "videoId": "iz9k-V93dXE", "provider": "youtube"}, {"id": "course-instruction-text-16", "type": "rich_text", "content": [{"kind": "p", "text": [{"bold": true, "text": "4. Далі прийом їжі згідно з режимом, що підходить для вашої конституції."}]}, {"kind": "p", "text": [{"bold": true, "text": "Для вата доші"}]}, {"kind": "p", "text": [{"bold": true, "text": "Варіант 1"}]}, {"kind": "p", "text": "До 8:30 сніданок - через 3 години перекус - 12:00-14:00 обід - через 3 години перекус - 18:00-20:00 вечеря. Останній прийом їжі не пізніше, ніж за 2 години до сну."}, {"kind": "p", "text": [{"bold": true, "text": "Варіант 2"}]}, {"kind": "p", "text": "До 8:30 сніданок - через 3 другий сніданок - 12:00-14:00 обід - через 3 другий обід - 18:00-20:00 вечеря. Останній прийом їжі не пізніше, ніж за 2 години до сну."}, {"kind": "p", "text": "Відмінність цієї концепції у тому, що ми ділимо їжу рівномірно на 5 прийомів їжі."}, {"kind": "p", "text": [{"bold": true, "text": "Для Пітта доші"}]}, {"kind": "p", "text": "До 8:30 сніданок - 12:00-14:00 обід - 18:00-20:00 вечеря. Останній прийом їжі не пізніше, ніж за 2 години до сну."}, {"kind": "p", "text": "Перекушування можуть бути допустимі при додатковому фізичному навантаженні і у випадку, якщо вам це було рекомендовано на першій консультації."}, {"kind": "p", "text": [{"bold": true, "text": "Для Капха доші"}]}, {"kind": "p", "text": "До 11:00 тільки пиття - 11:00-13:00 перший і основний прийом їжі за добу - 18:00 легка вечеря. Додаткові прийоми їжі не бажано."}, {"kind": "p", "text": [{"bold": true, "text": "5. Відхід до сну не пізніше 23:00."}]}]}, {"id": "course-instruction-image-17", "alt": "Приклад страви з яйцями, зеленню та овочами", "src": "/cw/courses/natural-body/instruction-meal-example.webp", "type": "image"}, {"id": "course-instruction-text-18", "type": "rich_text", "content": [{"kind": "h3", "text": [{"bold": true, "text": "Продукти для різного часу доби"}]}, {"kind": "p", "text": [{"bold": true, "text": "Сніданок:"}, {"text": "Фрукти, сухофрукти, горіхи, насіння, солодкі овочі, рослинні протеїни, спіруліна, хлорелла, фукус, зелень, крупи, яйця, корніплоди"}]}, {"kind": "p", "text": [{"bold": true, "text": "Обід:", "italic": true}, {"text": "Основний прийом їжі (приймаємо їжу на піку бажання їсти)."}]}, {"kind": "p", "text": "Завжди велика порція овочів у вигляді рагу, супу чи салату і до них щось поживне – каша, бобові, соя, гриби, хлібці, горіхові пасти (звертайте увагу на склад), м’ясо, риба, яйця (слідуємо принципу чергування)."}, {"kind": "p", "text": "Перекус:Через 3 години після основного прийому їжі(Для вата дощі або для пітта дощі котра займається спортом. Капхп доша уникає)."}, {"kind": "p", "text": "Фрукти (можуть бути некоректним на перекус після обіду, дослідимо на практиці). Будь-який рослинний білок. Може бути овочевий фреш. Також може бути хлібець, авокадо, зелень, топлене масло, молочний продукт, цукерки із какао, топленого чи кокосового масла і меду."}, {"kind": "p", "text": [{"bold": true, "text": "Вечеря"}, {"text": ": Ідеальна вечеря - овочевий суп, рагу чи салат. Не їмо крупи увечері. Можна бобові, насіння, гриби."}]}, {"kind": "p", "text": "Для вата доші допускається крупа."}, {"kind": "p", "text": "Для пітта доші допускаються фрукти."}, {"kind": "p", "text": "Після вечері, не пізніше, ніж за годину до сну, при бажанні можна пити рослинне або коров’яче молоко в невеликій кількості. Можно робити з ним какао. Можна пити какао з маслом гхі (допускається тільки в стресовій ситуації)."}, {"kind": "p", "text": [{"text": "Всю"}, {"bold": true, "text": "їжу готуємо на воді і тільки в самому кінці додаємо топлене чи рослинне масло."}]}]}, {"id": "course-instruction-text-19", "type": "rich_text", "content": [{"kind": "h3", "text": [{"bold": true, "text": "Питний режим"}]}, {"kind": "p", "text": "3-5 ковтків теплої води, один раз у 40-60 хв., але не більше, ніж 120 мл за один раз."}, {"kind": "h3", "text": [{"bold": true, "text": "Прийом трав"}]}, {"kind": "p", "text": "Настійку трав п''ємо 3 рази на день по 250 мл. перед сніданком, обідом та вечерею"}, {"kind": "p", "text": [{"bold": true, "text": "Список трав"}]}, {"kind": "ul", "items": ["ромашка,", "календула,", "шипшина,", "фіалка,", "кукурудзяні рильця,", "кмин,", "кріп,", "фенхель"]}, {"kind": "p", "text": "Всі перелічені трави змішуємо 1 до 1-го."}, {"kind": "ul", "items": ["Валер''яна - додаємо третю частину від 1-ї частини"]}, {"kind": "p", "text": "4 ч.л на 800 мл води, температурою 80 градусів. Настоюємо в термосі 40 хв. П’ємо за 30 хв до їжі."}, {"kind": "h3", "text": [{"bold": true, "text": "Чергування продуктів у тижневому циклі"}]}, {"kind": "p", "text": "2 дні в тиждень - м ’ ясо і всі інші продукти із таблиці для вашої конституції."}, {"kind": "p", "text": "2 дні в тиждень - яйця чи риба і всі інші продукти із таблиці для вашої конституції."}, {"kind": "p", "text": "2 дні в тиждень - молочні продукти і всі інші продукти із таблиці для вашої конституції."}, {"kind": "p", "text": "1 день в тиждень - розвантажувальний. Проводимо його у відповідності з інструкцією за посиланням нижче:"}, {"kind": "p", "text": [{"bold": true, "text": "Інструкція"}, {"bold": true, "href": "https://docs.google.com/presentation/d/1rZPyP0JlnThVJ2g3k5RiFSvk_tmjNdKn/edit?usp=sharing&ouid=101357384411492068748&rtpof=true&sd=true", "text": "Розвантажувальний день"}]}]}, {"id": "course-instruction-text-20", "type": "rich_text", "content": [{"kind": "h3", "text": [{"bold": true, "text": "Короткий Тест"}, {"text": "на визначення конституції тіла (доші) 12 питань -"}, {"href": "/dosha-test", "text": "тут"}, {"text": "."}]}]}]', '2026-08-23 17:45:07.335344+00', '2026-09-08 15:24:03.034047+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('68e0b213-c90f-5e47-9930-c892be3b1e69', 'fb5d1cf1-05b4-552a-9794-cf14a20e85f6', '82e31ee5-c006-55c3-aeee-de0cdabecd6f', 'lesson-1', 'Урок 1 · Встановлюємо цілі і мотивацію', 1, NULL, NULL, NULL, '[{"id": "lesson-1-objective", "text": "Розібрати тему «Встановлюємо цілі і мотивацію» і співвіднести її з практикою програми.", "type": "lesson_objective"}, {"id": "lesson-1-text-1", "type": "rich_text", "content": [{"kind": "h3", "text": [{"bold": true, "text": "Урок №1"}]}, {"kind": "p", "text": [{"bold": true, "text": "Тема: \"Встановлюємо цілі і мотивацію\"."}]}, {"kind": "p", "text": "Чи готові ви до проходження програми? Попрацюйте чесно перед собою."}, {"kind": "p", "text": [{"bold": true, "text": "Цікава пропозиція для вас!"}]}, {"kind": "p", "text": "Зробіть фото до та після програми (у весь зріст) та запишіть відгук про проходження прогрми (відео, аудіо або текстовий формат, по закінченню програми."}, {"kind": "p", "text": "За це ви отримаєте у подарунок дуже корисний вебінар про жіноче здоров''я!"}]}, {"id": "lesson-1-video-2-1", "type": "video", "title": "Урок №1 — відео", "videoId": "IoG9HD8uMm4", "provider": "youtube"}, {"id": "lesson-1-text-3", "type": "rich_text", "content": [{"kind": "p", "text": [{"bold": true, "text": "Вітаю вас друзі на першому уроці нашого циклу з 21 уроку з аюрведи. У рамках курсу Природнє тіло з Аюрведою."}]}, {"kind": "p", "text": "Я нагадую що це практичний курс, де ви інтегруєте дієту аюрведичну у своє життя і в цей час вивчаєте базові основи аюрведи для того, щоб зрозуміти що ви інтегруєте у своє життя і для того, щоб змогти надалі будувати дієти для ваших близьких людей і балансувати свою дієту в залежності від пори року."}, {"kind": "p", "text": "Але, для того, щоб прийти до вивчення дієтичних концепцій, до вивчення взагалі аюрведи, нам треба почати з того, що ми маємо затвердитися в тому, що ми дійсно готові рухатися, і що ми дійсно готові рухатися до кінця. Бо це важливий момент. Важливий момент - почати. А для того, щоб почати - ми маємо розуміти куди ми йдемо. І це дуже важлива річ."}, {"kind": "p", "text": "Ми часто на щось ідемо, включаємось в якусь ідею, а потім, два, три чотири дні - емоція здувається і ми більше не хочемо нікуди рухатись. І оце - чому так виникає, це дуже важливий момент, котрий треба обов''язково розібрати. Чому так виникає: перший чому так виникає - бо ми на щось ідемо первинно, через емоцію. Емоція - вона може якісь певні тригери в вас чіпляти, і ви берете чи ту, чи іншу ідею, починаєте її випрацьовувати, але то була емоціональна річ. А емоція - вона просто чіпляє тригери. А для того, щоб це будо не просто чіпляння тригерів, а дійсно рух в глибину. Ми маємо собі поставити декілька питань."}, {"kind": "p", "text": "Для чого, вот якщо ми зараз говоримо в контексті аюрведичних програми, перше питання яке ми маємо собі поставити - для чого я хочу щось змінити. Прямо зараз візьміть собі конспект, з яким ви будете працювати надалі, листочок, чи комп''ютер - не важливо, і перше, на що дайте собі відповідь - для чого я хочу щось змінити. Є у вас якісь уклад життя, якийсь стиль харчування, і ви чомусь вирішуєте це змінити. Дайте собі відповідь на це питання. Важливо, щоб рухатися далі. Наступне питання на яке ви маєте собі дати відповідь - що мене не влаштовує. Що зараз в моєму житті мене не влаштовує. Важливе питання, на котре дайте собі прямо зараз відповідь."}, {"kind": "p", "text": "І не в голові, а запишіть собі, поміркуйте про це, покрутіть це протягом цілого дня, до завтрашньої нашої бесіди. І от коли ви зараз дасте відповіді, на ці питання, котрі я тільки що перед вами поставив, це ще не говорить, що ви дійсно зможете рухатися до кінця. Але це хоча б при окриє завісу, хоча б дасть вам якісь первинні розуміння, і скоріш за все, ви почнете фізіологічні штуки писати - що хочу скинути вагу, хочу привести себе до ладу. Все це добре! так і пишіть - хочу енергію, хочу здоров''я, хочу те, але максимально чітко."}, {"kind": "p", "text": "Якщо, в процесі, коли ви будете писати, якісь показники, котрі ви можете прописати цифрами, обов''язково це пропишіть. Наприклад, то вага, або об''єми, або кількість сну, або кількість кроків яку ви хочете проходити - немає важливості. Якщо, є щось, що ви можете цифрами позначити, обов''язково позначте це цифрами, щоб потім в процесі ви могли звіритися з тим, що ви планували. Але, навіть все це прописавши, навіть прописавши всі ці плани, вірогідність, що ви пройдете все це до кінця - небагато цих вірогідностей. Або у вас все дуже не дуже з вашим здоров''ям і тоді вам хочеться щось змінити, або у вас зовсім щось розвалилося в житті і вам дійсно треба щось змінювати, або ви дуже дисципліновані. Якщо ці три параметри є, то так - ви дійсно зможете пройти цю програму до кінця."}, {"kind": "p", "text": "Але, навіть, в такому випадку, вам буде досить важко. Тут ми підходимо до концептуального, до дуже важливого, що ви насправді, взагалі маєте вирішити в своєму житті і знову і знову ставити собі ці питання, котрі я задам вам зараз. Далі ми пишемо три основні, головні ідеї, не ідеї, а питання до себе. Перше - навіщо я взагалі прокидаюся кожного ранку з ліжка. От моя глибинна мотивація. І спробуйте знайти ту глибинну мотивацію, котра не торкається близьких людей, ваших зобов''язаностей. Що в мене проєкт, я маю його робити. В мене дитина, я маю її годувати. Все це добре, але спробуйте знайти - а саме ви, а що саме ви, навіщо я прокидаюся сьогодні. Якщо у вас немає зобов''язаності, немає відповідальності, немає дітей, немає батьків, вот ви один - навіщо ви сьогодні прокидаєтесь. Можливо ви не один, а можливо ви ні за кого не відповідаєте, але ви у всесвіті і ви зараз прокидаєтесь. Питання - навіщо? Дуже важливе питання. В кай дзені це називають ітигай. Це ваша головна концептуальна ідея - подумайте про це."}, {"kind": "p", "text": "Подумайте протягом всього курсу, подумайте зараз, подумайте протягом дня, сьогоднішнього і завтрашнього - навіщо, взагалі, все відбувається в моєму житті."}, {"kind": "p", "text": "Навіщо ви все робите. Важливо, дуже важливо, поки я сам для себе не знайшов цю відповідь - насправді, мені було дуже важко рухатися. І навіть зараз, коли відповідь є, все одно не так просто. Бо та ціль, котру я собі ставлю, це не ціль, це просто мотиваційна історія, сенс мого життя, і це сенс вашого життя. Для того, щоб мені і вам туди рухатися, отут стає наступне питання. Перше це основна ідея життя. Ваша найвища ціль. І це дуже важливо - щоб до неї іти вам, є якісь умови, що вам треба, щоб іти до цієї основної цілі, щоб рухатися в контексті цієї основної ідеї. Що вам подрібно, щоб робити ось це - рухатися в основну ідею. Друге питання на яке ви маєте собі дати відповідь - що вам треба, щоб туди рухатись. Що вам для цього потрібно. Що вам потрібно, щоб рухатися до головної ідеї вашого життя. І щоб у вас було оце - що вам потрібно робити, щоб ви це робили - точно є ще якісь пункти, котрі роблять вас тим хто рухається до основної цілі. Щоб це зрозуміти, що треба в пункті три - я вам зараз наведу свій приклад. Як це в мене."}, {"kind": "p", "text": "Що я віднайшов для себе як схему мого руху в житті, як основну ідею. Основною ідеєю в моєму житті є мотивація.Тобто, я - як людина, мотивую інших людей. Тобто, я - мотиватор. Для мене це чомусь, я рухався у роздумах, навіщо взагалі я тут, навіщо я взагалі встаю з ліжка, навіщо я рухаюсь вперед - для мене виявилося, що основне - мотивація."}, {"kind": "p", "text": "Мотивація навіть для того, щоб мотивувати свою дитину рухатися по цьому життю з відкритими плечима. Навіть для цього. Але в моєму випадку це розповсюджується не тільки на дитину, а розповсюджується на всіх. Я маю завжди відчувати себе в стані, що я мотивую. Щоб мені бути в цьому стані, мені потрібна постійна сила. Сила фізична, сила ментальна - вона мені потрібна. Без неї, ніякого мотиватора немає. Для того, щоб в мене завжди була сила, я теж маю робити якісь дії. Обов''язково. Бо сила просто так не дається. Немає такого що я лежу, і мені сила дається - так не відбувається. І я написав собі три речі, котрі роблять мене сильним. Це спокій - це коли я роблю щось в стані спокійному. Навіть якщо я зараз збентежений, я заспокоюю себе і в спокійному стані я починаю щось робити - їсти, пити, писати, говорити. Від стану - що я спокійний."}, {"kind": "p", "text": "Друге - це задоволення. Задоволення від процесу, задоволення від результату, задоволення тим що я роблю."}, {"kind": "p", "text": "Останнє, що для мене виявилося ключовим і фундаментальним - це стабільність. Для мене це головне. Це я вам навів свої роздуми, свою концепцію, свій спосіб комунікації з реальністю. Навіщо я встаю з ліжка - щоб мотивувати. Мотивувати себе, дитину, дружину, друзів, батьків, людей, вас, всіх. Така моя задача. Для цього мені потрібна сила. І щоб мати силу мені потрібно все робити в стані спокій, задоволення, стабільність."}, {"kind": "p", "text": "Все що ви написали до цього - якісь фізіологічні штуки, котрі ви хочете винести з програми - все це має лягати в цю концепцію. Якщо всі дії, які ви прописали ведуть вас до того, що у вас в пункті три, цей пункт веде вас до пункту два, і цей пункт веде вас до пункту один, якщо ви все це пропрацюєте, продумаєте, поміркуєте, чесно з собою поспілкуєтесь, то програма ця пройде ідеально легко для вас. І не тільки ця програма, а взагалі все інше з моменту як ви це для себе вкладете - з цього моменту далі ваше життя буде просто постійно вам зрозуміло. Ви завжди будете собі нагадувати: так, моя основна ціль, я її не виконую, а чому я її не виконую - в мене немає сили, а чому в мене немає сили, бо я не роблю вот цього наприклад. Це моя концепція. У вашому випадку це буде своя концепція. Не намагайтеся вдягти мою концепцію на себе, у вас нічого не вийде."}, {"kind": "p", "text": "Подумайте про свою ідею. Поміркуйте про це протягом сьогоднішнього вечора, протягом завтрашнього дня та упродовж всього взагалі, прямо поміркуйте про це. Якщо не зможете - поспілкуйтеся про це з коучем, з психологом, з батьком, з сином, з другом, з подругою, зі мною, з ким завгодно, але пропрацюйте цю концепцію. Якщо вона вкладеться в вашу голову, далі все ваше життя буде, не скажу що як по маслу, воно буде рівним, будуть скакання вгору, будуть скакання вниз, але ви знаєте - куди, як і завдяки чому. перший урок був ось таким."}, {"kind": "p", "text": "Він головний в цьому курсі. Далі ми будемо вивчати технічні аспекти аюрведичного харчування, але оце, дасть вам можливість все вивчати."}, {"kind": "p", "text": "Я дякую вам за присутність в цьому курсі, дякую за ваше навчання і за бажання рухатися в світло в своєму житті."}]}]', '2026-08-23 17:45:07.335344+00', '2026-09-08 15:24:03.034047+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('b7e6f2a1-0000-4000-8000-000000000104', 'b7e6f2a1-0000-4000-8000-000000000001', 'b7e6f2a1-0000-4000-8000-000000000011', 'routine', 'Розпорядок дня для 1, 2 і 3 етапу', 2, NULL, 9, '"Спільна основа для всіх трьох етапів: пробудження, час прийому їжі за конституцією, сон."', '[{"id": "routine-objective", "text": "Цей розпорядок діє всі три дні практикуму. Час прийому їжі відрізняється за конституцією — знайди свій розділ.", "type": "lesson_objective"}, {"id": "routine-video", "type": "video", "title": "Про розпорядок дня", "videoId": "CrqxIvVQZ04", "provider": "youtube"}, {"id": "routine-step-1", "step": 1, "type": "protocol_step", "title": "Раннє пробудження, гігієна", "timing": "до 07:00"}, {"id": "routine-step-2", "step": 2, "type": "protocol_step", "title": "2 склянки теплої води і дихальна гімнастика", "timing": "після пробудження"}, {"id": "routine-meals-vata", "type": "rich_text", "content": [{"kind": "h3", "text": "Час прийому їжі — для Вата доші"}, {"kind": "p", "text": [{"bold": true, "text": "Варіант 1. "}, {"text": "До 8:30 сніданок — через 3 години перекус — 12:00-14:00 обід — через 3 години перекус — 18:00-20:00 вечеря. Останній прийом їжі не пізніше, ніж за 2 години до сну."}]}, {"kind": "p", "text": [{"bold": true, "text": "Варіант 2. "}, {"text": "До 8:30 сніданок — через 3 години другий сніданок — 12:00-14:00 обід — через 3 години другий обід — 18:00-20:00 вечеря. Останній прийом їжі не пізніше, ніж за 2 години до сну. Відмінність цієї концепції в тому, що ми ділимо їжу рівномірно на 5 прийомів."}]}]}, {"id": "routine-meals-pitta", "type": "rich_text", "content": [{"kind": "h3", "text": "Час прийому їжі — для Пітта доші"}, {"kind": "p", "text": "До 8:30 сніданок — 12:00-14:00 обід — 18:00-20:00 вечеря. Останній прийом їжі не пізніше, ніж за 2 години до сну."}, {"kind": "p", "text": "Перекуси можуть мати місце за умови додаткових фізичних навантажень і у випадку, якщо вам це рекомендовано на першій консультації."}]}, {"id": "routine-meals-kapha", "type": "rich_text", "content": [{"kind": "h3", "text": "Час прийому їжі — для Капха доші"}, {"kind": "p", "text": "До 11:00 тільки пиття — 11:00-13:00 перший і основний прийом їжі за добу — 18:00 легка вечеря. Додаткові прийоми їжі небажані."}]}, {"id": "routine-sleep", "type": "rich_text", "content": [{"kind": "h3", "text": "Час сну"}, {"kind": "p", "text": "Лягаємо спати не пізніше 23:00, при цьому вимикаємо всі екрани."}, {"kind": "p", "text": "Протягом дня намагаємося не працювати, лежачи у спальні. Ваш розум повинен чітко знати, що ліжко — це місце для сну."}, {"kind": "h3", "text": "Тривалість сну"}, {"kind": "p", "text": "7-10 годин у залежності від ваших конституційних особливостей, пори року і наявності патологічних процесів. Максимально пізній час для пробудження — 08:00."}, {"kind": "ul", "items": [[{"bold": true, "text": "Вата"}, {"text": " — 7 годин."}], [{"bold": true, "text": "Пітта"}, {"text": " — 8 годин."}], [{"bold": true, "text": "Капха"}, {"text": " — 8-10 годин."}]]}]}]', '2026-08-17 08:38:55.458595+00', '2026-09-08 15:24:03.462767+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('b7e6f2a1-0000-4000-8000-000000000101', 'b7e6f2a1-0000-4000-8000-000000000001', 'b7e6f2a1-0000-4000-8000-000000000010', 'day-1', 'Етап 1. Підготовка', 1, 1, 12, '"Ранок на теплій воді і диханні, ввечері — овочева вечеря до 18:00."', '[{"id": "d1-objective", "text": "Сьогодні ти готуєш тіло до розвантажувального дня: правильний ранок і вечеря з достатньою кількістю клітковини.", "type": "lesson_objective"}, {"id": "d1-morning-head", "type": "rich_text", "content": [{"kind": "h3", "text": "Ранок"}]}, {"id": "d1-step-1", "step": 1, "text": [{"text": "П''ємо 2 склянки теплої води — обов''язково теплої. Можна додати "}, {"bold": true, "text": "лимон"}, {"text": " (для Вата доші), "}, {"bold": true, "text": "мед"}, {"text": " (для Пітта і Капха доші), "}, {"bold": true, "text": "соду"}, {"text": " (для Капха доші, допустимо для Пітта доші, під контролем фахівця — для Вата доші)."}], "type": "protocol_step", "title": "2 склянки теплої води", "timing": "після пробудження"}, {"id": "d1-step-2", "step": 2, "text": "Можна розтягнути на 30 хвилин. Після того, як вода випита, переходимо до дихальних вправ.", "type": "protocol_step", "title": "П''ємо спокійно, не поспішаючи", "timing": "до 30 хвилин"}, {"id": "d1-breathing-video", "type": "video", "title": "Дихальна гімнастика", "videoId": "bl2IeHS1YH8", "provider": "youtube"}, {"id": "d1-evening-head", "type": "rich_text", "content": [{"kind": "h3", "text": "Вечір"}, {"kind": "p", "text": "Вечеря напередодні розвантажувального дня повинна містити достатню кількість клітковини і відбутися не пізніше 18:00."}, {"kind": "h3", "text": "Варіанти вечері напередодні"}]}, {"id": "d1-dinner-1", "text": "Вживати з топленим маслом (Вата, Пітта). Сира морква або печена, але вживаємо без масла — для Капха доші.", "type": "practice_block", "title": "1. Запечена морква"}, {"id": "d1-dinner-2", "text": "Печемо або варимо в «мундирі» буряк, моркву, ріпу, селеру, топінамбур, яблука (всі конституції).", "type": "practice_block", "title": "2. Овочі в «мундирі»"}, {"id": "d1-dinner-3", "text": "Гарбузовий чи морквяний суп-пюре (Пітта і Вата).", "type": "practice_block", "title": "3. Суп-пюре"}, {"id": "d1-dinner-4", "text": "Для Капха доші можна зробити огірковий суп — рецепт у розділі «Рецепти супів».", "type": "practice_block", "title": "4. Огірковий суп"}, {"id": "d1-recipes-cta", "href": "/learn/reset-day/recipes", "text": "Усі рецепти супів для підготовки і розвантажувального дня.", "type": "cta", "label": "Відкрити рецепти"}, {"id": "d1-checklist", "type": "checklist", "items": [{"id": "d1-c1", "text": "Ранок: 2 склянки теплої води випито спокійно"}, {"id": "d1-c2", "text": "Зроблено дихальну гімнастику"}, {"id": "d1-c3", "text": "Вечеря була овочевою і не пізніше 18:00"}, {"id": "d1-c4", "text": "Я обрав(-ла) варіант розвантажувального дня і підготував(-ла) продукти"}], "title": "Чек-лист підготовки", "requiredForCompletion": true}, {"id": "d1-boundary", "text": "Якщо у вашому випадку після овочевої вечері зранку немає дефекації — зверніться до фахівця. У подальшому ми повинні виправити цей недолік.", "type": "boundary_note"}]', '2026-08-15 14:04:44.752241+00', '2026-09-08 15:24:03.462767+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('cc7b01ee-0101-4000-8000-000000000001', 'cc7b01ee-0000-4000-8000-000000000001', 'cc7b01ee-0100-4000-8000-000000000001', 'general-recommendations', 'Загальний опис та рекомендації', 1, NULL, NULL, NULL, '[{"id": "general-recommendations-text-1", "type": "rich_text", "content": [{"kind": "p", "text": "Вітаємо у всесвіті шанувальників гімнастики та здорового образу життя! У цьому кабінеті 7 уроків вправ на кожен день тижня. Дивлячись відео-урок, можна спочатку, для навчання, виконувати вправи або синхронно з відео, або ставити на паузу і виконувати у своєму темпі, - як комфортніше. Всі ці вправи згруповані таким чином, щоб доповнювати одна одну як у комплексі одного дня занять, так і у цілісному комплексі занять всього тижня. Вони однаково підходять і новачкам, і практикуючим будь-якого рівня підготовки. Головне - завжди тренуватися і навантажуватися згідно відчуттям тіла на момент тренування. Тобто, якщо є відчуття, що треба трохи менше навантажитись, або, навпаки, трохи більше - все це можна й потрібно завжди регулювати амплітудою та швидкістю рухів, інтенсивністю та зусиллям, кількістю повторень та підходів. Для початку постійних щоденних тренувань починайте з понеділка - так швидше можна увійти у ритм кожного дня. Спочатку спробуйте на першому тижні мінімальні для себе навантаження для того, щоб сформувати чіткий тілесний відгук по конкретному дню і загалом по всьому тижню. Таким чином, далі вже буде зрозуміло, який середній рівень навантаження буде потрібен у наступних тренуваннях. В середньому, при щоденних тренуваннях індивідуальний початковий робочій тонус тіла може бути досягнутий приблизно за місяц тренувань. Також, якщо спочатку немає можливості або наміру тренуватися кожного дня, можна використовувати програму тренувать будь-якого дня тижня. Всі вони цілісні та сбалансовані для цього дня. Це дає можливість підтримувати себе у гарній формі у своєму форматі тренувань. Але для 100% гарантованного ефекту ми рекомендуємо щоденні тренування, у відповідності до програми комплексу вправ конкретного дня тижня. За для цього притримуйтесь, будь ласка, наступних правил: 1. ЗАВЖДИ робити гімнастику — щодня. Не робити від неї перерв. Не пропускати через хворобу (це допомагає швидше одужати). У разі травми зменшити навантаження в тих вправах, які більше перевантажують травмовану частину тіла (усе за відчуттями), але виконувати ВСІ вправи дня. Не пропускати через обставини (не встиг, пізно прокинувся, рано зустріч тощо) — усе рівно, зробити в будь-який інший час дня (навіть перед сном) або максимально швидко для поточного дня за рахунок швидкості виконання, але виконати ВСІ вправи (у середньому можна вкластися в 40 хвилин, якщо дуже потрібно). 2. Виконувати потрібно ВСІ вправи і ЗАВЖДИ, орієнтуючись на ВІДЧУТТЯ в тілі — регулювати навантаження інтенсивністю, зусиллям, швидкістю виконання, амплітудою та кількістю повторень. 3. Намагатися робити гімнастику після ранкових процедур, перед сніданком, натщесерце. Якщо в якийсь день критично немає такої можливості — усе рівно, зробити в будь-який інший час із не надто навантаженим шлунком, або якщо дуже голодні — перед самою гімнастикою з’їсти швидкі вуглеводи в помірній кількості, наприклад, солодкий батончик. 4. Завжди пити воду до і під час гімнастики по 150–200 мл за раз — за 30 хв до початку, безпосередньо перед початком гімнастики та під час гімнастики, з інтервалом у 30 хвилин між прийомами. 5. Якщо раптом усе ж ніяк не змогли зробити сьогодні — ОБОВ’ЯЗКОВО зробіть наступного дня гімнастику за планом наступного дня, ніби нічого не сталося. 6. Лінуватися можете, коли хочете, але гімнастику робіть щодня 💪 Це поступово сформує стиль ''життя в гімнастиці'', який і дозволить тілу та розуму бути функціональними кожного дня на потязі усього життя."}]}]', '2026-08-23 20:30:19.041894+00', '2026-09-08 15:24:02.326472+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('8097d24a-f0b7-5c4d-b979-071831a02bb2', 'fb5d1cf1-05b4-552a-9794-cf14a20e85f6', '82e31ee5-c006-55c3-aeee-de0cdabecd6f', 'lesson-3', 'Урок 3 · Теорія дош', 3, NULL, NULL, NULL, '[{"id": "lesson-3-objective", "text": "Розібрати тему «Теорія дош» і співвіднести її з практикою програми.", "type": "lesson_objective"}, {"id": "lesson-3-text-1", "type": "rich_text", "content": [{"kind": "h3", "text": [{"bold": true, "text": "Урок №3"}]}, {"kind": "p", "text": [{"bold": true, "text": "Тема: \"Теорія дош\". Вивчаємо з яких першоелементів формуються доші."}]}]}, {"id": "lesson-3-video-2-1", "type": "video", "title": "Урок №3 — відео", "videoId": "erE3Pw3SBlU", "provider": "youtube"}]', '2026-08-23 17:45:07.335344+00', '2026-09-08 15:24:03.034047+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('b7e6f2a1-0000-4000-8000-000000000102', 'b7e6f2a1-0000-4000-8000-000000000001', 'b7e6f2a1-0000-4000-8000-000000000010', 'day-2', 'Етап 2. Розвантажувальний день (умовне голодування)', 2, 2, 16, '"Шість варіантів проходження дня — обери один і не змінюй його протягом дня."', '[{"id": "d2-objective", "text": "Сьогодні ти проходиш розвантажувальний день за одним із шести варіантів. Обери варіант зранку — і далі жодних рішень.", "type": "lesson_objective"}, {"id": "d2-video", "type": "video", "title": "Про розвантажувальний день", "videoId": "g2KPHmoO0wI", "provider": "youtube"}, {"id": "d2-intro", "type": "rich_text", "content": [{"kind": "p", "text": "У даному мануалі представлені варіанти розвантажувального дня, без екстриму. Більш складні варіанти необхідно проводити після індивідуальної консультації."}, {"kind": "h3", "text": "Варіанти розвантажувального дня"}]}, {"id": "d2-variant-1", "text": "Протягом дня їмо тільки рис басматі з топленим маслом. Дозволено не гострі спеції. Їжу можна вживати кожні 3 години, але потроху, якщо хочеться їсти, та 2-3 рази, якщо їсти не хочеться. Вечеря о 18:00 — печена морква. Питний режим: 1 раз на годину 30-120 мл теплої води. Цей варіант можуть виконувати всі без виключення, у тому числі й діти. Рекомендовано для Вата доші.", "type": "practice_block", "title": "1. Рис басматі з топленим маслом"}, {"id": "d2-variant-2", "text": "Весь день їмо овочевий суп (вибираємо до 5-ти овочів). Їжу можна вживати кожні 3 години, але потроху. Вечеря о 18:00 — печена морква. Питний режим: 1 раз на годину 30-120 мл теплої води. Цей варіант можуть виконувати всі без виключення, у тому числі й діти.", "type": "practice_block", "title": "2. Овочевий суп"}, {"id": "d2-variant-3", "text": "Будь-який сирий овоч чи фрукт. Можна вживати кожну годину 1 плід. Вибираємо овочі і фрукти у відповідності до своєї індивідуальної конституції. Питний режим: 1 раз на годину 30-120 мл теплої води або води кімнатної температури (для Пітта доші).", "type": "practice_block", "title": "3. Сирий овоч або фрукт"}, {"id": "d2-variant-4", "text": [{"text": "Сік вживаємо у порції 350 мл 1 раз на 1-3 години. Також можна пити теплу воду у відповідності із рекомендаціями вище. "}, {"bold": true, "text": "Вата доша: "}, {"text": "морква, буряк, апельсин, гарбуз, виноград, гранат, абрикоса, персик. "}, {"bold": true, "text": "Пітта доша: "}, {"text": "яблуко, зелень, гранат, виноград, морква, буряк, картопля. "}, {"bold": true, "text": "Капха доша: "}, {"text": "зелень, гранат, зелене яблуко, огірок, капуста."}], "type": "practice_block", "title": "4. Соковий день"}, {"id": "d2-variant-5", "text": "Весь день проводимо на теплій воді і трав''яних чаях. В воду можна додавати мед або топлене масло — не змішувати. У випадку сильної слабкості чи головного болю увечері їмо овочевий суп. У такий день увечері гарно прийняти теплу ванну (для інших варіантів це також рекомендовано).", "type": "practice_block", "title": "5. Тепла вода і трав''яні чаї"}, {"id": "d2-variant-6", "text": "Весь день тільки на воді і трав''яних чаях.", "type": "practice_block", "title": "6. Тільки вода і трав''яні чаї"}, {"id": "d2-teas", "type": "rich_text", "content": [{"kind": "h3", "text": "Трав''яні чаї для 5 і 6 варіанту"}, {"kind": "p", "text": [{"bold": true, "text": "Трав''яний збір: "}, {"text": "насіння кропу, кмину, фенхелю і листя меліси. Усе змішуємо 1 до 1, потім подрібнюємо і настоюємо 5 ч.л. на 1 літр води (температура води 80 градусів), далі настоюємо в термосі 40 хв і вживаємо протягом дня, як чай."}]}, {"kind": "p", "text": [{"bold": true, "text": "Або чай з куркуми: "}, {"text": "1 ч.л. куркуми заливаємо 1 л води температурою 80 градусів, настоюємо 40 хв і вживаємо протягом дня, як чай."}]}]}, {"id": "d2-recipes-cta", "href": "/learn/reset-day/recipes", "text": "Рецепти супів для розвантажувального дня.", "type": "cta", "label": "Відкрити рецепти"}, {"id": "d2-checklist", "type": "checklist", "items": [{"id": "d2-c1", "text": "Я обрав(-ла) варіант зранку й не змінював(-ла) його протягом дня"}, {"id": "d2-c2", "text": "Питний режим дотриманий"}, {"id": "d2-c3", "text": "Вечір пройшов спокійно, без «доїдання» перед сном"}], "title": "Чек-лист розвантажувального дня", "requiredForCompletion": true}, {"id": "d2-boundary", "text": "Більш складні варіанти розвантажувального дня можливі лише після того, як вам стало абсолютно комфортно проводити день на воді.", "type": "boundary_note"}]', '2026-08-15 14:04:44.752241+00', '2026-09-08 15:24:03.462767+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('b7e6f2a1-0000-4000-8000-000000000103', 'b7e6f2a1-0000-4000-8000-000000000001', 'b7e6f2a1-0000-4000-8000-000000000010', 'day-3', 'Етап 3. Вихід', 3, 3, 10, '"Правильний вихід — запорука успіху. Некоректний вихід може призвести до неприємних наслідків."', '[{"id": "d3-objective", "text": "Сьогодні ти виходиш із розвантажувального дня. Варіант виходу залежить від того, який варіант дня ти проходив(-ла).", "type": "lesson_objective"}, {"id": "d3-video", "type": "video", "title": "Про вихід", "videoId": "yhST6Ew48Zo", "provider": "youtube"}, {"id": "d3-step-1", "step": 1, "type": "protocol_step", "title": "Теплий душ", "timing": "вранці"}, {"id": "d3-exit-common", "type": "rich_text", "content": [{"kind": "h3", "text": "Варіанти виходу"}, {"kind": "p", "text": "У всіх випадках, крім першого і шостого, снідаємо розварений рис басматі."}, {"kind": "p", "text": "У першому варіанті на сніданок їмо будь-яку звичну для вас їжу, крім кави."}]}, {"id": "d3-exit-six", "type": "rich_text", "content": [{"kind": "h3", "text": "Вихід після шостого варіанту"}, {"kind": "p", "text": [{"bold": true, "text": "Самсараяна крама"}, {"text": " — градуйована дієта:"}]}, {"kind": "ol", "items": [[{"bold": true, "text": "Манда"}, {"text": " — рисовий відвар"}], [{"bold": true, "text": "Пейя"}, {"text": " — рисовий суп"}], [{"bold": true, "text": "Вілепі"}, {"text": " — густий рисовий суп"}], [{"bold": true, "text": "Одана"}, {"text": " — варений рис"}], [{"bold": true, "text": "Юша"}, {"text": " — суп з машу"}], [{"bold": true, "text": "Кічарі"}, {"text": " — суміш рису з машем"}]]}, {"kind": "p", "text": "Маш (Mung Bean) є традиційною культурою, яка вирощується в Південній та Східній Азії вже протягом тисячоліть. Ймовірно, маш має своє походження в Індії, де він вперше був вирощений більше 4 000 років тому."}]}, {"id": "d3-checklist", "type": "checklist", "items": [{"id": "d3-c1", "text": "Вранці прийнято теплий душ"}, {"id": "d3-c2", "text": "Сніданок відповідав моєму варіанту виходу"}, {"id": "d3-c3", "text": "Я не компенсував(-ла) вчорашній день"}], "title": "Чек-лист виходу", "requiredForCompletion": true}, {"id": "d3-boundary", "text": "Правильний вихід — запорука успіху. Некоректний вихід може призвести до неприємних наслідків.", "type": "boundary_note"}, {"id": "d3-faq", "type": "faq_block", "items": [{"id": "d3-faq-1", "answer": "Доступ лишається назавжди — повторюй тоді, коли відчуваєш потребу, а не за розкладом.", "question": "Як часто можна повторювати цей цикл?"}, {"id": "d3-faq-2", "answer": "Якщо відчуваєш, що готовий(-а) до глибшого рівня — наступний крок це «Шлях 21», повна 21-денна програма очищення.", "question": "Що далі після цього циклу?"}]}, {"id": "d3-next", "href": "/programs/way21", "text": "Сподобалась легкість? Є глибший рівень.", "type": "cta", "label": "Подивитись «Шлях 21»"}]', '2026-08-15 14:04:44.752241+00', '2026-09-08 15:24:03.462767+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('c4a91d3e-0000-4000-8000-000000000100', 'c4a91d3e-0000-4000-8000-000000000001', 'c4a91d3e-0000-4000-8000-000000000011', 'intro', 'Технічна інформація по програмі. Прочитайте обов''язково', 1, 1, 8, '"Що зробити першого дня: написати адресу для трав, пройти тест на дошу і зрозуміти формат звітів."', '[{"id": "intro-objective", "text": "Налаштувати зв''язок з автором і формат супроводу до того, як почнеться сам протокол.", "type": "lesson_objective"}, {"id": "intro-boundary", "text": "Інтегративний детокс — оздоровчий інструмент, а не лікування: він доповнює, а не замінює діагностику й терапію. За хронічних станів, вагітності, лактації та прийому препаратів протокол і склад зборів узгоджуються з вашим лікарем.", "type": "boundary_note"}, {"id": "intro-packages", "type": "rich_text", "content": [{"kind": "h3", "text": "Залежно від вашого пакета"}, {"kind": "ul", "items": [[{"bold": true, "text": "«Вивчаю сам» — "}, {"text": "напишіть Євгенію у телеграм свою адресу, для відправлення трав."}], [{"bold": true, "text": "«Стандарт» — "}, {"text": "напишіть адресу для відправлення трав, а також відправляйте звіти щодня Євгену у телеграм."}], [{"bold": true, "text": "«Індивідуальний супровід» — "}, {"text": "напишіть адресу для відправлення трав та для проведення консультації, а також відправляйте звіти щодня Євгену у телеграм."}]]}]}, {"id": "intro-tg-cta", "href": "https://t.me/E_Koriakin", "text": "Адреса для трав, звіти й питання по програмі — сюди.", "type": "cta", "label": "Написати Євгенію у Telegram"}, {"id": "intro-support", "type": "rich_text", "content": [{"kind": "h3", "text": "Технічні питання (для всіх пакетів)"}, {"kind": "p", "text": "Якщо не відкриваються уроки, не приходить доступ або є проблеми зі входом у кабінет — напишіть у технічного бота CenterWay. Він знайде вашу оплату за email чи телефоном і, якщо потрібно, передасть звернення живій підтримці."}]}, {"id": "intro-support-cta", "href": "https://telegram.me/centerway_support_bot", "text": "Доступ, уроки, кабінет, оплата.", "type": "cta", "label": "Технічна підтримка CenterWay"}, {"id": "intro-dosha", "type": "rich_text", "content": [{"kind": "h3", "text": "Тест на конституцію"}, {"kind": "p", "text": "Обов''язково пройдіть тест на визначення конституції тіла (доші) — 12 питань. Від доші залежить ваш режим прийому їжі на всі три тижні."}]}, {"id": "intro-dosha-cta", "href": "/tests/dosha", "text": "12 питань, просто на платформі.", "type": "cta", "label": "Пройти тест на дошу"}, {"id": "intro-report", "type": "rich_text", "content": [{"kind": "h3", "text": "Звіт"}, {"kind": "p", "text": "Звіт надсилаємо щодня Євгенію в чат у телеграм. Нижче — приклад того, як він виглядає."}]}, {"id": "intro-report-cta", "href": "https://docs.google.com/document/d/1asJSbV6Vg-cvFuD06gccYdkAj_y2iuSOaLt46TZDK9U/edit", "text": "Google-документ зі структурою щоденного звіту.", "type": "cta", "label": "Приклад звіту"}, {"id": "intro-checklist", "type": "checklist", "items": [{"id": "intro-c1", "text": "Написав(-ла) Євгенію адресу для відправлення трав"}, {"id": "intro-c2", "text": "Пройшов(-ла) тест на дошу"}, {"id": "intro-c3", "text": "Подивився(-лась) приклад звіту"}, {"id": "intro-c4", "text": "Куплено топлену олію гхі та краплі Ану тейл"}], "title": "Перший день", "requiredForCompletion": true}]', '2026-08-19 14:47:31.154378+00', '2026-09-08 15:24:04.29744+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('13fbbb6c-fbf2-5fac-8616-8e236e21ae08', 'fb5d1cf1-05b4-552a-9794-cf14a20e85f6', '8170e82a-2913-5543-8a56-09ca20ce698c', 'technical-information', 'Технічна інформація по програмі', 1, NULL, NULL, NULL, '[{"id": "technical-information-objective", "text": "Зрозуміти формат підтримки, контакти і технічний порядок проходження програми.", "type": "lesson_objective"}, {"id": "technical-boundary", "text": "Програма має освітній і практичний wellness-формат та не замінює медичну діагностику чи лікування. Якщо під час проходження погіршується самопочуття, зупиніть практику і зверніться до кваліфікованого фахівця.", "type": "boundary_note"}, {"id": "technical-information-text-1", "type": "rich_text", "content": [{"kind": "p", "text": [{"bold": true, "text": "Якщо ви проходите Програму \"Природнє тіло з Аюрведою\" по пакету \"Вивчаю сам\","}, {"text": "ви проходити програму самостійно, але якщо у вас виникнуть проблеми зі здоров''ям під час проходження програми, то напишіть Євгенію у телеграм -"}, {"href": "https://t.me/E_Koriakin", "text": "https://t.me/E_Koriakin"}]}, {"kind": "p", "text": [{"bold": true, "text": "Якщо ви проходите Програму \"Природнє тіло з Аюрведою\" по пакету \"Стандарт\""}, {"text": ", напишіть Євгенію у телеграм для відправки щоденних звітів по проходженню програми та отримання зворотнього зв''язку по цим звітам -"}, {"href": "https://t.me/E_Koriakin", "text": "https://t.me/E_Koriakin"}]}, {"kind": "p", "text": [{"bold": true, "text": "Якщо ви проходите Програму \"Природнє тіло з Аюрведою\" по пакету \"Індивідуальний супровід\""}, {"text": ", напишіть Євгенію у телеграм для проведення індивідуальних консультацій, відправлення звітів та супроводу по програмі -"}, {"href": "https://t.me/E_Koriakin", "text": "https://t.me/E_Koriakin"}]}, {"kind": "h3", "text": [{"bold": true, "text": "Технічні непорозуміння по програмі (для всіх пакетів проходження)"}]}, {"kind": "p", "text": "Якщо у вас виникнуть технічні непорозумінні по проходженню програми на платформі, не будуть відкриватися уроки, чи виникнуть проблеми зі входом у кабінет, то одразу напишіть у телеграм бот."}]}, {"id": "technical-author-support", "href": "https://t.me/E_Koriakin", "text": "Питання щодо супроводу, звітів і проходження програми.", "type": "cta", "label": "Написати Євгенію в Telegram"}, {"id": "technical-platform-support", "href": "https://telegram.me/centerway_support_bot", "text": "Якщо не відкривається урок або виникла проблема зі входом у кабінет.", "type": "cta", "label": "Технічна підтримка CenterWay"}]', '2026-08-23 17:45:07.335344+00', '2026-09-08 15:24:03.034047+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('6fefe75f-e194-56d6-ba4f-0070025c812a', 'fb5d1cf1-05b4-552a-9794-cf14a20e85f6', '82e31ee5-c006-55c3-aeee-de0cdabecd6f', 'lesson-2', 'Урок 2 · 5 великих першоелементів', 2, NULL, NULL, NULL, '[{"id": "lesson-2-objective", "text": "Розібрати тему «5 великих першоелементів» і співвіднести її з практикою програми.", "type": "lesson_objective"}, {"id": "lesson-2-text-1", "type": "rich_text", "content": [{"kind": "h3", "text": [{"bold": true, "text": "Урок №2"}]}, {"kind": "p", "text": [{"bold": true, "text": "Тема: \"5 великих першоелементів\""}]}]}, {"id": "lesson-2-video-2-1", "type": "video", "title": "Урок №2 — відео", "videoId": "z_cp5xApHAw", "provider": "youtube"}]', '2026-08-23 17:45:07.335344+00', '2026-09-08 15:24:03.034047+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('c4a91d3e-0000-4000-8000-000000000130', 'c4a91d3e-0000-4000-8000-000000000001', 'c4a91d3e-0000-4000-8000-000000000014', 'w3-instruction', 'Тиждень 3-й. ВИХІД', 1, 15, 10, '"Запустити травлення, виростити флору кишківника, виробити ідеальний для себе режим харчування. На все життя."', '[{"id": "w3-objective", "text": "Запустити процеси травлення й вийти з програми з режимом харчування, який лишається з вами.", "type": "lesson_objective"}, {"id": "w3-intro", "type": "rich_text", "content": [{"kind": "p", "text": "Постарайтесь бути дуже уважними до себе на цьому етапі. Не піддавайтесь на провокації розуму. Будьте послідовними."}]}, {"id": "w3-drink", "text": "250 мл за 15–30 хв до їжі. Склад: лимон, апельсин, імбир, кардамон, фенхель, кориця, гвоздика, мед. Лимон — обов''язковий інгредієнт; усі спеції додаємо за смаком або не додаємо взагалі, якщо не хочеться. Напій повинен бути кислим — він допоможе розпалити вогонь травлення. Потрібно дочекатися хороших фізичних позивів до їжі. Напій п''ємо перед кожним прийомом їжі.", "type": "practice_block", "title": "Кислий напій"}, {"id": "w3-attention", "type": "rich_text", "content": [{"kind": "h3", "text": "Уважність до їжі"}, {"kind": "p", "text": "Перед тим, як їсти — думайте та аналізуйте. Звертайте увагу на смак, запах, консистенцію їжі. Зверніть увагу на свій стан до і після їжі. Проаналізуйте свій стан через 1 годину після їжі, через 3 години і зранку після вечірнього прийому. Якщо стан вам не подобається — спробуйте зрозуміти, що саме не так; якщо не виходить самостійно, запитайте у Євгенія."}]}, {"id": "w3-boundary", "text": "Вихід із програми — не формальність: різке повернення до звичайної їжі знецінює обидва попередні тижні. Дотримуйтесь послідовності днів, навіть якщо здається, що вже все добре.", "type": "boundary_note"}]', '2026-08-19 14:47:31.154378+00', '2026-09-08 15:24:04.29744+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('c27e0f93-614f-5ca1-bc37-5237443196fa', 'fb5d1cf1-05b4-552a-9794-cf14a20e85f6', '82e31ee5-c006-55c3-aeee-de0cdabecd6f', 'lesson-4', 'Урок 4 · 13 функцій життя і характеристики Вата доші', 4, NULL, NULL, NULL, '[{"id": "lesson-4-objective", "text": "Розібрати тему «13 функцій життя і характеристики Вата доші» і співвіднести її з практикою програми.", "type": "lesson_objective"}, {"id": "lesson-4-text-1", "type": "rich_text", "content": [{"kind": "h3", "text": [{"bold": true, "text": "Урок №4"}]}, {"kind": "p", "text": [{"bold": true, "text": "Складається з 2 тем: Тема 1: \"13 функцій життя\" Тема 2: \"Характеристики Вата доші\""}]}]}, {"id": "lesson-4-video-2-1", "type": "video", "title": "Урок №4 — відео", "videoId": "Q7UyGeUDHZo", "provider": "youtube"}]', '2026-08-23 17:45:07.335344+00', '2026-09-08 15:24:03.034047+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('550b4259-adbe-5c17-8a3f-856683d90e6c', 'fb5d1cf1-05b4-552a-9794-cf14a20e85f6', '82e31ee5-c006-55c3-aeee-de0cdabecd6f', 'lesson-5', 'Урок 5 · Основні характеристики Пітта доші', 5, NULL, NULL, NULL, '[{"id": "lesson-5-objective", "text": "Розібрати тему «Основні характеристики Пітта доші» і співвіднести її з практикою програми.", "type": "lesson_objective"}, {"id": "lesson-5-text-1", "type": "rich_text", "content": [{"kind": "h3", "text": [{"bold": true, "text": "Урок №5"}]}, {"kind": "p", "text": [{"bold": true, "text": "Тема: \"Основні характеристики Пітта доші\""}]}]}, {"id": "lesson-5-video-2-1", "type": "video", "title": "Урок №5 — відео", "videoId": "ESx54RH6nak", "provider": "youtube"}]', '2026-08-23 17:45:07.335344+00', '2026-09-08 15:24:03.034047+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('c4a91d3e-0000-4000-8000-000000000110', 'c4a91d3e-0000-4000-8000-000000000001', 'c4a91d3e-0000-4000-8000-000000000012', 'w1-instruction', 'Тиждень 1-й. ВХІД — підготовка і загальна релаксація', 1, 2, 14, '"Задача етапу — увійти в процес та підготувати органи до звільнення."', '[{"id": "w1-objective", "text": "Увійти в процес і підготувати органи до звільнення: режим, олія, збір, тепло.", "type": "lesson_objective"}, {"id": "w1-step-1", "step": 1, "text": "Відхід до сну не пізніше 23:00, найбільш пізній час — 23:45. Сніданок до 8:30 ранку (якщо не хочеться їсти — можна пропускати). Основний прийом їжі 11:00–13:00, залежно від бажання їсти, обставин і калорійності сніданку; приймайте їжу на піку бажання їсти. Вечеря — 18:00 ідеально, 20:00 максимально пізно.", "type": "protocol_step", "title": "Вирівняти режим дня"}, {"id": "w1-step-2", "step": 2, "text": "Мінімум 3 столові ложки, оптимально — 5 ст. л. на день; якщо добре себе почуваєте, можна й більше. Одна чайна або столова ложка (за відчуттями) зранку натщесерце, усі інші — з їжею. Намагаємось взяти максимум кілокалорій топленим маслом: у 100 грамах приблизно 900 ккал.", "type": "protocol_step", "title": "Прийом топленого масла"}, {"id": "w1-step-3", "step": 3, "text": "3 рази на день, разом з їжею. Заварювання — в уроці про ранкову структуру дня.", "type": "protocol_step", "title": "Прийом трав''яного збору"}, {"id": "w1-step-4", "step": 4, "text": "Кунжутною або топленою олією, зранку і ввечері. 1 чайну ложку розтерти по долонях та стопах, також наносимо на шию й поперек, по можливості — на все тіло. Носимо мінімум 15 хв, оптимально 60 хв, після цього лягаємо у ванну чи стаємо під гарячий душ і дуже сильно прогріваємось. Також сприятливо 2–3 рази на тиждень змастити олією голову: намаслену голову щільно замотуємо в платок і носимо мінімум 1 годину, найкраще провести з маслом ніч, зранку змити. Бажано використовувати делікатні шампуні, в ідеалі — рослинні порошки для миття волосся.", "type": "protocol_step", "title": "Розтирання долонь і стоп"}, {"id": "w1-step-5", "step": 5, "text": "Тричі на тиждень. Склад: 0,25 склянки гімалайської солі, 0,25 склянки сульфату магнію, 3 склянки яблучного оцту, 15 крапель евкаліптової олії. Якщо немає можливості приймати ванну — паримо ноги із цим же складом, тільки всі складові ділимо на 5.", "type": "protocol_step", "title": "Мінеральна ванна для релаксації"}, {"id": "w1-step-6", "step": 6, "text": "Виконуємо вранці після дихальних вправ (повний опис — в уроці про структуру ранку). Окремо для вух: змішуємо 2 краплі теплої олії гхі та 1 краплю Ану тейл, просочуємо невеликий шматочок спонжика, видавлюємо олію у вухо і вставляємо спонжик. Дозування на одне вухо. Робимо щодня ввечері перед сном — особливо важливо, якщо вуха дають себе знати.", "type": "protocol_step", "title": "Процедура Насья — очищення носоглотки"}, {"id": "w1-boundary", "text": "Усе робиться в межах комфорту: пар не повинен обпалювати, пульс не повинен прискорюватись, тепло має бути приємним. Різке погіршення самопочуття — процедура зупиняється, пишемо в супровід.", "type": "boundary_note"}]', '2026-08-19 14:47:31.154378+00', '2026-09-08 15:24:04.29744+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('c4a91d3e-0000-4000-8000-000000000111', 'c4a91d3e-0000-4000-8000-000000000001', 'c4a91d3e-0000-4000-8000-000000000012', 'w1-nutrition', 'Харчування першого тижня: табу, продукти, режим по дошах', 2, 3, 12, '"Що прибираємо, що лишається — і як розкладається день під вашу конституцію."', '[{"id": "w1n-objective", "text": "Зібрати свій раціон на програмі: за списком продуктів і за режимом своєї доші.", "type": "lesson_objective"}, {"id": "w1n-taboo", "type": "rich_text", "content": [{"kind": "h3", "text": "Табу — що не можна їсти"}, {"kind": "ul", "items": ["Чорний чай, кава. Можна зелений і трав''яний чаї, добре також узвари, натуральний квас", "Барвники, стабілізатори, синтетичні «Е»-добавки, консерванти, рафіновані продукти", "Цукор, борошно вищого сорту (цільнозернове борошно — можна)", "Магазинна готова їжа", "М''ясо, риба, яйця, молочні продукти — все, крім топленого масла", "Рослинні олії", "Алкоголь, наркотики, тютюн"]}]}, {"id": "w1n-products", "type": "rich_text", "content": [{"kind": "h3", "text": "Набір продуктів, що підходять для очищення"}, {"kind": "ul", "items": [[{"bold": true, "text": "Хліб — "}, {"text": "тільки хлібці, не злакові, а з насіння. Можна цільнозерновий хліб у невеликому обсязі."}], [{"bold": true, "text": "Овочі — "}, {"text": "усі, крім картоплі й помідора. Цибулю і часник — термічно обробленими."}], [{"bold": true, "text": "Фрукти — "}, {"text": "яблуко, груша, гранат, кавун, лимон, малина."}], [{"bold": true, "text": "Сухофрукти — "}, {"text": "усі, крім в''ялених бананів; диня і манго — тільки в першій половині дня. Цукати не можна. Постарайтеся жити без сухофруктів або додавайте трохи до насіння."}], [{"bold": true, "text": "Горіхи і насіння — "}, {"text": "тільки сирі, у замоченому вигляді, або готуємо разом із кашею, супом, салатом чи додаємо у смузі."}], [{"bold": true, "text": "Крупи — "}, {"text": "усі цільні."}], [{"bold": true, "text": "Бобові — "}, {"text": "маш і нут; інші можна, якщо не викликають газоутворення."}], [{"bold": true, "text": "Гриби — "}, {"text": "усі, краще місцеві сушені."}], [{"bold": true, "text": "Мед — "}, {"text": "не більше 5 столових ложок на день і не більше, ніж топленого масла (старайтесь без нього)."}], [{"bold": true, "text": "Спеції — "}, {"text": "усі, крім пекучих; сіль помірно."}], [{"bold": true, "text": "Обов''язковий продукт — топлена олія гхі: "}, {"text": "5–7 ст. л. на день, по можливості більше. Одну або більше зранку натщесерце обов''язково, решту додаємо в їжу."}]]}]}, {"id": "w1n-sleep", "type": "rich_text", "content": [{"kind": "h3", "text": "Сон"}, {"kind": "p", "text": "Відходимо до сну не пізніше 23:00, лягаючи, вимикаємо всі екрани. Протягом дня стараємося не працювати лежачи в спальні: ваш розум повинен чітко знати, що ліжко — це місце для сну."}, {"kind": "p", "text": "Тривалість сну — 7–10 годин залежно від конституційних особливостей, пори року й наявності патологічних процесів. Максимально пізній час для пробудження — 8:00. Вата — 7 годин, Пітта — 8 годин, Капха — 8–10 годин."}]}, {"id": "w1n-vata", "text": "Варіант 1: до 8:30 сніданок — через 3 години перекус — 12:00–14:00 обід — через 3 години перекус — 18:00–20:00 вечеря. Варіант 2: до 8:30 сніданок — через 3 години другий сніданок — 12:00–14:00 обід — через 3 години другий обід — 18:00–20:00 вечеря; тут ми ділимо їжу рівномірно на 5 прийомів. Останній прийом їжі не пізніше, ніж за 2 години до сну.", "type": "practice_block", "title": "Час прийому їжі — Вата доша"}, {"id": "w1n-pitta", "text": "До 8:30 сніданок — 12:00–14:00 обід — 18:00–20:00 вечеря. Останній прийом їжі не пізніше, ніж за 2 години до сну. Перекуси допустимі при додаткових фізичних навантаженнях і якщо це рекомендовано на першій консультації.", "type": "practice_block", "title": "Час прийому їжі — Пітта доша"}, {"id": "w1n-kapha", "text": "До 11:00 тільки пиття — 11:00–13:00 перший і основний прийом їжі за добу — 18:00 легка вечеря. Додаткові прийоми їжі небажані.", "type": "practice_block", "title": "Час прийому їжі — Капха доша"}, {"id": "w1n-menu", "type": "rich_text", "content": [{"kind": "h3", "text": "Що саме їмо"}, {"kind": "ul", "items": [[{"bold": true, "text": "До 8:30 — "}, {"text": "фрукти, сухофрукти, горіхи, насіння, солодкі овочі, рослинні протеїни, спіруліна, хлорела, фукус, зелень. Якщо цього недостатньо — 3 ст. л. вівсяної, гречаної чи пшоняної каші і 250 мл настою. Якщо після масла снідати не хочеться — не їмо, і першу їжу приймаємо до 11:00."}], [{"bold": true, "text": "11:00–13:00 — основний прийом їжі. "}, {"text": "Випиваємо 250 мл настою і їмо будь-яку їжу із дозволених продуктів. Завжди велика порція овочів — у вигляді рагу, супу чи салату — і до них щось поживне: каша, бобові, соя, гриби, хлібці, горіхові пасти (перевіряйте склад)."}], [{"bold": true, "text": "15:00–16:00 — може бути перекус "}, {"text": "(Вата перекушує, іншим конституціям краще пропускати): фрукти, будь-який рослинний білок, овочевий фреш, хлібець, авокадо, зелень, топлене масло."}], [{"bold": true, "text": "18:00–20:00 — вечеря. "}, {"text": "Ідеально овочевий суп, рагу чи салат. Не їмо увечері крупи; можна бобові, насіння, гриби. І знову трав''яний настій — 250 мл."}]]}, {"kind": "p", "text": "Після вечері, не пізніше, ніж за годину до сну, за бажанням можна пити рослинне молоко, можна робити з ним какао."}, {"kind": "p", "text": "Всю їжу готуємо на воді і тільки в самому кінці додаємо топлене масло. Нічого не смажимо на олії — можна протягом кількох хвилин прогріти спеції в топленому маслі."}]}, {"id": "w1n-water", "type": "rich_text", "content": [{"kind": "h3", "text": "Питний режим"}, {"kind": "p", "text": "1 раз на 40–60 хв приймаємо 30–120 мл теплої води."}]}]', '2026-08-19 14:47:31.154378+00', '2026-09-08 15:24:04.29744+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('41d392c4-d026-51f5-b7cb-41298e979aba', 'fb5d1cf1-05b4-552a-9794-cf14a20e85f6', '82e31ee5-c006-55c3-aeee-de0cdabecd6f', 'lesson-6', 'Урок 6 · Основні характеристики Капха доші', 6, NULL, NULL, NULL, '[{"id": "lesson-6-objective", "text": "Розібрати тему «Основні характеристики Капха доші» і співвіднести її з практикою програми.", "type": "lesson_objective"}, {"id": "lesson-6-text-1", "type": "rich_text", "content": [{"kind": "h3", "text": [{"bold": true, "text": "Урок №6"}]}, {"kind": "p", "text": [{"bold": true, "text": "Тема: \"Основні характеристики Капха доші\""}]}]}, {"id": "lesson-6-video-2-1", "type": "video", "title": "Урок №6 — відео", "videoId": "HVnJW_0wioo", "provider": "youtube"}]', '2026-08-23 17:45:07.335344+00', '2026-09-08 15:24:03.034047+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('c4a91d3e-0000-4000-8000-000000000112', 'c4a91d3e-0000-4000-8000-000000000001', 'c4a91d3e-0000-4000-8000-000000000012', 'w1-morning', 'Структура ранку: інгаляція, дихання, Ану тейл, збір', 3, 4, 15, '"Послідовність, з якої починається кожен день програми."', '[{"id": "w1m-objective", "text": "Зібрати ранок в одну послідовність: масло — інгаляція — дихання — краплі — збір — їжа.", "type": "lesson_objective"}, {"id": "w1m-step-1", "step": 1, "text": "Випиваємо 1 чайну чи столову ложку топленого масла, можна більше. Запиваємо двома склянками теплої води — у воду можна додати корицю, імбир, лимон.", "type": "protocol_step", "title": "Масло і тепла вода", "timing": "натщесерце"}, {"id": "w1m-step-2", "step": 2, "text": "Розчиніть 4 ч. л. соди в 1 літрі води, температура води 50–60 градусів. Пар не повинен обпалювати обличчя і слизові оболонки носа й рота. Розчин поміщаємо у глиняну або скляну каструлю, у крайньому випадку в емальовану. Нахиляємося, зверху накриваємося рушником і дихаємо 5–15 хв. Вам повинно бути приємно і комфортно, пульс не повинен прискорюватися.", "type": "protocol_step", "title": "Содова інгаляція"}, {"id": "w1m-step-3", "step": 3, "text": "Капалабхаті — різкі короткі видихи животом через ніс; динаміка така, щоб слиз легко відділявся, 108 повторень. Удіяна бандха — вакуумне втягування живота на затримці дихання після видиху, затримка настільки довга, наскільки комфортно, 3 повторення. Випинання-втягування живота на затримці після видиху — та сама удіяна бандха, але не тримаємо, а відпускаємо і підтягуємо; кількість у межах комфорту, 3 підходи. Те саме, але максимально випинаючи й втягуючи живіт, більше уваги фазі, яка дається найскладніше, 3 підходи. Те саме різко й динамічно — 3 підходи.", "type": "protocol_step", "title": "Маніпуляції животом"}, {"id": "w1m-video-short", "type": "video", "title": "Дихальна гімнастика — короткий варіант", "videoId": "uoXBYxPAOXo", "provider": "youtube"}, {"id": "w1m-video-long", "type": "video", "title": "Дихальна гімнастика — довгий варіант", "videoId": "iz9k-V93dXE", "provider": "youtube"}, {"id": "w1m-step-4", "step": 4, "text": "По 2 краплі в кожну ніздрю, капаємо в положенні лежачи, голова закинута. В ідеалі олія повинна потрапити у лобові пазухи.", "type": "protocol_step", "title": "Краплі Ану тейл"}, {"id": "w1m-anu-cta", "href": "https://rosa-pharm.com/porazitelnye-svojstva-masla-anu-tail/", "text": "Купується в будь-якому аюрведичному інтернет-магазині.", "type": "cta", "label": "Про олію Ану тейл"}, {"id": "w1m-step-5", "step": 5, "text": "Прополоскайте рот водою з сіллю — морською чи чорною гімалайською, вода трохи підсолена. Може пекти, неприємно відчуватися — це нормально. Наступні 5–60 хвилин з вас можуть витікати виділення: прибирайте їх, спльовуйте, але не закривайте ніс хустинкою — просто різко видихайте, як у вправах вище.", "type": "protocol_step", "title": "Полоскання рота"}, {"id": "w1m-step-6", "step": 6, "text": "Після цього можна відпочити або зробити просту зарядку: прокрутити суглоби, зробити простий йога-комплекс, можна прогулятися.", "type": "protocol_step", "title": "Відпочинок або легка зарядка"}, {"id": "w1m-step-7", "step": 7, "text": "Заварюємо 4,5 ч. л. на 800 мл води температурою 80 градусів, настоюємо 40 хв у термосі. За один прийом випиваємо 250 мл. Цей збір знімає спазми з гладкої мускулатури, має легкий сечогінний ефект і готує тіло до складних дій другого етапу.", "type": "protocol_step", "title": "Трав''яний збір і їжа", "timing": "через 20 хв або більше"}]', '2026-08-19 14:47:31.154378+00', '2026-09-08 15:24:04.29744+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('01773449-d936-5da4-8226-36b91bd5a6c9', 'fb5d1cf1-05b4-552a-9794-cf14a20e85f6', '82e31ee5-c006-55c3-aeee-de0cdabecd6f', 'lesson-8', 'Урок 8 · Теорія токсинів', 8, NULL, NULL, NULL, '[{"id": "lesson-8-objective", "text": "Розібрати тему «Теорія токсинів» і співвіднести її з практикою програми.", "type": "lesson_objective"}, {"id": "lesson-8-text-1", "type": "rich_text", "content": [{"kind": "h3", "text": [{"bold": true, "text": "Урок №8"}]}, {"kind": "p", "text": [{"bold": true, "text": "Тема: \"Теорія токсинів\""}]}]}, {"id": "lesson-8-video-2-1", "type": "video", "title": "Урок №8 — відео", "videoId": "6nhlgqUrMw4", "provider": "youtube"}]', '2026-08-23 17:45:07.335344+00', '2026-09-08 15:24:03.034047+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('c4a91d3e-0000-4000-8000-000000000120', 'c4a91d3e-0000-4000-8000-000000000001', 'c4a91d3e-0000-4000-8000-000000000013', 'w2-instruction', 'Тиждень 2-й. Глибоке очищення', 1, 8, 12, '"Режим лишається той самий, змінюється консистенція їжі."', '[{"id": "w2-objective", "text": "Перейти на просту рідку їжу — щоб тіло витрачало сили на очищення, а не на травлення.", "type": "lesson_objective"}, {"id": "w2-regime", "type": "rich_text", "content": [{"kind": "h3", "text": "Режим дня"}, {"kind": "p", "text": "Ранкова олія, вправи, питний режим, процедури, список табу лишаються як на першому етапі."}, {"kind": "p", "text": "Якщо вам важко приймати олію 5+ столових ложок на день, то можна зменшити до трьох. Але три — це мінімум."}, {"kind": "p", "text": "Оскільки їжа тепер буде швидко перетравлюваною, то можна приймати їжу кожні 3 години. Але не їжте тоді, коли не хочеться."}]}, {"id": "w2-diet", "type": "rich_text", "content": [{"kind": "h3", "text": "Дієта"}, {"kind": "p", "text": "Концепція дієти на очищувальному етапі — проста, гіпоалергенна, не подразнююча їжа. Із природними смаками, без смакових домінант: не гірка, не солона, не кисла, не гостра, не занадто солодка — як перший прикорм малюку."}, {"kind": "p", "text": "Продукти лишаються такими ж, як і раніше, але змінюється консистенція: вся їжа повинна бути у вигляді супів-пюре чи смузі із дозволених продуктів."}, {"kind": "p", "text": "Вживаємо їжу 2–3 рази, і тільки при фізичній або емоційній нестачі додаємо ще 2 прийоми. Проміжки між їжею не менше 3 годин."}, {"kind": "p", "text": "Якщо з якихось причин не виходить приймати їжу у рідкому вигляді — їмо просто супи і рагу, але вони повинні бути м''якими, добре звареними і навіть трохи подрібненими виделкою."}]}, {"id": "w2-example", "type": "rich_text", "content": [{"kind": "h3", "text": "Приклад дня"}, {"kind": "ul", "items": [[{"bold": true, "text": "07:00–08:00 — "}, {"text": "смузі із розмочених сухофруктів, горіхів і насіння; смузі із печених солодких овочів, із заморожених ягід, із дозволених фруктів. Також може бути суп-пюре. По можливості цей прийом їжі пропускаємо, обмежуючись відваром і клітковиною, але якщо є справді сильне бажання їсти — тоді їмо."}], [{"bold": true, "text": "11:00 — "}, {"text": "суп-пюре із овочів і злаків чи бобів, грибів. Готуйте саме суп і уже готовий подрібнюйте в блендері: якщо варити кашу й подрібнювати її, вийде паста, і це несмачно."}], [{"bold": true, "text": "14:00–15:00 — "}, {"text": "смузі із фруктів, ягід і розмочених сухофруктів. Також може бути суп-пюре — краще пропускати, можна обійтися топленим маслом."}], [{"bold": true, "text": "18:00–19:00 — "}, {"text": "суп-пюре із овочів, грибів, бобових."}]]}]}, {"id": "w2-basti", "type": "rich_text", "content": [{"kind": "h3", "text": "Що робиться тільки з індивідуальним супроводом"}, {"kind": "p", "text": "Блок клізмування дається лише за показаннями, за психологічної готовності і тільки в пакеті з індивідуальним веденням. Аюрведичні клізми відрізняються від класичних: малий об''єм, бувають очисні й поживні. Задача — очистити товстий кишківник, живити слизові, заспокоїти нервову систему, відновити перистальтику."}]}, {"id": "w2-boundary", "text": "Другий тиждень — найінтенсивніший відрізок програми. Не подовжуйте його самостійно і не додавайте нічого «від себе». Будь-яке різке погіршення стану — пишемо в супровід одразу, а не в кінці тижня.", "type": "boundary_note"}]', '2026-08-19 14:47:31.154378+00', '2026-09-08 15:24:04.29744+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('d47e066c-14d5-5b39-be0b-4b378c249235', 'fb5d1cf1-05b4-552a-9794-cf14a20e85f6', '82e31ee5-c006-55c3-aeee-de0cdabecd6f', 'lesson-7', 'Урок 7 · Причини захворювань. 6 стадій захворювання', 7, NULL, NULL, NULL, '[{"id": "lesson-7-objective", "text": "Розібрати тему «Причини захворювань. 6 стадій захворювання» і співвіднести її з практикою програми.", "type": "lesson_objective"}, {"id": "lesson-7-text-1", "type": "rich_text", "content": [{"kind": "h3", "text": [{"bold": true, "text": "Урок №7"}]}, {"kind": "p", "text": [{"bold": true, "text": "Тема: \"Причини захворювань. 6 стадій захворювання\""}]}]}, {"id": "lesson-7-video-2-1", "type": "video", "title": "Урок №7 — відео", "videoId": "3RyUIQBTYy8", "provider": "youtube"}]', '2026-08-23 17:45:07.335344+00', '2026-09-08 15:24:03.034047+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('7e60c9b3-8c0a-5cac-b2e3-da78dfb23062', 'fb5d1cf1-05b4-552a-9794-cf14a20e85f6', '82e31ee5-c006-55c3-aeee-de0cdabecd6f', 'lesson-9', 'Урок 9 · Теорія смаків', 9, NULL, NULL, NULL, '[{"id": "lesson-9-objective", "text": "Розібрати тему «Теорія смаків» і співвіднести її з практикою програми.", "type": "lesson_objective"}, {"id": "lesson-9-text-1", "type": "rich_text", "content": [{"kind": "h3", "text": [{"bold": true, "text": "Урок №9"}]}, {"kind": "p", "text": [{"bold": true, "text": "Тема: \"Теорія вкусів\""}]}]}, {"id": "lesson-9-video-2-1", "type": "video", "title": "Урок №9 — відео", "videoId": "f1e6n_u3GXQ", "provider": "youtube"}]', '2026-08-23 17:45:07.335344+00', '2026-09-08 15:24:03.034047+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('ce7d6417-cec0-5658-875f-bea56e6318b7', 'fb5d1cf1-05b4-552a-9794-cf14a20e85f6', '7be10864-7465-5aa6-8569-af9766770368', 'lesson-15', 'Урок 15 · Поєднання продуктів', 6, NULL, NULL, NULL, '[{"id": "lesson-15-objective", "text": "Розібрати тему «Поєднання продуктів» і співвіднести її з практикою програми.", "type": "lesson_objective"}, {"id": "lesson-15-text-1", "type": "rich_text", "content": [{"kind": "h3", "text": [{"bold": true, "text": "Урок №15"}]}, {"kind": "p", "text": [{"bold": true, "text": "Тема: \"Поєднання продуктів\""}]}]}, {"id": "lesson-15-video-2-1", "type": "video", "title": "Урок №15 — відео", "videoId": "m9B5OqiFxaU", "provider": "youtube"}]', '2026-08-23 17:45:07.335344+00', '2026-09-08 15:24:03.034047+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('5a212a5a-f02b-5bbf-b7f1-28d6ed0f3f2c', 'fb5d1cf1-05b4-552a-9794-cf14a20e85f6', 'c2aa79bb-decc-521a-ab7e-7c541df5bbe9', 'lesson-21', 'Урок 21 · Баланс Капха доші', 4, NULL, NULL, NULL, '[{"id": "lesson-21-objective", "text": "Розібрати тему «Баланс Капха доші» і співвіднести її з практикою програми.", "type": "lesson_objective"}, {"id": "lesson-21-text-1", "type": "rich_text", "content": [{"kind": "h3", "text": [{"bold": true, "text": "Урок №21"}]}, {"kind": "p", "text": [{"bold": true, "text": "Тема: \"Баланс Капха доші\""}]}]}, {"id": "lesson-21-video-2-1", "type": "video", "title": "Урок №21 — відео", "videoId": "W05NdR8d5iI", "provider": "youtube"}]', '2026-08-23 17:45:07.335344+00', '2026-09-08 15:24:03.034047+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('a3f1c7d2-0000-4000-8000-000000000101', 'a3f1c7d2-0000-4000-8000-000000000001', 'a3f1c7d2-0000-4000-8000-000000000011', 'day-1', 'День 1. Старт практики', 1, 1, 18, '"Карта тижня і міні-комплекс гімнастики на 10 хвилин."', '[{"id": "d1-objective", "text": "Сьогодні ви дивитесь карту тижня і робите перший комплекс — сім вправ на десять хвилин.", "type": "lesson_objective"}, {"id": "d1-cover-plan", "alt": "Обкладинка курсу «Short-Перезавантаження»", "src": "/cw/courses/short/plan.webp", "type": "image"}, {"id": "d1-welcome", "type": "rich_text", "content": [{"kind": "p", "text": "Вітаємо! Раді, що Ви тут. Ось із чого складається тиждень."}]}, {"id": "d1-plan", "type": "rich_text", "content": [{"kind": "h3", "text": "День 1. Старт практики"}, {"kind": "p", "text": "Міні-комплекс «Short-Перезавантаження» — базові 10 хвилин для всього тіла, з текстовим описом кожної вправи."}, {"kind": "h3", "text": "День 2. Налаштування дихання"}, {"kind": "p", "text": "Два комплекси дихальних вправ:"}, {"kind": "ul", "items": ["ранковий — для заряду бадьорості на весь день", "вечірній — для глибокого розслаблення та спокійного сну"]}, {"kind": "h3", "text": "День 3. Занурення в деталі"}, {"kind": "p", "text": "Три докладні відеоуроки та розбір нюансів: як адаптувати кожну вправу під свій поточний стан."}, {"kind": "h3", "text": "День 4–5. Зворотний зв''язок"}, {"kind": "p", "text": "Ви ділитеся відчуттями, ми допомагаємо з тим, що не виходить."}, {"kind": "h3", "text": "День 6. Дайджест"}, {"kind": "p", "text": "Усі матеріали курсу зібрані в одному місці."}, {"kind": "h3", "text": "День 7. Наступний рівень"}, {"kind": "p", "text": "Знайомство з великою системною практикою — ІВЕМ-гімнастикою."}]}, {"id": "d1-boundary", "text": "Гімнастика й дихальні вправи тут — оздоровча практика, а не лікування. Робіть усе в межах комфорту: біль, запаморочення чи задишка означають зупинку, а не «ще трохи». За хронічних станів, високого тиску, вагітності та після травм чи операцій обсяг вправ узгоджується з лікарем.", "type": "boundary_note"}, {"id": "d1-cover", "alt": "Обкладинка уроку: комплекс гімнастики Short-перезавантаження", "src": "/cw/courses/short/day-1-complex.webp", "type": "image"}, {"id": "d1-intro", "type": "rich_text", "content": [{"kind": "p", "text": "Ваш перший крок до кращого самопочуття — міні-комплекс «Short-Перезавантаження». Всього 10 хвилин, і тіло скаже дякую. Спробуйте сьогодні."}]}, {"id": "d1-video", "type": "video", "title": "Комплекс гімнастики «Short-Перезавантаження»", "videoId": "4X4ffF2uuT8", "provider": "youtube", "durationMin": 10}, {"id": "d1-desc-head", "type": "rich_text", "content": [{"kind": "h3", "text": "Опис вправ"}]}, {"id": "d1-step-1", "step": 1, "text": "Вихідне положення: стоячи, руки зігнуті в ліктях, ноги напівзігнуті. Техніка: одночасно виконуємо обертальний рух руками у плечових суглобах і переступаємо ногами, наче йдемо на місці — спочатку обома руками вперед, потім назад, потім поперемінно вперед і назад. Частота помірна, підбирається за відчуттями. Дихання рівномірне: вдих у розслабленому положенні, видих — у момент напруги.", "type": "protocol_step", "title": "Ходьба на місці з одночасним обертанням руками", "timing": "12 разів на кожну руку в обох напрямках"}, {"id": "d1-step-2", "step": 2, "text": "Вихідне положення: руками спираємося на стілець, ноги відставлені приблизно під 45 градусів і напівзігнуті, долоні паралельно на стільці, пальці вперед. Техніка: одночасно ритмічно згинаємо ноги та руки, навантаження розподіляємо індивідуально — в ідеалі рівномірно між руками й ногами. Дихання: вдих унизу, видих угорі.", "type": "protocol_step", "title": "Одночасні напівприсідання та віджимання руками від стільця", "timing": "12 разів"}, {"id": "d1-step-3", "step": 3, "text": "Вихідне положення: руки підняті вгору, стоїмо прямо, ноги на ширині плечей, кисті стиснуті в кулак. Техніка: одночасно, з зусиллям, опускаємо руки з боків ліктями донизу до середини корпусу — кулаки максимально стиснуті — і піднімаємо коліно правої ноги перед собою до грудей. Потім руки із зусиллям угору, ногу вниз. Далі те саме з лівою ногою, і так поперемінно. Дихання: вдих — руки вгорі, видих — руки внизу.", "type": "protocol_step", "title": "Одночасне підняття та опускання рук з напругою та підняттям колін до грудей", "timing": "12 разів"}, {"id": "d1-step-4", "step": 4, "text": "Вихідне положення: сидячи на підлозі, ноги та корпус прямі, руки прямі вздовж тулуба, долонями на підлозі, пальці притиснуті та спрямовані вперед. Техніка: на вдиху піднімаємо таз угору — коліна під 90 градусів, стопи притиснуті до підлоги, руки прямі, корпус рівний, паралельно до підлоги, голова відкинута назад. На видиху повертаємось у вихідне положення.", "type": "protocol_step", "title": "Підняття корпусу «Лавка»", "timing": "12 разів"}, {"id": "d1-step-5", "step": 5, "text": "Вихідне положення: стоячи, руки опущені вздовж корпусу, ноги прямі. Техніка: на вдиху корпусом відхиляємося назад з помірним прогином, руки одночасно йдуть у сторони, назад і вгору. На видиху опускаємося вперед, ноги прямі або ледь зігнуті — без зайвого натягу, за відчуттями — руками торкаємося підлоги.", "type": "protocol_step", "title": "Нахили з прогином", "timing": "12 разів"}, {"id": "d1-step-6", "step": 6, "text": "Вихідне положення: ноги зігнуті в колінах, опора на пальці ніг, п''яти зведені під себе, корпус відкинуто назад, руки за спиною з опорою на підлогу. Техніка: максимально натягуємо стегна, корпус в одній лінії зі стегнами, п''ятами одночасно похитуємо від середини назовні. Дихання рівномірне, довільне.", "type": "protocol_step", "title": "Стретчинг стегон з похитуванням стопами назовні та всередину", "timing": "12 разів"}, {"id": "d1-step-7", "step": 7, "text": "Вихідне положення: сидячи на підлозі, ноги зігнуті попереду, коліна розведені вбік, низ стоп разом, руки на пальцях ніг. Техніка: нахиляємося головою до стоп, підтягуючи себе руками, погойдуючись уперед. Дихання рівномірне, довільне.", "type": "protocol_step", "title": "Стретчинг спини «Зігнута вісімка»", "timing": "12 разів"}, {"id": "d1-about", "type": "rich_text", "content": [{"kind": "h3", "text": "Навіщо цей комплекс"}, {"kind": "p", "text": "Коли ви довго перебуваєте в одному положенні, мало рухаєтеся, коли розум тривалий час сконцентрований над одним завданням і треба підбадьоритися — цей комплекс допомагає швидко відновити функціональність."}, {"kind": "p", "text": "Завдяки нестандартним інтенсивним рухам, рівномірному навантаженню та розтягуванню всіх сухожильно-м''язових меридіанів тіла, активному диханню та прискоренню руху крові й лімфи він дозволяє за 10 хвилин перезавантажити тіло й заново запустити всі системи організму."}, {"kind": "p", "text": "У комплексі всього 7 вправ. Його можна робити для перезавантаження протягом дня або як самостійний короткий комплекс ранкової гімнастики."}]}, {"id": "d1-checklist", "type": "checklist", "items": [{"id": "d1-cl-1", "text": "Ходьба на місці з одночасним обертанням руками"}, {"id": "d1-cl-2", "text": "Одночасні напівприсідання та віджимання руками від стільця"}, {"id": "d1-cl-3", "text": "Одночасне підняття та опускання рук з напругою та підняттям колін до грудей"}, {"id": "d1-cl-4", "text": "Підняття корпусу «Лавка»"}, {"id": "d1-cl-5", "text": "Нахили з прогином"}, {"id": "d1-cl-6", "text": "Стретчинг стегон з похитуванням стопами назовні та всередину"}, {"id": "d1-cl-7", "text": "Стретчинг спини «Зігнута вісімка»"}], "title": "Нагадувалка: порядок вправ"}]', '2026-08-26 19:13:01.853432+00', '2026-09-08 15:24:03.880171+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('a3f1c7d2-0000-4000-8000-000000000102', 'a3f1c7d2-0000-4000-8000-000000000001', 'a3f1c7d2-0000-4000-8000-000000000011', 'day-2', 'День 2. Налаштування дихання', 2, 2, 25, '"Ранковий очисний комплекс і вечірній комплекс пранаям."', '[{"id": "d2-objective", "text": "Сьогодні ви додаєте дихання: очисний комплекс зранку і заспокійливий — перед сном.", "type": "lesson_objective"}, {"id": "d2-cover-morning", "alt": "Обкладинка уроку: ранковий дихальний комплекс", "src": "/cw/courses/short/day-2-morning.webp", "type": "image"}, {"id": "d2-morning-intro", "type": "rich_text", "content": [{"kind": "h3", "text": "Ранковий комплекс"}, {"kind": "p", "text": "Два короткі відео для тих, хто хоче прокидатись з енергією і засинати спокійно. Починаємо з ранкового: він допоможе зарядитися зранку."}, {"kind": "p", "text": "Очисний, пробуджуючий комплекс (активна пранаяма та бандхи) спрямований на глибоке очищення носоглотки, бронхо-легеневої системи та органів черевної порожнини. Він активізує дихальну мускулатуру, діафрагму, кровообіг і запускає інтенсивні процеси внутрішнього очищення."}]}, {"id": "d2-video-morning", "type": "video", "title": "Ранкова дихальна гімнастика (пранаяма)", "videoId": "IRaWCuGZWho", "provider": "youtube"}, {"id": "d2-m-step-1", "step": 1, "text": "Вихідне положення: сидячи з прямою спиною, тіло стабільне, плечі розслаблені. Техніка: різкі короткі активні видихи через ніс, на видиху живіт різко втягується до хребта; вдих відбувається самовільно, без зусилля. Завершення підходу: вдих — руки через сторони вгору, затримка дихання на вдиху комфортний час, видих — м''який нахил уперед. Очищує дихальні шляхи, активізує обмінні процеси й готує тіло до глибшої роботи.", "type": "protocol_step", "title": "Капалабхаті", "timing": "108 повторень, 3 підходи"}, {"id": "d2-m-step-2", "step": 2, "text": "Вихідне положення: стоячи або сидячи, корпус злегка нахилений уперед. Техніка: глибокий вдих, повний видих; на видиху підтягни живіт до хребта, діафрагму — вгору, і затримай дихання на комфортний проміжок. Вихід: коли з''являється імпульс до вдиху — вдихни й повністю відпусти живіт. Масажує внутрішні органи, активує травлення та енергетичний центр.", "type": "protocol_step", "title": "Удіяна бандха (статична)", "timing": "3 підходи"}, {"id": "d2-m-step-3", "step": 3, "text": "Вихідне положення: сидячи з легким нахилом корпуса вперед, коліна м''які, спина витягнута, але розслаблена, долоні спираються на стегна або коліна. Підготовка: глибокий вдих через ніс, повний повільний видих, затримка дихання без повітря. На затримці живіт ритмічно працює без вдиху — рух іде не з напруження, а з усвідомленого контролю діафрагми й черевної стінки. Три варіанти окремо: середня амплітуда, максимальна амплітуда, максимальна швидкість. Увага в центрі живота й діафрагмі; горло, плечі й обличчя лишаються розслабленими. З''явилося тремтіння або дискомфорт — зменш амплітуду або вийди з техніки.", "type": "protocol_step", "title": "Динамічна удіяна бандха", "timing": "кожен варіант по 3 підходи"}, {"id": "d2-m-step-4", "step": 4, "text": "Вихідне положення: стоячи з ногами на ширині таза або сидячи з легким нахилом корпуса вперед, долоні впираються в стегна чи коліна, спина витягнута, шия розслаблена. Робота відбувається на затримці дихання після повного видиху, лише м''язами передньої черевної стінки. Послідовність: обидва прямі м''язи одночасно; далі лише ліва сторона (центр ваги на ліву ногу); далі лише права; потім кругові хвилі — зліва направо 12 обертів, справа наліво 9, зліва направо 7. Рух нагадує перекочування хвилі по колу, без ривків.", "type": "protocol_step", "title": "Ізольована робота м''язів живота", "timing": "кожен етап 2–3 підходи"}, {"id": "d2-morning-about", "type": "rich_text", "content": [{"kind": "h3", "text": "Що дає ранковий комплекс"}, {"kind": "p", "text": "Комплекс побудований за принципом поступового заглиблення: від активного механічного очищення та стимуляції — до глибокого внутрішнього масажу — і до тонкого контролю м''язів живота."}, {"kind": "ul", "items": ["покращує вентиляцію легень і роботу дихальної мускулатури", "активізує крово- та лімфообіг у черевній порожнині", "зменшує застійні явища у внутрішніх органах", "підвищує рівень енергії, ясність і зібраність", "готує тіло до тонших практик пранаями й медитації"]}]}, {"id": "d2-morning-boundary", "text": "Ранковий комплекс не є заспокійливим і не призначений для виконання перед сном. Практикуйте його вранці або в активній частині дня, лише після засвоєння базових технік і за відсутності протипоказань.", "type": "boundary_note"}, {"id": "d2-morning-checklist", "type": "checklist", "items": [{"id": "d2-mcl-1", "text": "Капалабхаті"}, {"id": "d2-mcl-2", "text": "Удіяна бандха (статична)"}, {"id": "d2-mcl-3", "text": "Динамічна удіяна бандха"}, {"id": "d2-mcl-4", "text": "Ізольована робота м''язів живота"}], "title": "Нагадувалка: ранковий комплекс"}, {"id": "d2-cover-evening", "alt": "Обкладинка уроку: вечірній дихальний комплекс", "src": "/cw/courses/short/day-2-evening.webp", "type": "image"}, {"id": "d2-evening-intro", "type": "rich_text", "content": [{"kind": "h3", "text": "Вечірній комплекс"}, {"kind": "p", "text": "Вечірній комплекс пранаям — м''яке поетапне перезавантаження нервової системи, яке переводить тіло й свідомість із режиму активності у стан глибокого спокою та відновлення."}]}, {"id": "d2-video-evening", "type": "video", "title": "Вечірня дихальна практика (пранаяма)", "videoId": "JCcnV2xPSsw", "provider": "youtube"}, {"id": "d2-e-step-1", "step": 1, "text": "Сядь у ваджрасану: коліна на підлозі, стопи під сідницями, таз спирається на п''яти, спина вертикальна, плечі розслаблені. На вдиху відчуй витягнення вздовж хребта, на видиху дозволь корпусу повільно нахилитися вперед — без зусилля й тиску, руки вільно вздовж тіла або на підлозі. У нахилі корпус і живіт м''яко спираються на стегна, спина не «тримається», а стікає вниз; шия вільна, обличчя й щелепи розслаблені. Дихання рівне, без пауз: на вдиху увага рухається вздовж осі хребта вгору, на видиху — повне відпускання напруги.", "type": "protocol_step", "title": "Нахил у ваджрасані", "timing": "щонайменше 12 дихальних циклів"}, {"id": "d2-e-step-2", "step": 2, "text": "Ляж на спину, ноги зігнуті в колінах, стопи на підлозі, руки вздовж тіла долонями догори. На видиху м''яко підтягни коліна до грудей і обхопи їх руками. Поперек розслаблений і притиснутий до підлоги, плечі, шия й обличчя м''які. На вдиху — легке розширення в спині, на видиху — глибоке відпускання напруги в тазі, животі та попереку. Вихід: відпусти руки, постав стопи на підлогу й кілька циклів полежи спокійно.", "type": "protocol_step", "title": "Апанасана", "timing": "12–20 дихальних циклів"}, {"id": "d2-e-step-3", "step": 3, "text": "Зручне положення сидячи зі схрещеними ногами, спина пряма, хребет витягнутий. М''яко звузь голосову щілину, підтягни підборіддя ближче до шиї й дихай через ніс. Вдих і видих рівні за тривалістю, плавні, без зусилля; у горлі виникає ледь чутний внутрішній звук, який супроводжує дихання. Увага повністю на диханні та відчутті руху повітря вздовж горла.", "type": "protocol_step", "title": "Уджайї пранаяма", "timing": "3–5 хвилин, мінімум 12 циклів"}, {"id": "d2-e-step-4", "step": 4, "text": "Сидячи з прямою спиною, права рука в мудрі для пранаями. Закрий праву ніздрю великим пальцем — вдих через ліву; закрий ліву ніздрю безіменним пальцем — видих через праву; вдих через праву — видих через ліву. Це один повний цикл. Дихання повільне, рівне, без затримок, увага слідує за потоком дихання.", "type": "protocol_step", "title": "Наді шодхана пранаяма", "timing": "6–12 циклів"}, {"id": "d2-evening-about", "type": "rich_text", "content": [{"kind": "h3", "text": "Логіка вечірньої практики"}, {"kind": "p", "text": "Комплекс вибудуваний від тіла — до дихання — до внутрішнього балансу: нахил у ваджрасані створює опору і знімає поверхневу напругу, апанасана розслабляє таз і поперек, уджайї заспокоює розум і стабілізує дихання, наді шодхана балансує нервову систему та завершує практику."}]}, {"id": "d2-evening-checklist", "type": "checklist", "items": [{"id": "d2-ecl-1", "text": "Нахил у ваджрасані"}, {"id": "d2-ecl-2", "text": "Апанасана"}, {"id": "d2-ecl-3", "text": "Уджайї пранаяма"}, {"id": "d2-ecl-4", "text": "Наді шодхана пранаяма"}], "title": "Нагадувалка: вечірній комплекс"}]', '2026-08-26 19:13:01.853432+00', '2026-09-08 15:24:03.880171+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('c4a91d3e-0000-4000-8000-000000000122', 'c4a91d3e-0000-4000-8000-000000000001', 'c4a91d3e-0000-4000-8000-000000000013', 'w2-review', 'Підсумок другого тижня', 3, 14, 4, '"Перед виходом: що має бути зроблено і що купити на третій тиждень."', '[{"id": "w2r-objective", "text": "Коректно завершити очисний етап і підготуватися до виходу.", "type": "lesson_objective"}, {"id": "w2r-checklist", "type": "checklist", "items": [{"id": "w2r-c1", "text": "Тиждень рідкої їжі пройдено"}, {"id": "w2r-c2", "text": "Збір і клітковина приймались за схемою"}, {"id": "w2r-c3", "text": "Звіти надіслані"}, {"id": "w2r-c4", "text": "Куплено лимони, апельсини й спеції для кислого напою"}], "title": "Завершення етапу", "requiredForCompletion": true}]', '2026-08-19 14:47:31.154378+00', '2026-09-08 15:24:04.29744+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('00d8ab10-51d7-5b37-a6d0-f89aab1937ff', 'fb5d1cf1-05b4-552a-9794-cf14a20e85f6', '7be10864-7465-5aa6-8569-af9766770368', 'lesson-10', 'Урок 10 · Властивості фруктів', 1, NULL, NULL, NULL, '[{"id": "lesson-10-objective", "text": "Розібрати тему «Властивості фруктів» і співвіднести її з практикою програми.", "type": "lesson_objective"}, {"id": "lesson-10-text-1", "type": "rich_text", "content": [{"kind": "h3", "text": [{"bold": true, "text": "Урок №10"}]}, {"kind": "p", "text": [{"bold": true, "text": "Тема: Властивості фруктів"}, {"text": "🍏"}]}]}, {"id": "lesson-10-video-2-1", "type": "video", "title": "Урок №10 — відео", "videoId": "As7n9M5DU28", "provider": "youtube"}]', '2026-08-23 17:45:07.335344+00', '2026-09-08 15:24:03.034047+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('04d97003-9762-5419-992e-58e16fa85a41', 'fb5d1cf1-05b4-552a-9794-cf14a20e85f6', '7be10864-7465-5aa6-8569-af9766770368', 'lesson-11', 'Урок 11 · Властивості овочів', 2, NULL, NULL, NULL, '[{"id": "lesson-11-objective", "text": "Розібрати тему «Властивості овочів» і співвіднести її з практикою програми.", "type": "lesson_objective"}, {"id": "lesson-11-text-1", "type": "rich_text", "content": [{"kind": "h3", "text": [{"bold": true, "text": "Урок №11"}]}, {"kind": "p", "text": [{"bold": true, "text": "Тема: Властивості овочів"}]}]}, {"id": "lesson-11-video-2-1", "type": "video", "title": "Урок №11 — відео", "videoId": "RI3cQh09DAY", "provider": "youtube"}]', '2026-08-23 17:45:07.335344+00', '2026-09-08 15:24:03.034047+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('be6ae51b-ecab-5dae-9f80-d6c48085d7db', 'fb5d1cf1-05b4-552a-9794-cf14a20e85f6', '7be10864-7465-5aa6-8569-af9766770368', 'lesson-12', 'Урок 12 · Злаки, бобові та горіхи', 3, NULL, NULL, NULL, '[{"id": "lesson-12-objective", "text": "Розібрати тему «Злаки, бобові та горіхи» і співвіднести її з практикою програми.", "type": "lesson_objective"}, {"id": "lesson-12-text-1", "type": "rich_text", "content": [{"kind": "h3", "text": [{"bold": true, "text": "Урок №12"}]}, {"kind": "p", "text": [{"bold": true, "text": "Тема: \"Злаки. Бобові. Горіхи\""}, {"text": "🌾"}]}]}, {"id": "lesson-12-video-2-1", "type": "video", "title": "Урок №12 — відео", "videoId": "plZpR1W1MqU", "provider": "youtube"}]', '2026-08-23 17:45:07.335344+00', '2026-09-08 15:24:03.034047+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('a3f1c7d2-0000-4000-8000-000000000103', 'a3f1c7d2-0000-4000-8000-000000000001', 'a3f1c7d2-0000-4000-8000-000000000011', 'day-3', 'День 3. Занурення в деталі', 3, 3, 30, '"Три докладні розбори технік."', '[{"id": "d3-objective", "text": "Сьогодні ви розбираєте техніку — щоб вправи працювали, а не просто повторювались.", "type": "lesson_objective"}, {"id": "d3-cover", "alt": "Обкладинка уроку: докладні відео розборів", "src": "/cw/courses/short/day-3-details.webp", "type": "image"}, {"id": "d3-intro", "type": "rich_text", "content": [{"kind": "p", "text": "Це докладні відео міні-комплексу гімнастики «Short-Перезавантаження», ранкового та вечірнього комплексів дихальних вправ. Додаткове пояснення допомагає швидше опанувати техніку виконання і адаптувати вправи під свій поточний стан."}]}, {"id": "d3-video-gym", "type": "video", "title": "Пояснення до комплексу Short-Перезавантаження", "videoId": "n_8XdTi-148", "provider": "youtube"}, {"id": "d3-video-morning", "type": "video", "title": "Пояснення до ранкової дихальної гімнастики", "videoId": "qrdzbl3nhM0", "provider": "youtube"}, {"id": "d3-video-evening", "type": "video", "title": "Пояснення до вечірньої дихальної гімнастики", "videoId": "iUvgrgpsFT4", "provider": "youtube"}]', '2026-08-26 19:13:01.853432+00', '2026-09-08 15:24:03.880171+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('b7e6f2a1-0000-4000-8000-000000000105', 'b7e6f2a1-0000-4000-8000-000000000001', 'b7e6f2a1-0000-4000-8000-000000000012', 'recipes', 'Рецепти супів', 1, NULL, 8, '"Рецепти супів для проведення розвантажувального дня в аюрведичній концепції."', '[{"id": "rec-objective", "text": "П''ять супів для підготовки і для розвантажувального дня. Кожен рецепт позначено за конституцією — обери свій.", "type": "lesson_objective"}, {"id": "rec-1", "type": "rich_text", "content": [{"kind": "h3", "text": "1. Легке огіркове гаспачо"}, {"kind": "p", "text": "Рецепт на 2-4 порції."}, {"kind": "p", "text": "Варимо в ідеалі на пару: 1 свіжий лук порей і 1 зубчик часнику — давленого. Варимо 5 хв, щоб знизити гостроту з овочів. Далі чистимо від шкіри 3 середні огірки і ріжемо їх великими скибками. Беремо ½ стакану дрібно нарізаної петрушки."}, {"kind": "p", "text": "Скласти огірки, петрушку, лук порей, часник у блендер і додати:"}, {"kind": "ul", "items": ["Сік 1 лимону", "1 склянка охолодженого бульйону від овочів", "3-5 с.л оливкової олії", "сіль за смаком, але все одно трошки", "⅛ ч.л каєнського перцю", "⅛ ч.л чорного перцю"]}, {"kind": "p", "text": "Збити в блендері 30-60 сек, до однорідної маси."}, {"kind": "p", "text": [{"bold": true, "text": "Рецепт гарно підходить Капха доші"}, {"text": ", не зловживаючи — для Вати і Пітти."}]}]}, {"id": "rec-2", "type": "rich_text", "content": [{"kind": "h3", "text": "2. Суп із брокколі"}, {"kind": "p", "text": "Рецепт на 2-4 порції."}, {"kind": "p", "text": "Варимо в ідеалі на пару: 1-2 склянки нарізаного брокколі, включаючи верхню частину ніжки. 1 ст.л нарізаного луку порей або звичайний лук (лук не обов''язково). Варимо 3-5 хв."}, {"kind": "p", "text": "Складаємо в блендер:"}, {"kind": "ul", "items": ["2 ст.л сирих волоських горіхів чи кешью", "Сіль за смаком"]}, {"kind": "p", "text": "Гомогенізуємо горіхи і додаємо варені овочі, подрібнюємо до однорідної консистенції. Можна додати перець за смаком."}, {"kind": "p", "text": [{"bold": true, "text": "Рецепт підходить всім конституціям."}]}]}, {"id": "rec-3", "type": "rich_text", "content": [{"kind": "h3", "text": "3. Поживний овочевий суп"}, {"kind": "p", "text": "Рецепт на 4 порції."}, {"kind": "ul", "items": ["½ склянки ячмінної крупи", "8-10 склянок чистої води", "1 ч.л лаврового листа", "1 ч.л солі, чи за смаком"]}, {"kind": "p", "text": "Поки все вариться, додаємо:"}, {"kind": "ul", "items": ["2 моркви нарізані і ненарізана зелень від моркви — її можна не їсти, але вона надасть приємний смак і корисні властивості", "2 пучка селери дрібно нарізати", "1 склянка нарізаної петрушки", "2 ст.л нарізаного луку (необов''язково)", "1 зубок часнику, не очищений від шкіри", "1-3 склянки картоплі або ріпи (для Капхи точно ріпа)"]}, {"kind": "p", "text": "Варите 40-50 хв, потім додати:"}, {"kind": "ul", "items": ["1 невеликий пучок шпинату", "½ ч.л сушеного чебрецю", "чорний перець за смаком"]}, {"kind": "p", "text": "Після цього ще варити 2-5 хв і в кінці можна додати гхі, особливо для Вата доші."}, {"kind": "p", "text": [{"bold": true, "text": "Добре підходить Вата конституції"}, {"text": ", гарно для ослабленої Пітта конституції, для Капхи — без гхі і картоплі. Не екадашний рецепт."}]}]}, {"id": "rec-4", "type": "rich_text", "content": [{"kind": "h3", "text": "4. Суп «шатаварі»"}, {"kind": "p", "text": "Рецепт на 4 порції."}, {"kind": "p", "text": "Тушити декілька хвилин у сковорідці з товстим дном:"}, {"kind": "ul", "items": ["1 невелика цибулина", "2 зубчики часнику, давленого", "2 стакана різаної спаржі"]}, {"kind": "p", "text": "Тушимо на невеликій кількості топленого масла гхі. Додаємо 4 склянки води і варити 30-40 хв, або менше, до приємного стану."}, {"kind": "p", "text": "В цей час подрібнюємо ½ склянки соняшникового насіння. Коли овочі готові, додаємо бульйон у насіння і повільно перемішуємо у блендері; овочі також можна подрібнити або залишити цілими."}, {"kind": "p", "text": "У кінці додаємо сіль та перець за смаком та ¼ подрібненого мускатного горіха."}, {"kind": "p", "text": [{"bold": true, "text": "Підходить всім конституціям"}, {"text": ", Вата дошу укріплює."}]}]}, {"id": "rec-5", "type": "rich_text", "content": [{"kind": "h3", "text": "5. Буряковий суп «Борщ»"}, {"kind": "p", "text": "Рецепт на 2 порції."}, {"kind": "p", "text": "У чотирьох склянках води варимо 3 середні, дрібно нарізані буряки — якщо молоді, то можна з бадиллям. 1 см кореня імбиру, очищеного. Накрити кришкою і варити приблизно 40 хв."}, {"kind": "p", "text": "Коли готово, у блендері подрібнюємо до консистенції густого супу. Додаємо сіль, перець за смаком. Оливкову олію першого холодного віджиму — 1-3 ст.л."}, {"kind": "p", "text": [{"bold": true, "text": "Підходить всім конституціям."}]}]}]', '2026-08-17 12:08:01.694619+00', '2026-09-08 15:24:03.462767+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('c4a91d3e-0000-4000-8000-000000000113', 'c4a91d3e-0000-4000-8000-000000000001', 'c4a91d3e-0000-4000-8000-000000000012', 'w1-review', 'Підсумок першого тижня', 4, 7, 5, '"Звіряємося перед найінтенсивнішим відрізком програми."', '[{"id": "w1r-objective", "text": "Переконатися, що вхід пройдено чесно — від цього залежить, як пройде другий тиждень.", "type": "lesson_objective"}, {"id": "w1r-checklist", "type": "checklist", "items": [{"id": "w1r-c1", "text": "Режим дня вирівняно: сон до 23:00, їжа за часом своєї доші"}, {"id": "w1r-c2", "text": "Гхі приймаю щодня, мінімум 3 ст. л."}, {"id": "w1r-c3", "text": "Збір п''ю 3 рази на день"}, {"id": "w1r-c4", "text": "Ранкова послідовність робиться щодня"}, {"id": "w1r-c5", "text": "Звіти надсилаю Євгенію"}], "title": "Готовність до другого тижня", "requiredForCompletion": true}, {"id": "w1r-report-cta", "href": "https://t.me/E_Koriakin", "text": "Звіт за тиждень — у чат.", "type": "cta", "label": "Надіслати звіт"}]', '2026-08-19 14:47:31.154378+00', '2026-09-08 15:24:04.29744+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('c4a91d3e-0000-4000-8000-000000000141', 'c4a91d3e-0000-4000-8000-000000000001', 'c4a91d3e-0000-4000-8000-000000000015', 'recipes', 'Рецепти солодощів', 3, NULL, 8, '"Солодке, яке можна на програмі."', '[{"id": "rc-objective", "text": "Закрити потребу в солодкому, не виходячи з протоколу.", "type": "lesson_objective"}, {"id": "rc-h1", "type": "rich_text", "content": [{"kind": "h3", "text": "Солодощі, що не підвищують рівень цукру в крові"}, {"kind": "p", "text": "Максимально рекомендовані на програмі."}]}, {"id": "rc-almond", "text": "1/4 склянки мигдальної пасти, 1/4 склянки топленої олії гхі, 2 ст. л. какао-порошку без цукру, стевія за смаком (тут 10 крапель, можна мед). Розтопіть у мисці олію гхі і мигдальну пасту, ретельно перемішайте. Додайте стевію і какао-порошок. Перелийте в посудину, викладіть суміш у формочки, поставте в холодильник мінімум на 30 хвилин. Зберігайте в холодильнику в щільно закритому контейнері. Можна використовувати будь-яку горіхову пасту.", "type": "practice_block", "title": "Мигдальні цукерки", "durationMin": 10}, {"id": "rc-nuts", "text": "1½ склянки цільних горіхів макадамія, ¼ склянки молотого насіння льону / чіа / конопляного, ½ склянки арахісової пасти, ¼ склянки топленої олії гхі, ½ склянки кокосової стружки без цукру, стевія 5–10 крапель або мед. У кухонному комбайні в імпульсному режимі подрібніть горіхи, насіння, арахісову пасту й гхі. Перекладіть у миску, додайте стевію за смаком, додайте кокосову стружку і обережно перемішайте. Помістіть у холодильник на 30–45 хвилин, поки суміш не стане достатньо твердою. Зробіть 10 кульок (приблизно 1 ст. л. на кульку), помістіть у холодильник ще на 15–20 хв, обваляйте в кокосовій стружці. Зберігати в герметичному контейнері в холодильнику. У цих цукерках надзвичайно багато корисних жирів — якщо потрібно поснідати, з''їжте одну.", "type": "practice_block", "title": "Горіхово-насіннєві цукерки — 10 штук", "durationMin": 25}, {"id": "rc-peanut", "text": "¼ склянки топленої олії гхі, ¼ склянки арахісової пасти без добавок, 2 ст. л. какао-порошку без цукру, 1 ст. л. ксиліту або меду за смаком. Помістіть інгредієнти в ємність для водяної бані й розтопіть (мед можна додати після розтоплення). Перелийте масу у глечик з носиком, розлийте по силіконових формах, помістіть у морозилку приблизно на годину. Витягніть із форм; щоб цукерки були хрумкішими, посипте подрібненим арахісом. Не кладіть більше підсолоджувача, ніж потрібно. Шукайте арахісову пасту з одного інгредієнта — перемеленого нежареного арахісу.", "type": "practice_block", "title": "Арахісові цукерки — 3 штуки", "durationMin": 30}, {"id": "rc-ghee-choc", "text": "15 г топленої олії гхі, 30–40 г какао-порошку, 3–5 г меду. Підігрійте гхі, змішайте всі інгредієнти, розділіть на рівні частини й надайте будь-яку форму. Можна їсти одразу або трохи охолодити в холодильнику.", "type": "practice_block", "title": "Гхі-шоколад", "durationMin": 5}, {"id": "rc-h2", "type": "rich_text", "content": [{"kind": "h3", "text": "Солодощі, що підвищують рівень цукру в крові"}, {"kind": "p", "text": "Їх можна їсти в невеликій кількості у перший прийом їжі. Стараємось обмежувати."}]}, {"id": "rc-apple-pear", "text": "1 яблуко, 1 груша, 1 ст. л. ізюму, 1 гвоздика, ¼ чашки води. Фрукти очистіть від шкірки і наріжте тонкими пластинками, помістіть у неглибоку каструлю з водою, додайте ізюм і гвоздику. Доведіть до кипіння і залиште на повільному вогні 5–10 хвилин, поки фрукти не стануть м''якими. З''їжте страву теплою: з''їдені вранці яблука допомагають виробленню оджасу — кінцевого продукту засвоєння їжі.", "type": "practice_block", "title": "Яблучно-грушевий сніданок", "durationMin": 15}, {"id": "rc-apple-bar", "text": "1½ чашки грецьких горіхів, 1 чашка сушених яблук, 1 чашка фініків, ¼ ч. л. кориці, 1/8 ч. л. імбиру, 1/8 ч. л. солі. Змішати в блендері всі інгредієнти до утворення клейкої маси; якщо потрібно, додати ще фініків. Перекласти масу у форму 17,5×17,5 см або 20×20 см, застелену пергаментом, обережно прим''яти. Помістити в холодильник мінімум на 2 години і розрізати на 8 частин. Зберігати у герметичному контейнері в холодильнику.", "type": "practice_block", "title": "Яблучний батончик"}, {"id": "rc-triple", "text": "100 г чорносливу, 100 г ізюму чи інжиру (помити, ошпарити окропом, пропустити через м''ясорубку), 100 мл топленої олії гхі, 100 г меду, 50 г листя сени (купіть в аптеці й додатково перемеліть). Перемішайте всі інгредієнти до однорідної густої суміші, скачайте кульки із 1 ч. л., покладіть у банку, закрийте кришкою й поставте в холодильник. М''який спосіб очистити кишківник — допомагає за 8 годин.", "type": "practice_block", "title": "Цукерка потрійної дії"}, {"id": "rc-triple-boundary", "text": "«Цукерка потрійної дії» містить листя сени — це проносний засіб. Не більше 1 чайної ложки увечері. Не давати дітям, не приймати за вагітності, лактації, кишкових захворювань і разом з іншими проносними.", "type": "boundary_note"}, {"id": "rc-brownie", "text": "250 г грецьких горіхів, 1 склянка какао-порошку, ¼ ч. л. солі, 500 г фініків без кісточки, 100 г сирого несоленого мигдалю (опціонально). Подрібніть грецькі горіхи до стану порошку, змішайте з какао і сіллю, знову збийте в блендері; поки блендер працює, поступово додавайте фініки — суміш повинна нагадувати сиру липку масу. Подрібніть ножем мигдаль і змішайте. Мокрими руками сформуйте тонкий пласт на харчовому папері, відправте в холодильник, щоб легше нарізалися.", "type": "practice_block", "title": "Сирі брауні"}]', '2026-08-19 14:47:31.154378+00', '2026-09-08 15:24:04.29744+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('cae9b828-fdf2-4967-bae8-5a1cad34cc79', '1082476a-db78-4dd2-ad51-da4001d3a9ec', '563d835a-e74c-4728-a95a-9155a98c3b1a', 'how-to', 'Як користуватися', 1, NULL, NULL, NULL, '[{"id": "1b54d01f-b47b-4af7-810e-b7c947856fbc", "text": "[ЗАПОВНИ: для чого цей урок]", "type": "lesson_objective"}, {"id": "b3272c95-f384-45dc-b897-845eacbb2149", "type": "rich_text", "content": [{"kind": "p", "text": "[ЗАПОВНИ: текст]"}]}]', '2026-08-28 16:15:06.153406+00', '2026-08-28 16:15:06.153406+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('c6552a81-c893-4ebc-9e0f-a2c6779ddf83', '1082476a-db78-4dd2-ad51-da4001d3a9ec', '5f956238-a039-43e4-9713-488eafb0bfa1', 'section-1', 'Розділ 1', 1, NULL, NULL, NULL, '[{"id": "bfe9c43d-643d-49cf-84a5-da7361aea83a", "type": "rich_text", "content": [{"kind": "p", "text": "[ЗАПОВНИ: текст]"}]}, {"id": "daa720d3-5202-4ac6-8d79-4e6979991887", "head": ["[ЗАПОВНИ: колонка 1]", "[ЗАПОВНИ: колонка 2]"], "rows": [["[ЗАПОВНИ: клітинка]", "[ЗАПОВНИ: клітинка]"]], "type": "table"}]', '2026-08-28 16:15:06.153406+00', '2026-08-28 16:15:06.153406+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('987adaa2-81b4-4327-b51c-abe2d2f6faf8', '1082476a-db78-4dd2-ad51-da4001d3a9ec', '5f956238-a039-43e4-9713-488eafb0bfa1', 'section-2', 'Розділ 2', 2, NULL, NULL, NULL, '[{"id": "637d3585-2003-420e-a7b8-bc5daae00fe1", "type": "rich_text", "content": [{"kind": "p", "text": "[ЗАПОВНИ: текст]"}]}, {"id": "705d18bc-f104-426a-8aea-d88b1ca4c867", "type": "faq_block", "items": [{"id": "a4b6476e-a4d7-4b1e-a768-771920989040", "answer": "[ЗАПОВНИ: відповідь]", "question": "[ЗАПОВНИ: питання]"}]}]', '2026-08-28 16:15:06.153406+00', '2026-08-28 16:15:06.153406+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('a3f1c7d2-0000-4000-8000-000000000107', 'a3f1c7d2-0000-4000-8000-000000000001', 'a3f1c7d2-0000-4000-8000-000000000011', 'day-7', 'День 7. Наступний рівень', 7, 7, 8, '"Куди йти далі після міні-курсу."', '[{"id": "d7-objective", "text": "Ви почали. Далі — системна щоденна практика, якщо схочете глибше.", "type": "lesson_objective"}, {"id": "d7-cover", "alt": "Обкладинка уроку: ІВЕМ-гімнастика", "src": "/cw/courses/short/day-7-ivem.webp", "type": "image"}, {"id": "d7-intro", "type": "rich_text", "content": [{"kind": "p", "text": "За цей час Ви зробили важливе — почали. Short-Перезавантаження — це як перший подих свіжого повітря. Але є система, яка йде набагато глибше."}, {"kind": "p", "text": "ІВЕМ-гімнастика — великий щоденний комплекс, який м''яко, але системно змінює тіло і самопочуття:"}, {"kind": "ul", "items": ["енергія на весь день", "здорові суглоби і спина", "гарна постава і легкість у тілі", "спокійний сон і відновлення", "вдома, без обладнання, у будь-якому віці"]}, {"kind": "p", "text": "Підходить для будь-якого рівня підготовки. Навіть якщо здається, що «я не спортивна(ий)», — саме для Вас і створено."}]}, {"id": "d7-irem-cta", "href": "/programs/irem", "text": "Велика щоденна практика після міні-курсу.", "type": "cta", "label": "Подивитись ІВЕМ-гімнастику"}]', '2026-08-26 19:13:01.853432+00', '2026-09-08 15:24:03.880171+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('8149c50c-c64d-5dc8-bf63-6b3f75b78dd6', 'fb5d1cf1-05b4-552a-9794-cf14a20e85f6', '7be10864-7465-5aa6-8569-af9766770368', 'lesson-13', 'Урок 13 · Властивості рослинних олій та молочних продуктів', 4, NULL, NULL, NULL, '[{"id": "lesson-13-objective", "text": "Розібрати тему «Властивості рослинних олій та молочних продуктів» і співвіднести її з практикою програми.", "type": "lesson_objective"}, {"id": "lesson-13-text-1", "type": "rich_text", "content": [{"kind": "h3", "text": [{"bold": true, "text": "Урок №13"}]}, {"kind": "p", "text": [{"bold": true, "text": "Тема: \"Властивості Рослинних олій та молочних продуктів\""}]}]}, {"id": "lesson-13-video-2-1", "type": "video", "title": "Урок №13 — відео", "videoId": "BTM40xb_EUo", "provider": "youtube"}]', '2026-08-23 17:45:07.335344+00', '2026-09-08 15:24:03.034047+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('24905938-5840-4dc2-a9a4-fe8668f3f4ee', '0faafa48-0f49-4f38-927a-210eec33b8df', 'a2d89899-ffa8-4114-9b4e-a2c3f2167713', 'urok-2', '01  /  MORNING', 2, NULL, NULL, '"RESET • Очищення & потік "', '[{"id": "1ff32ed6-42f8-4110-b541-b3fe0daa85f5", "text": "Ранковий ритуал для м’якого пробудження тіла, уваги та дихального патерну. ", "type": "boundary_note"}, {"id": "2712110c-3bac-44fc-a463-3d3eaba0a8b0", "step": 1, "text": "Фокус: діафрагма та відчуття простору в зоні нижніх ребер.", "type": "protocol_step", "title": "Міофасціальний реліз", "timing": "Виконати 3–4 цикли."}, {"id": "0dd0250f-1881-4ffd-a408-ca1d81280e1b", "type": "rich_text", "content": [{"kind": "ul", "items": ["Лягти на спину, коліна зігнуті, стопи на підлозі.", "Зробити спокійний глибокий видих.", "М’яко розмістити пальці під реберною дугою.", "На вдиху — зменшити тиск і розслабитися.", "На видиху — дуже делікатно поглибити контакт.", "Виконати 3-4 цикли "]}]}, {"id": "911498d5-f165-4cf7-9ff3-1d882d2b39dd", "step": 2, "text": "у перекладі з санскриту — «замок зльоту/підйому» або «черевний замок». Це класичний йогічний замок (бандха), який виконується шляхом повного видиху та втягування органів черевної порожнини вгору та під ребра.", "type": "protocol_step", "title": "Уддіяна бандха", "timing": "3–5 циклів  •  затримка 5–10 секунд"}, {"id": "f15687fd-0482-4883-84ae-4a4296f6b068", "type": "rich_text", "content": [{"kind": "ul", "items": ["Стати, трохи зігнути коліна, руки — на стегна.", "Повністю видихнути.", "Затримати дихання.", "Виконати м’який «хибний вдих» без набору повітря.", "Дозволити животу втягнутися під ребра.", "Утримувати 5–10 секунд.", "Плавно відпустити та відновити дихання."]}]}, {"id": "ac9d84d3-8239-45cc-89ac-d6501f65aa57", "text": "КЛЮЧ Практика виконується без силового напруження. Язик може м’яко лежати біля верхнього піднебіння.", "type": "quote", "author": "Автор"}]', '2026-08-30 18:04:23.145312+00', '2026-09-01 14:07:15.53448+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('a13314c9-dfc8-522f-975d-24acfe97c0fa', 'fb5d1cf1-05b4-552a-9794-cf14a20e85f6', '7be10864-7465-5aa6-8569-af9766770368', 'lesson-14', 'Урок 14 · Властивості спецій та підсолоджувачів', 5, NULL, NULL, NULL, '[{"id": "lesson-14-objective", "text": "Розібрати тему «Властивості спецій та підсолоджувачів» і співвіднести її з практикою програми.", "type": "lesson_objective"}, {"id": "lesson-14-text-1", "type": "rich_text", "content": [{"kind": "h3", "text": [{"bold": true, "text": "Урок №14"}]}, {"kind": "p", "text": [{"bold": true, "text": "Тема: \"Властивості спецій та підсолоджувачів\""}]}]}, {"id": "lesson-14-video-2-1", "type": "video", "title": "Урок №14 — відео", "videoId": "OoIWfBqFSFM", "provider": "youtube"}]', '2026-08-23 17:45:07.335344+00', '2026-09-08 15:24:03.034047+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('b7e6f2a1-0000-4000-8000-000000000100', 'b7e6f2a1-0000-4000-8000-000000000001', 'b7e6f2a1-0000-4000-8000-000000000011', 'intro', 'Технічна інформація по проходженню практикуму', 1, NULL, 6, '"Прочитайте обов''язково."', '[{"id": "intro-objective", "text": "Перед стартом: як влаштований практикум, де підтримка і що важливо розуміти про сам формат.", "type": "lesson_objective"}, {"id": "intro-boundary-main", "text": "Один розвантажувальний день — це три дні уваги та дисципліни. Некоректно починати голодування чи умовне голодування, не підготувавшись до нього належним чином. У деяких випадках необхідна консультація фахівця. В іншому випадку — ви можете собі нашкодити.", "type": "boundary_note"}, {"id": "intro-video", "type": "video", "title": "Вітальне відео", "videoId": "KzIq5GgcyvA", "provider": "youtube"}, {"id": "intro-support", "type": "rich_text", "content": [{"kind": "h3", "text": "Технічні непорозуміння по практикуму"}, {"kind": "p", "text": "Якщо у вас виникнуть технічні непорозуміння по проходженню практикуму на платформі, не будуть відкриватися уроки чи виникнуть проблеми зі входом у кабінет — одразу напишіть у телеграм."}]}, {"id": "intro-support-cta", "href": "https://telegram.me/centerway_support_bot", "type": "cta", "label": "Технічна підтримка CenterWay"}]', '2026-08-17 08:38:55.458595+00', '2026-09-08 15:24:03.462767+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('8b041ddf-8176-4468-a847-6ad26f155967', '3bf946d7-31a1-4767-b9fd-409310e58956', '3d440582-72ce-4d2c-91c6-1b5cd3c4539a', 'lesson-1', 'Урок 1', 1, NULL, NULL, NULL, '[{"id": "73c1388c-5d18-4a48-9b45-82d452c843f5", "text": "[ЗАПОВНИ: для чого цей урок]", "type": "lesson_objective"}]', '2026-09-09 10:48:35.437287+00', '2026-09-09 10:48:35.437287+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('c4a91d3e-0000-4000-8000-000000000131', 'c4a91d3e-0000-4000-8000-000000000001', 'c4a91d3e-0000-4000-8000-000000000014', 'w3-food-return', 'Послідовний вхід у тверду їжу', 2, 16, 10, '"Сім днів, за які раціон повертається — по одному кроку на день."', '[{"id": "w3f-objective", "text": "Повернути тверду їжу так, щоб травлення встигало за раціоном.", "type": "lesson_objective"}, {"id": "w3f-days", "type": "rich_text", "content": [{"kind": "h3", "text": "День за днем"}, {"kind": "ol", "items": ["Із твердої їжі можна каші. Також у цей день можна вживати молочні продукти. Пийте фреші — тільки із тих продуктів, що описані нижче", "Можна додати відварену або тушковану рибу, зелень і цільнозерновий хліб", "Паровий омлет або варені некруто яйця", "М''який сир, рагу із овочів з рисом. Картопля поки що ні", "Вводимо м''ясо у вигляді тефтелі чи парової котлети", "З 6-го дня починаємо їсти усе те ж саме, що і під час першого тижня", "До 7 дня виходу приходимо до дієти 1-го етапу плюс ті продукти, які ввели за інструкцією вище. Більше нічого не додаємо"]}, {"kind": "p", "text": "Кожен наступний день нам можна дозволені продукти поточного дня плюс продукти попереднього. Усе інше — у рідкому вигляді."}]}, {"id": "w3f-fresh", "text": "Кожного дня пийте морквяний та гарбузовий фреш. 1 раз на день пийте чорносливовий коктейль: замочіть на ніч в''ялений чорнослив (10–15 шт) у 250 мл води, зранку збийте блендером і вживайте.", "type": "practice_block", "title": "Фреші й чорносливовий коктейль"}, {"id": "w3f-closing", "type": "rich_text", "content": [{"kind": "p", "text": "Будьте уважні цього тижня, не поспішайте. Виконуючи всі інструкції, ви навчитеся харчуватися найкращим для себе способом."}]}]', '2026-08-19 14:47:31.154378+00', '2026-09-08 15:24:04.29744+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('c4a91d3e-0000-4000-8000-000000000143', 'c4a91d3e-0000-4000-8000-000000000001', 'c4a91d3e-0000-4000-8000-000000000015', 'prepare', 'Що підготувати — по тижнях', 1, NULL, 6, '"Список зібраний із інструкцій усіх трьох тижнів, щоб не бігати по магазинах у день, коли воно вже потрібне."', '[{"id": "prep-objective", "text": "Заздалегідь бачити, що знадобиться на кожному тижні — і купити це спокійно.", "type": "lesson_objective"}, {"id": "prep-note", "type": "rich_text", "content": [{"kind": "p", "text": "Нічого нового тут немає: усе перелічене нижче вже описано в уроках відповідних тижнів. Ця сторінка просто збирає покупки в одному місці й відкрита від першого дня."}]}, {"id": "prep-all", "type": "rich_text", "content": [{"kind": "h3", "text": "На всі три тижні"}, {"kind": "ul", "items": [[{"bold": true, "text": "Топлена олія гхі — "}, {"text": "головний продукт програми: 5–7 ст. л. на день, мінімум 3. Рахуйте одразу на 21 день або домовляйтесь про докупівлю."}], [{"bold": true, "text": "Краплі Ану тейл — "}, {"text": "для процедури насья, щодня зранку. Купуються в аюрведичному інтернет-магазині."}], [{"bold": true, "text": "Кунжутна олія — "}, {"text": "для розтирання долонь, стоп і тіла зранку і ввечері (можна замінити топленою)."}], [{"bold": true, "text": "Фітозбори №1–№3 і клітковина — "}, {"text": "надсилає автор. Щоб вони приїхали вчасно, адресу треба написати в перший день."}]]}]}, {"id": "prep-w1", "type": "rich_text", "content": [{"kind": "h3", "text": "Тиждень 1 — процедури"}, {"kind": "ul", "items": ["Гімалайська сіль і сульфат магнію (англійська сіль) — по 0,25 склянки на ванну, тричі на тиждень", "Яблучний оцет — 3 склянки на ванну", "Евкаліптова олія — 15 крапель на ванну", "Харчова сода — 4 ч. л. на літр води для інгаляції, щодня", "Морська або чорна гімалайська сіль — для полоскання рота після насьї"]}]}, {"id": "prep-w2", "type": "rich_text", "content": [{"kind": "h3", "text": "Тиждень 2 — рідке харчування"}, {"kind": "ul", "items": ["Блендер — весь тиждень їжа у вигляді супів-пюре і смузі", "Овочі, крупи, бобові, гриби на супи-пюре; фрукти, ягоди й розмочені сухофрукти на смузі", "Чиста вода — 2–2,5 л на добу, теплою, малими порціями"]}]}, {"id": "prep-w3", "type": "rich_text", "content": [{"kind": "h3", "text": "Тиждень 3 — вихід"}, {"kind": "ul", "items": ["Лимони (обов''язково), апельсини, імбир — основа кислого напою перед кожним прийомом їжі", "Кардамон, фенхель, кориця, гвоздика, мед — за смаком у той самий напій", "В''ялений чорнослив — 10–15 шт. на добу для коктейлю", "Морква і гарбуз — на щоденні фреші", "Далі по днях: каші й молочні, риба і цільнозерновий хліб, яйця, м''який сир і рис, м''ясо на пару"]}]}, {"id": "prep-sweets", "type": "rich_text", "content": [{"kind": "h3", "text": "Якщо готуватимете солодощі"}, {"kind": "p", "text": "Рецепти — в окремому уроці. Базовий набір: горіхова або арахісова паста, какао-порошок без цукру, підсолоджувач (стевія, ксиліт або мед), кокосова стружка, горіхи макадамія й грецькі, фініки, насіння льону, чіа чи конопляне."}]}, {"id": "prep-boundary", "text": "Склад зборів і будь-які заміни підбираються під вашу конституцію й стан — не збирайте трави самостійно «за списком». За хронічних станів, вагітності, лактації та прийому препаратів усе узгоджується з лікарем.", "type": "boundary_note"}]', '2026-08-19 18:14:14.495912+00', '2026-09-08 15:24:04.29744+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('c4a91d3e-0000-4000-8000-000000000140', 'c4a91d3e-0000-4000-8000-000000000001', 'c4a91d3e-0000-4000-8000-000000000015', 'webinars', 'Вебінари', 4, NULL, 5, '"Три записані зустрічі з автором — теорія, якої вистачає надовго після курсу."', '[{"id": "wb-objective", "text": "Розібрати логіку методу — щоб ви розуміли, навіщо кожен крок протоколу.", "type": "lesson_objective"}, {"id": "wb-1", "type": "video", "title": "Вебінар 1. Базові основи аюрведи", "videoId": "w2MM1kk_vFY", "provider": "youtube"}, {"id": "wb-2", "type": "video", "title": "Вебінар 2. Жіноче здоров''я з аюрведою", "videoId": "VXtl3BmAC1A", "provider": "youtube"}, {"id": "wb-3", "type": "video", "title": "Вебінар 3. Зміна сезонів і очищення організму", "videoId": "En0gUb8LBQA", "provider": "youtube"}]', '2026-08-19 14:47:31.154378+00', '2026-09-08 15:24:04.29744+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('c4a91d3e-0000-4000-8000-000000000142', 'c4a91d3e-0000-4000-8000-000000000001', 'c4a91d3e-0000-4000-8000-000000000015', 'reports', 'Звітність', 5, NULL, 3, '"Щоденний звіт — це те, за чим автор бачить вашу динаміку."', '[{"id": "rp-objective", "text": "Вести звіт так, щоб супровід був предметним.", "type": "lesson_objective"}, {"id": "rp-how", "type": "rich_text", "content": [{"kind": "p", "text": "Звіт надсилаємо щодня Євгенію в чат у телеграм. Структура — за прикладом нижче."}]}, {"id": "rp-example", "href": "https://docs.google.com/document/d/1asJSbV6Vg-cvFuD06gccYdkAj_y2iuSOaLt46TZDK9U/edit", "text": "Google-документ зі структурою щоденного звіту.", "type": "cta", "label": "Приклад звіту"}, {"id": "rp-send", "href": "https://t.me/E_Koriakin", "text": "Щодня, протягом усієї програми.", "type": "cta", "label": "Надіслати звіт у Telegram"}]', '2026-08-19 14:47:31.154378+00', '2026-09-08 15:24:04.29744+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('1d358974-ec6e-50fa-8143-5b4378cd3bb0', 'fb5d1cf1-05b4-552a-9794-cf14a20e85f6', 'c2aa79bb-decc-521a-ab7e-7c541df5bbe9', 'lesson-20', 'Урок 20 · Баланс Пітта доші', 3, NULL, NULL, NULL, '[{"id": "lesson-20-objective", "text": "Розібрати тему «Баланс Пітта доші» і співвіднести її з практикою програми.", "type": "lesson_objective"}, {"id": "lesson-20-text-1", "type": "rich_text", "content": [{"kind": "h3", "text": [{"bold": true, "text": "Урок №20"}]}, {"kind": "p", "text": [{"bold": true, "text": "Тема: \"Баланс Пітта доші\""}]}]}, {"id": "lesson-20-video-2-1", "type": "video", "title": "Урок №20 — відео", "videoId": "8Kye1nZEEDc", "provider": "youtube"}]', '2026-08-23 17:45:07.335344+00', '2026-09-08 15:24:03.034047+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('6fb1fad5-49a9-50c5-bab8-549c05e4b85b', 'fb5d1cf1-05b4-552a-9794-cf14a20e85f6', 'fcd4165b-638c-5136-9d16-407132b3d7c1', 'recipes', 'Рецепти солодощів, які можна вживати під час проходження програми', 1, NULL, NULL, NULL, '[{"id": "recipes-objective", "text": "Використовувати рецепти як довідковий матеріал і враховувати індивідуальну переносимість продуктів.", "type": "lesson_objective"}, {"id": "recipes-image-1", "alt": "Домашні горіхові цукерки в кунжуті на тарілці", "src": "/cw/courses/natural-body/recipe-almond-candies.webp", "type": "image"}, {"id": "recipes-text-2", "type": "rich_text", "content": [{"kind": "p", "text": [{"text": "Солодощі без білого цукру, які автор курсу рекомендує вживати помірно під час програми", "italic": true}]}, {"kind": "h3", "text": [{"bold": true, "text": "Мигдальні цукерки"}]}, {"kind": "p", "text": "Можна використовувати будь-яку горіхову пасту + топлене масло"}, {"kind": "p", "text": "Олія Гхі + какао-порошок + підсолоджувач."}, {"kind": "p", "text": "Це рецепт цукерок із мигдальної пасти. Вона допоможе вам залишатися ситим. Можна використовувати будь-який підсолоджувач, тут використана стевія."}, {"kind": "p", "text": [{"bold": true, "text": "ЧАС НА ПРИГОТУВАННЯ:"}, {"text": "10 хв."}]}, {"kind": "p", "text": [{"bold": true, "text": "ІНГРЕДІЄНТИ:"}]}, {"kind": "ul", "items": ["1/4 склянки мигдальної пасти", "1/4 склянки топленої олії гхі", "2 ст. л. какао-порошку без цукру", "Стевія – за смаком. Тут використано 10 крапель, можна використовувати мед."]}, {"kind": "p", "text": "СПОСІБ ПРИГОТУВАННЯ:"}, {"kind": "ol", "items": ["Розтопіть у мисці олію Гхі і мигдальну пасту. Ретельно перемішайте.", "Додайте стевію і какао-порошок.", "Перелийте в посудину.", "Викладіть суміш у формочки.", "Поставте в холодильник мінімум на 30 хвилин."]}, {"kind": "p", "text": "Зберігайте в холодильнику в щільно закритому контейнері."}]}, {"id": "recipes-text-3", "type": "rich_text", "content": [{"kind": "h3", "text": [{"bold": true, "text": "Горіхово-насіннєві цукерки"}]}, {"kind": "p", "text": "У цих цукерках надзвичайно багато корисних жирів із горіхів і насіння. Якщо вам потрібно поснідати, з’їжте одну таку цукерку."}, {"kind": "p", "text": [{"bold": true, "text": "ЧАС:"}, {"text": "25 ХВИЛИН"}]}, {"kind": "p", "text": [{"bold": true, "text": "КІЛЬКІСТЬ:"}, {"text": "10 штук"}]}, {"kind": "p", "text": [{"bold": true, "text": "ІНГРЕДІЄНТИ:"}]}, {"kind": "ul", "items": ["Горіхи макадамія - 1 1⁄2 склянки (цільні)", "Насіння льону / чіа / конопляне насіння - 1⁄4 склянки (молоті)", "Арахісова паста - 1⁄2 склянки", "Топлена олія Гхі - 1⁄4 склянки", "Кокосова стружка без цукру - 1⁄2 склянки", "Стевія - 5-10 крапель, можна використовувати мед."]}, {"kind": "p", "text": [{"bold": true, "text": "СПОСІБ ПРИГОТУВАННЯ:"}]}, {"kind": "ol", "items": ["В кухонному комбайні в імпульсному режимі подрібніть горіхи макадамія, насіння (можна попередньо перемолоти в кавомолці), арахісову пасту, топлену олію Гхі. Перекладіть суміш в миску і додайте стевію за смаком (5-10 крапель).", "Додайте кокосову стружку і обережно перемішайте. Помістіть суміш в холодильник на 30-45 хвилин, поки вона не стане достатньо твердою - такою, щоб із неї можна було зробити цукерки.", "Зробіть 10 кульок (приблизно 1 столова ложка суміші на одну кульку). Помістіть в холодильник ще на 15-20 хв.", "Обваляйте в кокосовій стружці!"]}, {"kind": "p", "text": "Зберігайте в герметичному контейнері в холодильнику."}]}, {"id": "recipes-image-4", "alt": "Горіхово-насіннєві цукерки у паперових формочках", "src": "/cw/courses/natural-body/recipe-nut-seed-candies.webp", "type": "image"}, {"id": "recipes-text-5", "type": "rich_text", "content": [{"kind": "h3", "text": [{"bold": true, "text": "Арахісові цукерки"}]}, {"kind": "p", "text": [{"bold": true, "text": "ЧАС:"}, {"text": "30 минут"}]}, {"kind": "p", "text": [{"bold": true, "text": "КІЛЬКІСТЬ:"}, {"text": "3 штуки"}]}, {"kind": "p", "text": "Це швидкий рецепт цукерки із арахісової пасти з какао для ласунів, щоб їм не довелося зовсім відмовлятися від солодкого."}, {"kind": "p", "text": "Прислухайтесь до свого тіла. Не кладіть більше підсолоджувача, ніж це потрібно."}, {"kind": "p", "text": "Постарайтесь знайти арахісову пасту із одного-єдиного інгредієнта: перемеленого арахісу (не жареного)."}, {"kind": "p", "text": "“Водяна баня” в цьому рецепті використовується для того, щоб жоден інгредієнт не нагрівався напряму, і, щоб при розтоплюванні продуктів нічого не пригоріло."}, {"kind": "p", "text": "Ємність для “водяної бані” ставлять на каструлю з гарячою водою і продовжують підігрівати на середньому вогні."}, {"kind": "p", "text": [{"bold": true, "text": "ІНГРЕДІЄНТИ:"}]}, {"kind": "ul", "items": ["Топлена олія Гхі - 1⁄4 склянки", "Арахісова паста (без добавок) - 1⁄4 склянки", "Какао-порошок без цукру - 2 столові ложки", "Ксиліт (ксилітол) (в порошку чи гранульований). Можна використовувати мед - 1 столова ложка чи за смаком."]}, {"kind": "p", "text": [{"bold": true, "text": "СПОСІБ ПРИГОТУВАННЯ:"}]}, {"kind": "ol", "items": ["Помістіть топлену олію Гхі, арахісову пасту, какао-порошок і ксиліт в ємність для водяної бані. Можна використовувати мед.", "Розтопіть (мед можна додати після розтоплення).", "Перелийте масу у глечик з “носиком”, щоб не забруднити все навколо.", "Розлийте суміш по силіконовим формам.", "Помістіть в морозилку приблизно на годину.", "Витягніть “жиро-бомби” із форм. Щоб цукерки були ще більш хрумкими, посипте їх подрібненим арахісом. Зберігайте в герметичному контейнері в холодильнику."]}]}, {"id": "recipes-text-6", "type": "rich_text", "content": [{"kind": "h3", "text": [{"bold": true, "text": "Гхі шоколад"}]}, {"kind": "p", "text": [{"bold": true, "text": "ЧАС ПРИГОТУВАННЯ:"}, {"text": "5 хв"}]}, {"kind": "p", "text": [{"bold": true, "text": "ІНГРЕДІЄНТИ:"}]}, {"kind": "ul", "items": ["Топлена олія Гхі - 15 гр", "Какао порошок 30-40 гр", "Мед 3-5 гр"]}, {"kind": "p", "text": [{"bold": true, "text": "СПОСІБ ПРИГОТУВАННЯ:"}]}, {"kind": "ol", "items": ["Змішайте всі інгредієнти разом, попередньо підігрівши олію Гхі", "Розділіть на рівні частини", "Надайте будь-яку форму"]}, {"kind": "p", "text": "Можна їсти одразу або трішки охолодити перед вживанням у холодильнику."}, {"kind": "p", "text": [{"text": "Солодощі, що підвищують рівень цукру в крові. Їх можна їсти в невеликій кількості у перший прийом їжі. Стараємся обмежувати.", "italic": true}]}]}, {"id": "recipes-text-7", "type": "rich_text", "content": [{"kind": "h3", "text": [{"bold": true, "text": "Яблучно-грушевий сніданок"}]}, {"kind": "p", "text": [{"bold": true, "text": "ЧАС ПРИГОТУВАННЯ:"}, {"text": "15 хв"}]}, {"kind": "p", "text": [{"bold": true, "text": "ІНГРЕДІЄНТИ:"}]}, {"kind": "ul", "items": ["1 яблуко", "1 груша", "1 ст.л. ізюму", "1 гвоздика", "1/4 чашка води"]}, {"kind": "p", "text": [{"bold": true, "text": "СПОСІБ ПРИГОТУВАННЯ:"}]}, {"kind": "ol", "items": ["Фрукти очистіть від шкірки і, наріжте тонкими пластинками.", "Помістіть в не глибоку кастрюлю з ¼ чашками води. Додайте ізюм і гвоздику.", "Доведіть до кипіння і залиште кипіти на повільному вогні протягом 5-10 хвилин – до тих пір, поки фрукти не стануть м''якими."]}, {"kind": "p", "text": "З''їжте страву, поки вона тепла. З''їдені вранці яблука допомагають виробленню оджасу – кінцевого продукту засвоєння їжі. Оджас допомагає підвищити життєву енергію, імунітет організму і покращує загальне самопочуття."}]}, {"id": "recipes-image-8", "alt": "Запечені груші з прянощами на світлій тарілці", "src": "/cw/courses/natural-body/recipe-baked-pears.webp", "type": "image"}, {"id": "recipes-text-9", "type": "rich_text", "content": [{"kind": "h3", "text": [{"bold": true, "text": "Яблучний батончик"}]}, {"kind": "p", "text": [{"bold": true, "text": "ІНГРЕДІЄНТИ:"}]}, {"kind": "ul", "items": ["1 1⁄2 чашки грецьких горіхів", "1 чашка сушених яблук", "1 чашка фініків", "1⁄4 чайної ложки кориці", "1/8 чайної ложки імбиру", "1/8 чайної ложки солі"]}, {"kind": "p", "text": [{"bold": true, "text": "ПРИГОТУВАННЯ:"}]}, {"kind": "ol", "items": ["Змішати в блендері всі інгредієнти до утворення клейкої маси. Якщо потрібно, додати ще фініків, для клейкості.", "Перекласти масу в форму розміром 17,5х17,5 см або 20х20 см, застелену пергаментом, обережно прим’яти.", "Помістити в холодильник мінімум на 2 години і розрізати на 8 частин."]}, {"kind": "p", "text": "Зберігати у герметичному контейнері в холодильнику."}]}, {"id": "recipes-senna-boundary", "text": "Рецепт із сеною нижче — не звичайний десерт і не універсально безпечний засіб. Не використовуйте його для самолікування або для дітей без попереднього погодження з лікарем чи фармацевтом.", "type": "boundary_note"}, {"id": "recipes-text-10", "type": "rich_text", "content": [{"kind": "h3", "text": [{"bold": true, "text": "Цукерка потрійної дії"}]}, {"kind": "p", "text": "Рецепт із сеною, який у вихідному курсі подано як засіб із проносною дією. Він потребує окремої обережності та не є звичайним десертом."}, {"kind": "p", "text": "Головне - стриматися і не з''їсти більше 1 чайної ложки! Не використовуйте цей рецепт для дітей без попереднього погодження з лікарем або фармацевтом."}, {"kind": "p", "text": [{"bold": true, "text": "ІНГРЕДІЄНТИ:"}]}, {"kind": "ul", "items": ["100 гр чорносливу", "100 гр ізюму чи інжиру (помити і ошпарити кип’ятком, пропустити через м’ясорубку)", "100 мл топленої олії Гхі", "100 гр меду", "50 гр листя сени (купіть в аптеці і додатково перемеліть в кавоварці)."]}, {"kind": "p", "text": [{"bold": true, "text": "СПОСІБ ПРИГОТУВАННЯ:"}]}, {"kind": "ol", "items": ["Перемішайте всі інгредієнти - у вас повинна вийти однорідна густа суміш.", "Скачайте кульки із 1 ч. ложки.", "Покладіть в банку, закрийте кришкою, поставте в холодильник - вистачає надовго і гарно зберігається."]}, {"kind": "p", "text": "! 1 чайну ложку увечері - не більше!"}]}, {"id": "recipes-text-11", "type": "rich_text", "content": [{"kind": "h3", "text": [{"bold": true, "text": "Сирі брауні або корисні батончики"}]}, {"kind": "p", "text": [{"bold": true, "text": "ІНГРЕДІЄНТИ:"}]}, {"kind": "ul", "items": ["250 г грецьких горіхів", "1 склянка какао-порошку", "1/4 чайної ложки солі", "500 г фініків без кісточки", "100 г сирого не солоного мигдалю (опціонально)"]}, {"kind": "p", "text": [{"bold": true, "text": "СПОСІБ ПРИГОТУВАННЯ:"}]}, {"kind": "ol", "items": ["Подрібніть грецькі горіхи до стану порошку. Змішайте з какао і сіллю і знову збийте в блендері. Поки блендер працює, поступово додавайте в суміш фініки. В кінці, суміш повинна нагадувати сиру липку масу.", "Подрібніть ножем мигдаль і змішайте з фініковою сумішшю. Мокрими руками сформуйте із приготованої суміші тонкий пласт на харчовому папері. Відправте в холодильник, щоб вони легше нарізалися на батончики. Можна надати іншу форму - на ваш розсуд."]}]}]', '2026-08-23 17:45:07.335344+00', '2026-09-08 15:24:03.034047+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('a0c20a3d-b07c-512a-96e9-07e64097a957', 'fb5d1cf1-05b4-552a-9794-cf14a20e85f6', '7be10864-7465-5aa6-8569-af9766770368', 'lesson-16', 'Урок 16 · Цикли доби', 7, NULL, NULL, NULL, '[{"id": "lesson-16-objective", "text": "Розібрати тему «Цикли доби» і співвіднести її з практикою програми.", "type": "lesson_objective"}, {"id": "lesson-16-text-1", "type": "rich_text", "content": [{"kind": "h3", "text": [{"bold": true, "text": "Урок №16"}]}, {"kind": "p", "text": [{"bold": true, "text": "Тема: \"Цикли доби\""}, {"text": "⏳"}]}]}, {"id": "lesson-16-video-2-1", "type": "video", "title": "Урок №16 — відео", "videoId": "O8EkDRclFN4", "provider": "youtube"}]', '2026-08-23 17:45:07.335344+00', '2026-09-08 15:24:03.034047+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('02886986-0a74-50f7-8005-2297d03d95a0', 'fb5d1cf1-05b4-552a-9794-cf14a20e85f6', '7be10864-7465-5aa6-8569-af9766770368', 'lesson-17', 'Урок 17 · Розбір денного циклу харчування', 8, NULL, NULL, NULL, '[{"id": "lesson-17-objective", "text": "Розібрати тему «Розбір денного циклу харчування» і співвіднести її з практикою програми.", "type": "lesson_objective"}, {"id": "lesson-17-text-1", "type": "rich_text", "content": [{"kind": "h3", "text": [{"bold": true, "text": "Урок №17"}]}, {"kind": "p", "text": [{"bold": true, "text": "Тема: Розбір денного циклу харчування."}]}]}, {"id": "lesson-17-video-2-1", "type": "video", "title": "Урок №17 — відео", "videoId": "dbNrlnc-tKE", "provider": "youtube"}]', '2026-08-23 17:45:07.335344+00', '2026-09-08 15:24:03.034047+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('12b6a0fe-b4b2-4394-87b7-2043672d8957', '0faafa48-0f49-4f38-927a-210eec33b8df', 'a2d89899-ffa8-4114-9b4e-a2c3f2167713', 'urok-4', '03  /  EVENING', 4, NULL, NULL, '"RESTORE • Баланс & відновлення"', '[{"id": "9574012e-7a84-488e-871d-200fcf14f48c", "text": "Вечірній ритуал для уповільнення, переходу від активності до спокою та підготовки до сну.", "type": "lesson_objective"}, {"id": "79d77ab1-1d0c-4c25-8c93-1fb675167d41", "step": 1, "text": "(часто плутають або поєднують з Наді Шодхана) — це класична пранаяма змінного дихання через праву і ліву ніздрі, яка перекладається як «природне і протилежне» або «за шерстю і проти шерсті». У класичній хатха-йозі це базовий етап освоєння дихальних практик перед складнішими затримками.", "type": "protocol_step", "title": "Анулома Вілома", "timing": "Співвідношення 1 : 2  •  10–15 хвилин"}, {"id": "90f34fdc-6e82-4ba4-b088-7bf576568af7", "type": "rich_text", "content": [{"kind": "p", "text": [{"bold": true, "text": "Техніка виконання"}]}, {"kind": "p", "text": "Сядьте зручно, спина пряма без напруги. Праву руку складіть у Насагра Мудру."}, {"kind": "p", "text": "ОДИН ЦИКЛ"}, {"kind": "ul", "items": ["Закрити праву ніздрю великим пальцем.", "Вдих через ліву — 4 рахунки.", "Закрити ліву, відкрити праву.", "Видих через праву — 8 рахунків.", "Вдих через праву — 4 рахунки.", "Видих через ліву — 8 рахунків.", "Повторювати 10–15 хвилин"]}]}, {"id": "0118c6c4-05b7-4ca8-9844-4e98045e98b9", "text": [{"bold": true, "text": "Завершення:"}, {"text": " Залиштеся на кілька природних циклів дихання та дозвольте тілу перейти до спокою без додаткового зусилля. "}], "type": "quote", "author": "Автор"}, {"id": "f5c590fb-69b4-4b94-b9e8-2ff9209da392", "text": [{"bold": true, "text": "КЛЮЧ"}, {"text": " Не форсуйте довжину видиху. Якщо співвідношення 1:2 некомфортне, скоротіть рахунок, зберігаючи м’якість."}], "type": "boundary_note"}]', '2026-08-30 18:04:23.145312+00', '2026-09-01 14:07:15.53448+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('e727431b-839e-559e-a533-5a8e622f644c', 'fb5d1cf1-05b4-552a-9794-cf14a20e85f6', 'c2aa79bb-decc-521a-ab7e-7c541df5bbe9', 'lesson-18', 'Урок 18 · Гуни матеріальної природи', 1, NULL, NULL, NULL, '[{"id": "lesson-18-objective", "text": "Розібрати тему «Гуни матеріальної природи» і співвіднести її з практикою програми.", "type": "lesson_objective"}, {"id": "lesson-18-text-1", "type": "rich_text", "content": [{"kind": "h3", "text": [{"bold": true, "text": "Урок №18"}]}, {"kind": "p", "text": [{"bold": true, "text": "Тема: \"Гуни матеріальної природи\""}]}]}, {"id": "lesson-18-video-2-1", "type": "video", "title": "Урок №18 — відео", "videoId": "bKDdoWB2Fms", "provider": "youtube"}]', '2026-08-23 17:45:07.335344+00', '2026-09-08 15:24:03.034047+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('cc7b01ee-0201-4000-8000-000000000005', 'cc7b01ee-0000-4000-8000-000000000001', 'cc7b01ee-0200-4000-8000-000000000001', 'day-5', 'Урок №5. П''ятниця', 5, 5, NULL, NULL, '[{"id": "ivem-day-5-objective", "text": "Пройти авторську практику для дня «П''ятниця».", "type": "lesson_objective"}, {"id": "ivem-day-5-boundary", "text": "Практика має освітній і wellness-формат та не замінює медичну діагностику чи лікування. Зупиніть вправу, якщо вона викликає біль, запаморочення або інше погіршення самопочуття, і за потреби зверніться до кваліфікованого фахівця.", "type": "boundary_note"}, {"id": "ivem-day-5-video", "type": "video", "title": "Урок №5. П''ятниця", "videoId": "hkTngVgvprI", "provider": "youtube"}, {"id": "ivem-day-5-text-1", "type": "rich_text", "content": [{"kind": "h3", "text": "Інтегральна відновлювальна енергомоделююча гімнастика"}, {"kind": "p", "text": "Опис вправ"}, {"kind": "p", "text": "1 частина"}, {"kind": "p", "text": "Виділення енергії та прокачування енергетичних насосів"}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "\"Масайські\" стрибки - підстрибування вгору з однієї точки"}, {"kind": "p", "text": "Стоїмо прямо, ноги разом."}, {"kind": "p", "text": "Максимально підстрибуємо вертикально вгору, трохи допомагаючи собі руками, 12 разів"}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Згинання рук з максимальною напругою внизу вгору"}, {"kind": "p", "text": "Початкове положення – стоячи, руки вздовж тіла, кулаки стиснуті."}, {"kind": "p", "text": "На видиху повільно з максимальною напругою згинаємо руки в ліктях внутрішньою стороною кулаків до грудей. На вдиху вільно опускаємо, 12 разів"}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Згинання рук із зусиллям від боків до середини грудей"}, {"kind": "p", "text": "Початкове положення – стоячи, руки відведені убік, кулаки стиснуті."}, {"kind": "p", "text": "На видиху повільно з максимальною напругою рук та грудних м''язів зводимо руки до центру грудей, на вдиху відводимо убік, 12 разів"}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Підстрибування з високим підняттям колін"}, {"kind": "p", "text": "Початкове положення – стоячи, руки зігнуті у ліктях."}, {"kind": "p", "text": "Підстрибуємо на місці, максимально високо підіймаючи коліна, 12 разів"}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Розгинання рук із зусиллям від середини грудей убік"}, {"kind": "p", "text": "Початкове положення – стоячи, руки притиснуті до центру грудей, кулаки стиснуті."}, {"kind": "p", "text": "На видиху, повільно з максимальною напругою розгинаємо руки в сторони задньою поверхнею руки нагору, на вдиху повертаємо до грудей, 12 разів"}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Згинання рук з напругою верхньої частини спини та шиї"}, {"kind": "p", "text": "Початкове положення – стоячи, руки вздовж тіла, кулаки стиснуті, верхня частина кулаків дивиться вперед."}, {"kind": "p", "text": "На видиху повільно з максимальною напругою згинаємо руки в ліктях, зовнішньою стороною кулаків вгору, плечі підіймаємо, на вдиху опускаємо, 12 разів"}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Підстрибування з присіданням на пальцях ніг"}, {"kind": "p", "text": "Вихідне положення - сидячи навприсядки, на пальцях ніг."}, {"kind": "p", "text": "На видиху підстрибуємо на місці, на вдиху приземляємось у вихідне положення, 12 разів"}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Згинання рук із зусиллям від боків до голови"}, {"kind": "p", "text": "Початкове положення – стоячи, руки в сторони долонями догори, кулаки стиснуті."}, {"kind": "p", "text": "На видиху з максимальною напругою згинаємо руки до голови, на вдиху повертаємо у вихідне положення, 12 разів"}]}]', '2026-08-23 20:30:19.041894+00', '2026-09-08 15:24:02.326472+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('d908afe9-4250-4a2e-b6ef-c2264f93a1d8', '0faafa48-0f49-4f38-927a-210eec33b8df', 'a2d89899-ffa8-4114-9b4e-a2c3f2167713', 'lesson-1', 'ЯК КОРИСТУВАТИСЯ', 1, NULL, NULL, '"Один день. Три точки повернення. "', '[{"id": "1ac2c299-35f5-4264-8c35-8dc4fef8729a", "type": "rich_text", "content": [{"kind": "p", "text": "Цей протокол створений як проста домашня практика між процедурами, тілесними заняттями та періодами відновлення. Його ритм — м’який рух від активації вранці до фокусування вдень і заспокоєння ввечері."}]}, {"id": "04dacc60-17c5-43fe-9632-9c745ffe9e9d", "text": "ПРИНЦИП Не потрібно змінювати весь день. Іноді достатньо змінити спосіб, у який ви дихаєте.", "type": "quote", "author": "Веди"}, {"id": "3d168c22-f656-4daf-89bd-bc945728e009", "type": "rich_text", "content": [{"kind": "h3", "text": "М’яка рамка практики"}, {"kind": "ul", "items": ["Оберіть стійке, комфортне положення та залишайтеся в межах природного дихання"]}, {"kind": "ul", "items": ["Не форсуйте амплітуду, затримку або тривалість; якість важливіша за інтенсивність"]}, {"kind": "ul", "items": ["Після практики коротко відмітьте, що змінилося у вашому стані."]}]}, {"id": "a883ea9e-2ea0-4595-9c03-f9094c14bc76", "text": [{"bold": true, "text": "БЕЗПЕКА "}, {"text": "Практикуйте без болю, запаморочення чи надмірного зусилля. Якщо техніка викликає дискомфорт — припиніть її та зверніться до фахівця. Матеріал не замінює медичну консультацію. "}], "type": "boundary_note"}]', '2026-08-28 16:24:11.231166+00', '2026-09-01 14:07:15.53448+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('cc7b01ee-0201-4000-8000-000000000006', 'cc7b01ee-0000-4000-8000-000000000001', 'cc7b01ee-0200-4000-8000-000000000001', 'day-6', 'Урок №6. Субота', 6, 6, NULL, NULL, '[{"id": "ivem-day-6-objective", "text": "Пройти авторську практику для дня «Субота».", "type": "lesson_objective"}, {"id": "ivem-day-6-boundary", "text": "Практика має освітній і wellness-формат та не замінює медичну діагностику чи лікування. Зупиніть вправу, якщо вона викликає біль, запаморочення або інше погіршення самопочуття, і за потреби зверніться до кваліфікованого фахівця.", "type": "boundary_note"}, {"id": "ivem-day-6-video", "type": "video", "title": "Урок №6. Субота", "videoId": "6sob0ip22iw", "provider": "youtube"}, {"id": "ivem-day-6-text-1", "type": "rich_text", "content": [{"kind": "h3", "text": "Інтегральна відновлювальна енергомоделююча гімнастика"}, {"kind": "p", "text": "Опис вправ"}, {"kind": "p", "text": "1 частина"}, {"kind": "p", "text": "Виділення енергії та прокачування енергетичних насосів"}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "«Сходинка»"}, {"kind": "p", "text": "Початкове положення – стоїмо на пальцях ніг на високому порозі чи сходинці, руками притримуємося для збереження рівноваги."}, {"kind": "p", "text": "На вдиху максимально опускаємо п''яти нижче порога, на видиху максимально підіймаємося вище за поріг 1 підхід на максимум"}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Присідання на верхній частині стопи із опорою на руки."}, {"kind": "p", "text": "Вихідне положення - опора на зовнішню сторону пальців стопи, ноги прямі, корпус нахилений вперед, руки впираються в лаву, стілець, диван."}, {"kind": "p", "text": "ÐÐ° Ð²Ð´Ð¸ÑINSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('cc7b01ee-0201-4000-8000-000000000007', 'cc7b01ee-0000-4000-8000-000000000001', 'cc7b01ee-0200-4000-8000-000000000001', 'day-7', 'Урок №7. Неділя', 7, 7, NULL, NULL, '[{"id": "ivem-day-7-objective", "text": "Пройти авторську практику для дня «Неділя».", "type": "lesson_objective"}, {"id": "ivem-day-7-boundary", "text": "Практика має освітній і wellness-формат та не замінює медичну діагностику чи лікування. Зупиніть вправу, якщо вона викликає біль, запаморочення або інше погіршення самопочуття, і за потреби зверніться до кваліфікованого фахівця.", "type": "boundary_note"}, {"id": "ivem-day-7-video", "type": "video", "title": "Урок №7. Неділя", "videoId": "wGb3uAfCasM", "provider": "youtube"}, {"id": "ivem-day-7-text-1", "type": "rich_text", "content": [{"kind": "h3", "text": "Інтегральна відновлювальна енергомоделююча гімнастика"}, {"kind": "p", "text": "Опис вправ"}, {"kind": "p", "text": "1 частина"}, {"kind": "p", "text": "Виділення енергії та прокачування енергетичних насосів"}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Імітація ударів ногою поперемінно вперед"}, {"kind": "p", "text": "Початкове положення – стоячи, ліва нога трохи попереду, права ззаду, руки зігнуті."}, {"kind": "p", "text": "На видиху правою ногою імітуємо удар ногою вперед, на вдиху повертаємось у вихідне положення, міняємо ноги, імітуємо удар вперед лівою ногою і навпаки, 12 разів"}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Імітація ударів двома долонями разом уперед"}, {"kind": "p", "text": "Початкове положення - стоячи, руки зігнуті в ліктях і притиснуті до корпусу."}, {"kind": "p", "text": "На видиху імітуємо удар двома руками вперед відкритими долонями, пальці вгору, на вдиху повертаємось у вихідне положення 12 разів"}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Імітація ударів ногами поперемінно убік"}, {"kind": "p", "text": "Вихідне положення – стоячи, руки зігнуті."}, {"kind": "p", "text": "На видиху відводимо коліно однієї ноги до протилежного боку та імітуємо удар ногою убік, на вдиху повертаємось у вихідне положення. Змінюємо ноги. 12 разів"}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Імітація ударів долонями поперемінно вперед із розворотом корпусу"}, {"kind": "p", "text": "Початкове положення – стоячи, ноги трохи зігнуті, на ширині плечей, руки зігнуті, притиснуті до боків."}, {"kind": "p", "text": "На видиху імітуємо удар відкритою долонею з розворотом корпусу, лікоть іншої руки відводиться назад, на вдиху починаємо відводити ударну руку назад, на видиху імітуємо удар іншою рукою і т.д. 12 разів"}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Імітація ударів поперемінно ногами назад"}, {"kind": "p", "text": "Вихідне положення – стоячи, руки зігнуті."}, {"kind": "p", "text": "На видиху підіймаємо коліно однієї ноги та імітуємо удар п''ятою назад, на вдиху повертаємось у вихідне положення, потім виконуємо іншою ногою, 12 разів"}, {"kind": "p", "text": "Вправа"}, {"kind": "ul", "items": ["Вправа"]}, {"kind": "p", "text": "Імітація ударів поперемінно кулаками збоку вперед на різній висоті"}, {"kind": "p", "text": "Початкове положення – стоячи, ноги трохи зігнуті, на ширині плечей, руки зігнуті, лікті притиснуті до боків, кулаки стиснуті."}, {"kind": "p", "text": "На видиху імітуємо удар однією рукою збоку вперед на рівні живота, на вдиху повертаємось у вихідне положення, потім на рівні грудей та на рівні голови, потім іншою рукою, по 12 разів, потім поперемінно однією та другою рукою на різних висотах 12 разів."}]}]', '2026-08-23 20:30:19.041894+00', '2026-09-08 15:24:02.326472+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('a3f1c7d2-0000-4000-8000-000000000104', 'a3f1c7d2-0000-4000-8000-000000000001', 'a3f1c7d2-0000-4000-8000-000000000011', 'day-4', 'День 4. Запитання', 4, 4, 5, '"Місце, де можна спитати про те, що не виходить."', '[{"id": "d4-objective", "text": "Якщо щось не виходить — сьогодні саме той день, щоб спитати.", "type": "lesson_objective"}, {"id": "d4-cover", "alt": "Обкладинка уроку: запитання по курсу", "src": "/cw/courses/short/day-4-questions.webp", "type": "image"}, {"id": "d4-intro", "type": "rich_text", "content": [{"kind": "p", "text": "Можливо, у вас виникли питання по вправах або по проходженню курсу. Напишіть — розберемо."}]}, {"id": "d4-support-cta", "href": "https://telegram.me/centerway_support_bot", "text": "Доступ, уроки, кабінет, оплата.", "type": "cta", "label": "Технічна підтримка CenterWay"}]', '2026-08-26 19:13:01.853432+00', '2026-09-08 15:24:03.880171+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('bd551583-57e9-4c84-9bf6-fc4d011cced9', '0faafa48-0f49-4f38-927a-210eec33b8df', 'a2d89899-ffa8-4114-9b4e-a2c3f2167713', 'urok-5', 'ТИЖНЕВИЙ ТРЕКЕР • 7 ДНІВ', 5, NULL, NULL, '"MY DAILY RHYTHM"', '[{"id": "c54aa337-2df2-4821-ad78-c5b67a8bdc99", "text": "Відмічайте практику без оцінювання. Завдання трекера — бачити ритм, а не вимагати ідеальності.", "type": "lesson_objective"}, {"id": "028364d7-c852-4135-b812-afd66afd0d65", "head": ["ДЕНЬ", "MORNING", "DAY", "EVENING"], "rows": [["Понеділок", "☐", "☐", "☐"], ["Вівторок", "☐", "☐", "☐"], ["Середа", "☐", "☐", "☐"], ["Четвер ", "☐", "☐", "☐"], ["П’ятниця", "☐", "☐", "☐"], ["Субота", "☐", "☐", "☐"], ["Неділя", "☐", "☐", "☐"]], "type": "table"}]', '2026-08-30 18:04:23.145312+00', '2026-09-01 14:07:15.53448+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('9e21e8f8-87ef-4501-81f8-cce0234f9b69', '0faafa48-0f49-4f38-927a-210eec33b8df', 'a2d89899-ffa8-4114-9b4e-a2c3f2167713', 'urok-3', '02  /  DAY', 3, NULL, NULL, '"FOCUS • Фокус & центр"', '[{"id": "ad1f032e-aac0-492b-832e-d838737b3616", "text": [{"bold": true, "text": "Коротка пауза серед дня, щоб повернути увагу до тіла та зменшити темп.", "italic": true}], "type": "lesson_objective"}, {"id": "3b29c78e-ad2c-4d9f-97d8-0076b6fb39dd", "step": 1, "text": "Coherent Breathing — це техніка повільного керованого дихання, яка синхронізує дихальний цикл із серцевим ритмом і артеріальним тиском, вводячи організм у стан максимальної фізіологічної рівноваги.", "type": "protocol_step", "title": "Резонансне дихання", "timing": "5,5 сек  ВДИХ  5,5 сек ВИДИХ  10 хв РИТМ"}, {"id": "430abdb9-6dd1-4178-b4d4-846396b5a525", "text": [{"bold": true, "text": "Техніка виконання"}], "type": "lesson_objective"}, {"id": "37eefcf8-a803-4e5d-a790-5c225e778f8b", "type": "rich_text", "content": [{"kind": "ul", "items": ["Сісти з комфортною прямою спиною.", "Розслабити плечі та щелепу.", "Повільно вдихати через ніс — 5,5 секунди.", "Без паузи плавно видихати — 5,5 секунди.", "Утримувати увагу на м’якому русі нижніх ребер.", "Продовжувати 10 хвилин."]}]}, {"id": "c367c5f7-c71c-40e3-99f4-84fe06f384de", "type": "rich_text", "content": [{"kind": "p", "text": [{"bold": true, "text": "Фізіологічний ефект"}]}, {"kind": "ul", "items": ["Максимізація варіабельності серцевого ритму (HRV): Серцевий ритм починає гармонійно коливатися в унісон із диханням і коливаннями кров''яного тиску (хвилі Траубе-Херинга-Маєра).", "Балансування нервової системи: Стимулює парасимпатичну нервову систему через активацію блукаючого нерва (vagus), знижуючи рівень стресу, кортизолу та тривожності"]}, {"kind": "p", "text": "Користь: Покращує концентрацію уваги, стабілізує артеріальний тиск, знімає напругу з діафрагми та допомагає швидко відновити ресурс нервової системи. Зазвичай практикується сесіями по 5–10 хвилин на день."}]}, {"id": "d547f21b-8f87-48b2-8ba1-ea709e8d5fcc", "text": "КЛЮЧ Не намагайтеся вдихнути більше повітря. Дихання має залишатися тихим, плавним і комфортним.", "type": "quote"}]', '2026-08-30 18:04:23.145312+00', '2026-09-01 14:07:15.53448+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('c8e8be12-b329-5d93-b174-ff5d9031ed29', 'fb5d1cf1-05b4-552a-9794-cf14a20e85f6', 'c2aa79bb-decc-521a-ab7e-7c541df5bbe9', 'lesson-19', 'Урок 19 · Баланс Вата доші', 2, NULL, NULL, NULL, '[{"id": "lesson-19-objective", "text": "Розібрати тему «Баланс Вата доші» і співвіднести її з практикою програми.", "type": "lesson_objective"}, {"id": "lesson-19-text-1", "type": "rich_text", "content": [{"kind": "h3", "text": [{"bold": true, "text": "Урок №19"}]}, {"kind": "p", "text": [{"bold": true, "text": "Тема: \"Баланс Вата доші\""}]}]}, {"id": "lesson-19-video-2-1", "type": "video", "title": "Урок №19 — відео", "videoId": "8BzCQsysj5A", "provider": "youtube"}]', '2026-08-23 17:45:07.335344+00', '2026-09-08 15:24:03.034047+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('a3f1c7d2-0000-4000-8000-000000000105', 'a3f1c7d2-0000-4000-8000-000000000001', 'a3f1c7d2-0000-4000-8000-000000000011', 'day-5', 'День 5. Як ви себе почуваєте', 5, 5, 5, '"Коротка зупинка й погляд на власні відчуття."', '[{"id": "d5-objective", "text": "Кілька днів практики позаду — подивіться, що змінилось у відчуттях.", "type": "lesson_objective"}, {"id": "d5-cover", "alt": "Обкладинка уроку: зворотний зв''язок після перших занять", "src": "/cw/courses/short/day-5-feedback.webp", "type": "image"}, {"id": "d5-intro", "type": "rich_text", "content": [{"kind": "p", "text": "Вже кілька днів як ви практикуєте. Як ви себе почуваєте після перших занять?"}, {"kind": "p", "text": "Поділіться відчуттями — це найкорисніший матеріал і для вас, і для нас."}]}, {"id": "d5-support-cta", "href": "https://telegram.me/centerway_support_bot", "text": "Що вийшло, що ні, що змінилось у тілі.", "type": "cta", "label": "Написати про свої відчуття"}]', '2026-08-26 19:13:01.853432+00', '2026-09-08 15:24:03.880171+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('c4a91d3e-0000-4000-8000-000000000121', 'c4a91d3e-0000-4000-8000-000000000001', 'c4a91d3e-0000-4000-8000-000000000013', 'w2-herbs', 'Збір і клітковина другого тижня', 2, 9, 8, '"Схема заварювання, дозування клітковини й на що дивитися у звітах."', '[{"id": "w2h-objective", "text": "Приймати збір і клітковину так, щоб очищення йшло м''яко й передбачувано.", "type": "lesson_objective"}, {"id": "w2h-brew", "text": "Заварюємо 4,5 ч. л. на 750 мл води температурою 80 градусів. Настоюємо 40 хв. П''ємо за 15 хв до їжі.", "type": "practice_block", "title": "Трав''яний збір"}, {"id": "w2h-fiber", "text": "1 ч. л. настоюємо в 200 мл води, вода може бути кімнатної температури — це порція на 1 раз. П''ємо клітковину 3 рази на день, безпосередньо перед їжею чи з їжею. Якщо на цьому етапі кількість дефекацій буде більше, ніж 5, то приймаємо клітковину 2 рази на день — зранку і ввечері.", "type": "practice_block", "title": "Клітковина"}, {"id": "w2h-important", "type": "rich_text", "content": [{"kind": "h3", "text": "Важливо"}, {"kind": "p", "text": "Тверді випорожнення на другому етапі повинні бути більш м''якими і частішими, ніж зазвичай. Якщо це не так — обов''язково відмічайте це у звітах, і Євгеній підкаже, що робити."}]}, {"id": "w2h-water", "type": "rich_text", "content": [{"kind": "h3", "text": "Питний режим"}, {"kind": "p", "text": "Один раз на 40–60 хв приймаємо 30–120 мл теплої води. Більше не потрібно: наші нирки не здатні одномоментно обробити великий об''єм води."}]}]', '2026-08-19 14:47:31.154378+00', '2026-09-08 15:24:04.29744+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('2fc58ff6-90a8-432e-8ac1-a9c7c057d0c7', '0faafa48-0f49-4f38-927a-210eec33b8df', 'a2d89899-ffa8-4114-9b4e-a2c3f2167713', 'urok-6', 'Бонус', 6, NULL, NULL, '"Відео урок з дихальної гімнастика   "', '[{"id": "a0850379-154a-4c9a-a0ba-8642942c4ffa", "type": "video", "videoId": "uoXBYxPAOXo", "provider": "youtube", "durationMin": 12}]', '2026-08-31 12:45:42.02209+00', '2026-09-01 14:07:15.53448+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('a3f1c7d2-0000-4000-8000-000000000106', 'a3f1c7d2-0000-4000-8000-000000000001', 'a3f1c7d2-0000-4000-8000-000000000011', 'day-6', 'День 6. Усі матеріали', 6, 6, 5, '"Дайджест курсу: що де лежить."', '[{"id": "d6-objective", "text": "Усе, що знадобиться для практики, зібране в одному місці.", "type": "lesson_objective"}, {"id": "d6-cover", "alt": "Обкладинка уроку: дайджест матеріалів курсу", "src": "/cw/courses/short/day-6-digest.webp", "type": "image"}, {"id": "d6-intro", "type": "rich_text", "content": [{"kind": "p", "text": "Тут зібране все, що може вам знадобитися для повноцінного опанування технік. У боті це був список посилань; на платформі матеріали лежать в уроках і залишаються з вами."}, {"kind": "h3", "text": "Практика"}, {"kind": "ul", "items": ["День 1 — комплекс гімнастики «Short-Перезавантаження»: відео, опис семи вправ і нагадувалка", "День 2 — ранковий очисний комплекс і вечірній комплекс пранаям: відео, описи технік і нагадувалки"]}, {"kind": "h3", "text": "Розбори"}, {"kind": "ul", "items": ["День 3 — три докладні пояснення: гімнастика, ранкове дихання, вечірнє дихання"]}]}]', '2026-08-26 19:13:01.853432+00', '2026-09-08 15:24:03.880171+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('c4a91d3e-0000-4000-8000-000000000132', 'c4a91d3e-0000-4000-8000-000000000001', 'c4a91d3e-0000-4000-8000-000000000014', 'w3-final', 'Фінал: що змінилося за 21 день', 3, 21, 6, '"Звіряємося з орієнтирами програми і фіксуємо результат."', '[{"id": "w3fin-objective", "text": "Зафіксувати результат і зрозуміти, що тримати далі.", "type": "lesson_objective"}, {"id": "w3fin-outcomes", "type": "rich_text", "content": [{"kind": "h3", "text": "Орієнтири після повного циклу"}, {"kind": "ul", "items": ["Дихання спокійне й амплітудне", "Травлення сильне й стабільне", "Відходи життєдіяльності виводяться вчасно й без утруднення, немає набряків і мішків під очима", "Сон стабільний і регулярний, проблем із засинанням немає", "Шкіра чиста й еластична, тіло гнучкіше й менш болісне", "Вага в нормі або рухається до норми — і ви чітко розумієте, як продовжувати"]}]}, {"id": "w3fin-checklist", "type": "checklist", "items": [{"id": "w3fin-c1", "text": "21 день пройдено"}, {"id": "w3fin-c2", "text": "Вихід у тверду їжу зроблено послідовно"}, {"id": "w3fin-c3", "text": "Свій режим харчування на далі зафіксовано"}], "title": "Завершення програми", "requiredForCompletion": true}, {"id": "w3fin-cta", "href": "https://t.me/E_Koriakin", "text": "Підсумковий звіт і питання про подальший режим.", "type": "cta", "label": "Написати Євгенію"}]', '2026-08-19 14:47:31.154378+00', '2026-09-08 15:24:04.29744+00');
INSERT INTO public.lms_lessons (id, course_id, module_id, slug, title, "order", day_index, duration_min, summary, blocks, created_at, updated_at) VALUES ('c4a91d3e-0000-4000-8000-000000000102', 'c4a91d3e-0000-4000-8000-000000000001', 'c4a91d3e-0000-4000-8000-000000000015', 'phyto-protocol', 'Фітопротокол: склад зборів і як їх заварювати', 2, NULL, 10, '"Три збори — три задачі. Склад коригується під вашу дошу, стан і сезон."', '[{"id": "ph-objective", "text": "Розуміти, що саме ви п''єте кожного тижня і чому послідовність не можна міняти місцями.", "type": "lesson_objective"}, {"id": "ph-brew", "type": "rich_text", "content": [{"kind": "h3", "text": "Заварювання"}, {"kind": "ul", "items": [[{"bold": true, "text": "Тиждень 1 — "}, {"text": "4,5 ч. л. на 800 мл води температурою 80 градусів, настоювати 40 хв у термосі. За один прийом — 250 мл, тричі на день разом з їжею."}], [{"bold": true, "text": "Тиждень 2 — "}, {"text": "4,5 ч. л. на 750 мл води температурою 80 градусів, настоювати 40 хв. Пити за 15 хв до їжі. Плюс клітковина: 1 ч. л. на 200 мл води, 3 рази на день."}], [{"bold": true, "text": "Тиждень 3 — "}, {"text": "трави скасовуються, лишається кислий напій перед кожним прийомом їжі."}]]}]}, {"id": "ph-1", "type": "rich_text", "content": [{"kind": "h3", "text": "Збір №1 · тиждень 1 · дренаж"}, {"kind": "p", "text": "Розвантаження жовчних проток, лімфодренаж, зняття спазмів. Готує тіло до глибокого очищення на другому етапі."}, {"kind": "ul", "items": [[{"bold": true, "text": "Кукурудзяні рильця — "}, {"text": "розріджують жовч і підтримують її плавне виведення в дванадцятипалу кишку, знімаючи застій у жовчному міхурі."}], [{"bold": true, "text": "Ромашка й календула — "}, {"text": "хамазулен і каротиноїди м''яко заспокоюють слизову ШКТ і готують шлунок до грубої клітковини наступного тижня."}], [{"bold": true, "text": "Шипшина (плоди) — "}, {"text": "вітамінний комплекс C, P, K і ниркова фільтрація: первинний дренаж тканин."}], [{"bold": true, "text": "Пустирник — "}, {"text": "знімає нейровегетативну напругу й спазм сфінктера Одді, тому старт проходить без спастичного болю, нудоти чи печії."}]]}]}, {"id": "ph-2", "type": "rich_text", "content": [{"kind": "h3", "text": "Збір №2 · тиждень 2 · лімфа й антибродіння"}, {"kind": "ul", "items": [[{"bold": true, "text": "Цикорій — "}, {"text": "природний інулін, пребіотик: захищає мікробіом під час інтенсивного очищення."}], [{"bold": true, "text": "Бузина (квіти) — "}, {"text": "головний лімфотонік програми: активує дренаж лімфи малого таза й черевної порожнини."}], [{"bold": true, "text": "Фенхель, кріп, кмин — "}, {"text": "ефіроолійна вітрогінна група: знімає метеоризм і бродіння при розщепленні великих об''ємів клітковини."}], [{"bold": true, "text": "Валеріана й меліса — "}, {"text": "м''які міорелаксанти: роблять перистальтику плавною, запобігають колькам."}], [{"bold": true, "text": "Фіалка триколірна — "}, {"text": "додає очисне навантаження на нирки й шкіру як допоміжні шляхи виведення."}]]}]}, {"id": "ph-3", "type": "rich_text", "content": [{"kind": "h3", "text": "Збір №3 · тиждень 2 · сорбція й захист слизової"}, {"kind": "ul", "items": [[{"bold": true, "text": "Овес і насіння льону — "}, {"text": "щит слизової: мукополісахаридні слизи утворюють захисний ковзний гель уздовж усього ШКТ."}], [{"bold": true, "text": "Псиліум — "}, {"text": "гідрофільна розчинна клітковина: формує м''який гелеподібний болюс і запускає фізіологічний рефлекс випорожнення."}], [{"bold": true, "text": "Клітковина яблука — "}, {"text": "розчинний пектин, глибокий ентеросорбент: зв''язує важкі метали, залишки медикаментів і токсичні метаболіти."}], [{"bold": true, "text": "Клітковина буряку — "}, {"text": "грубі нерозчинні волокна працюють як делікатна щітка для складок і крипт товстого кишківника."}], [{"bold": true, "text": "Сенна (касія) — "}, {"text": "антраглікозиди прискорюють евакуацію мас; завдяки слизам вівса й льону діє м''яко, без болісних спазмів."}], [{"bold": true, "text": "Стальник, солодка — "}, {"text": "за можливості й показаннями: протизапальна дія, менша набряклість вен, загоєння мікроерозій слизової."}]]}]}, {"id": "ph-substitutes", "type": "rich_text", "content": [{"kind": "p", "text": "Усі збори складені з трав нашої широти. Якщо ви живете там, куди доставка трав ускладнена, склад замінюється на аюрведичні препарати — узгоджується індивідуально."}]}, {"id": "ph-boundary", "text": "Фітопідтримка доповнює, а не замінює лікування. Склад підбирається під вашу конституцію, стан і сезон — не збирайте його самостійно «за списком».", "type": "boundary_note"}]', '2026-08-19 14:47:31.154378+00', '2026-09-08 15:24:04.29744+00');
INSERT INTO public.lms_media_assets (id, course_id, asset_key, canonical_path, paths, bytes, content_type, width, height, uploaded_by, created_at, swept_at) VALUES ('7f11cfef-3edd-4b05-820d-fe3c3fea9ffd', NULL, 'authors/bdc98ead-08d6-4869-ae09-cd154030e339/7f11cfef-3edd-4b05-820d-fe3c3fea9ffd', 'authors/bdc98ead-08d6-4869-ae09-cd154030e339/7f11cfef-3edd-4b05-820d-fe3c3fea9ffd/1600.webp', '{authors/bdc98ead-08d6-4869-ae09-cd154030e339/7f11cfef-3edd-4b05-820d-fe3c3fea9ffd/1600.webp,authors/bdc98ead-08d6-4869-ae09-cd154030e339/7f11cfef-3edd-4b05-820d-fe3c3fea9ffd/640.webp}', 6694, 'image/webp', 1080, 1351, 'bdc98ead-08d6-4869-ae09-cd154030e339', '2026-08-29 19:48:14.269104+00', NULL);
INSERT INTO public.lms_media_assets (id, course_id, asset_key, canonical_path, paths, bytes, content_type, width, height, uploaded_by, created_at, swept_at) VALUES ('d214113a-2694-4701-8c92-0762369aa6f1', '0faafa48-0f49-4f38-927a-210eec33b8df', 'courses/0faafa48-0f49-4f38-927a-210eec33b8df/d214113a-2694-4701-8c92-0762369aa6f1', 'courses/0faafa48-0f49-4f38-927a-210eec33b8df/d214113a-2694-4701-8c92-0762369aa6f1/1600.webp', '{courses/0faafa48-0f49-4f38-927a-210eec33b8df/d214113a-2694-4701-8c92-0762369aa6f1/1600.webp,courses/0faafa48-0f49-4f38-927a-210eec33b8df/d214113a-2694-4701-8c92-0762369aa6f1/640.webp}', 289186, 'image/webp', 1600, 2133, 'a68003e9-e804-4d1c-96d0-08b2d770a6d6', '2026-08-29 20:42:21.00036+00', NULL);
