INSERT INTO public.test_questions (id, test_id, order_index, question_code, question_text, status, created_at, updated_at) VALUES ('f32a6115-50da-4e56-ae57-710f58d5041d', 'a2c5a8a3-95c1-4db7-a79c-379810c34aad', 7, 'q07', 'Як зазвичай працює ваш кишечник?', 'active', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:07.076461+00');
INSERT INTO public.test_questions (id, test_id, order_index, question_code, question_text, status, created_at, updated_at) VALUES ('98cc575f-9fcc-4769-b0c7-ec7ca1b90b9b', 'a2c5a8a3-95c1-4db7-a79c-379810c34aad', 8, 'q08', 'Як би ви описали свій сон та пробудження?', 'active', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:07.877483+00');
INSERT INTO public.test_questions (id, test_id, order_index, question_code, question_text, status, created_at, updated_at) VALUES ('1b793012-38ed-425c-ba21-2adc9e7e939c', 'a2c5a8a3-95c1-4db7-a79c-379810c34aad', 9, 'q09', 'Як би ви оцінили свій рівень енергії та фізичної витривалості?', 'active', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:08.389514+00');
INSERT INTO public.test_questions (id, test_id, order_index, question_code, question_text, status, created_at, updated_at) VALUES ('c1a7ed0e-805a-4fa5-9341-46a67fc66d4d', 'a2c5a8a3-95c1-4db7-a79c-379810c34aad', 10, 'q10', 'Як би ви описали своє волосся від природи?', 'active', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:08.88444+00');
INSERT INTO public.test_questions (id, test_id, order_index, question_code, question_text, status, created_at, updated_at) VALUES ('d8807182-18fb-48fe-9d43-96ba2dc45211', 'a2c5a8a3-95c1-4db7-a79c-379810c34aad', 11, 'q11', 'Який стан шкіри для вас найбільш характерний?', 'active', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:09.581555+00');
INSERT INTO public.test_questions (id, test_id, order_index, question_code, question_text, status, created_at, updated_at) VALUES ('2fce6e76-f886-4f85-a79e-6845b2e702c0', 'a2c5a8a3-95c1-4db7-a79c-379810c34aad', 12, 'q12', 'Як би ви описали свою природну статуру?', 'active', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:10.335463+00');
INSERT INTO public.test_options (id, question_id, option_order, option_code, option_text, mapped_dosha, created_at, updated_at) VALUES ('ead35816-8575-4fd2-b295-7e3c3c20573e', 'c27a430c-4f5f-45d4-90cc-92e0acb4abe9', 1, 'q04_a1', 'Я дуже швидко розумію нове, миттєво вловлюю ідеї, хоч іноді й поверхнево.', 'vata', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:05.426893+00');
INSERT INTO public.test_options (id, question_id, option_order, option_code, option_text, mapped_dosha, created_at, updated_at) VALUES ('60ee81d9-39fd-4eba-8391-3ba56d7ba227', 'eaa83583-8d69-44e1-98ab-0933492dcb01', 2, 'q06_a2', 'Я легко дратуюся, можу бути нетерплячим(ою) або різким(ою), коли щось іде не за планом.', 'pitta', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:06.847374+00');
INSERT INTO public.test_options (id, question_id, option_order, option_code, option_text, mapped_dosha, created_at, updated_at) VALUES ('e2576fca-3c4f-4334-881b-f0c1969015b4', 'eaa83583-8d69-44e1-98ab-0933492dcb01', 3, 'q06_a3', 'Зазвичай я зберігаю спокій та врівноваженість, але іноді можу відчувати апатію чи лінощі.', 'kapha', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:06.962228+00');
INSERT INTO public.test_options (id, question_id, option_order, option_code, option_text, mapped_dosha, created_at, updated_at) VALUES ('c7a0d54f-9bfb-4f64-a0df-b2404f05600e', 'f32a6115-50da-4e56-ae57-710f58d5041d', 1, 'q07_a1', 'Робота кишечника нерегулярна. Часто бувають закрепи, відчуття сухості або здуття.', 'vata', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:07.199417+00');
INSERT INTO public.test_options (id, question_id, option_order, option_code, option_text, mapped_dosha, created_at, updated_at) VALUES ('ace4b1d2-0eea-4085-9ff7-b6889962c45b', 'f32a6115-50da-4e56-ae57-710f58d5041d', 2, 'q07_a2', 'Кишечник працює дуже активно і швидко. Випорожнення часті, м''які, є схильність до розладів.', 'pitta', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:07.311198+00');
INSERT INTO public.test_options (id, question_id, option_order, option_code, option_text, mapped_dosha, created_at, updated_at) VALUES ('6edb9ef8-5b70-4dd0-96bd-a190d54bf7d4', 'c1a7ed0e-805a-4fa5-9341-46a67fc66d4d', 3, 'q10_a3', 'Дуже густе, міцне і блискуче. Добре росте, але може бути важким.', 'kapha', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:09.469082+00');
INSERT INTO public.test_options (id, question_id, option_order, option_code, option_text, mapped_dosha, created_at, updated_at) VALUES ('8ff474a2-1199-49b1-82f9-426534ff95bb', 'd8807182-18fb-48fe-9d43-96ba2dc45211', 2, 'q11_a2', 'Шкіра чутлива, тепла. Легко червоніє на сонці чи від емоцій, бувають подразнення чи висипання.', 'pitta', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:09.933547+00');
INSERT INTO public.test_options (id, question_id, option_order, option_code, option_text, mapped_dosha, created_at, updated_at) VALUES ('a24fc688-67cc-4918-ba88-73a9bac72245', '2fce6e76-f886-4f85-a79e-6845b2e702c0', 1, 'q12_a1', 'Від природи тонка, худорлява статура та легка кістка. Важко набираю вагу.', 'vata', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:11.253747+00');
INSERT INTO public.test_options (id, question_id, option_order, option_code, option_text, mapped_dosha, created_at, updated_at) VALUES ('857e2570-4f5b-4fb2-bb16-18654d9a0367', '2fce6e76-f886-4f85-a79e-6845b2e702c0', 2, 'q12_a2', 'Збалансована, пропорційна статура (часто спортивна). Вага стабільна, легко керувати нею.', 'pitta', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:11.486617+00');
INSERT INTO public.test_options (id, question_id, option_order, option_code, option_text, mapped_dosha, created_at, updated_at) VALUES ('4be9d2d5-f323-4a45-8413-f23227946438', 'c951a80e-b877-4723-ae9b-f61dd277c486', 1, 'q01_a1', 'Швидкий та енергійний. Я дію швидко, іноді метушливо, часто поспішаю.', 'vata', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:02.928264+00');
INSERT INTO public.test_options (id, question_id, option_order, option_code, option_text, mapped_dosha, created_at, updated_at) VALUES ('90c64067-7160-4a3c-b36e-fc4764425170', 'c951a80e-b877-4723-ae9b-f61dd277c486', 2, 'q01_a2', 'Помірний та чіткий. Мій темп впевнений і цілеспрямований, без зайвої суєти.', 'pitta', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:03.100322+00');
INSERT INTO public.test_options (id, question_id, option_order, option_code, option_text, mapped_dosha, created_at, updated_at) VALUES ('d0b2ffd5-5f02-4045-a9e9-8e37d3bba6f6', 'c951a80e-b877-4723-ae9b-f61dd277c486', 3, 'q01_a3', 'Розмірений та спокійний. Я рухаюся неквапливо і плавно, зберігаючи внутрішній спокій.', 'kapha', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:03.383129+00');
INSERT INTO public.test_options (id, question_id, option_order, option_code, option_text, mapped_dosha, created_at, updated_at) VALUES ('3ad06021-640d-48bd-b5f2-8a064dbbcc4a', 'e73d4751-22a8-4a93-a739-21a126f7ce78', 1, 'q02_a1', 'Я дуже швидко мерзну, тому найбільше не люблю холод, вітер і протяги.', 'vata', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:03.620708+00');
INSERT INTO public.test_options (id, question_id, option_order, option_code, option_text, mapped_dosha, created_at, updated_at) VALUES ('855193ed-2401-431c-833a-bb0f5c3b4bd3', 'e73d4751-22a8-4a93-a739-21a126f7ce78', 2, 'q02_a2', 'Я швидко перегріваюся, тому найгірше переношу спеку та палюче сонце.', 'pitta', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:03.929767+00');
INSERT INTO public.test_options (id, question_id, option_order, option_code, option_text, mapped_dosha, created_at, updated_at) VALUES ('e7b5dd42-8dac-4d95-88f8-7643cf2cb606', 'e73d4751-22a8-4a93-a739-21a126f7ce78', 3, 'q02_a3', 'Мене пригнічує сирість і волога прохолода, не люблю похмурі та дощові дні.', 'kapha', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:04.322037+00');
INSERT INTO public.test_options (id, question_id, option_order, option_code, option_text, mapped_dosha, created_at, updated_at) VALUES ('5658e6bd-cf9f-4c67-b51e-a33d3d23644d', '0bfc55f1-d519-44bc-8871-7bb530d6f5c3', 1, 'q03_a1', 'Мій апетит постійно змінюється (можу забути поїсти або перекушую на ходу). Травлення чутливе та нерегулярне.', 'vata', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:04.768504+00');
INSERT INTO public.test_options (id, question_id, option_order, option_code, option_text, mapped_dosha, created_at, updated_at) VALUES ('e7556b70-7577-4d6e-8a59-a304b3a0818c', 'c27a430c-4f5f-45d4-90cc-92e0acb4abe9', 2, 'q04_a2', 'Я швидко розбираюся в темі, але мені важливо зрозуміти систему, структуру та логіку.', 'pitta', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:05.554699+00');
INSERT INTO public.test_options (id, question_id, option_order, option_code, option_text, mapped_dosha, created_at, updated_at) VALUES ('65cda457-ce27-43d6-b673-797fe5d3f4d1', 'c27a430c-4f5f-45d4-90cc-92e0acb4abe9', 3, 'q04_a3', 'Мені потрібен час, щоб вникнути. Я сприймаю інформацію неквапливо, бо люблю розбиратися глибоко.', 'kapha', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:05.671941+00');
INSERT INTO public.test_options (id, question_id, option_order, option_code, option_text, mapped_dosha, created_at, updated_at) VALUES ('9418541a-6c23-45c5-83fc-86b3ecad5206', '0bfc55f1-d519-44bc-8871-7bb530d6f5c3', 2, 'q03_a2', 'У мене завжди сильний апетит — мені важко терпіти голод. Травлення швидке та активне.', 'pitta', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:04.887667+00');
INSERT INTO public.test_options (id, question_id, option_order, option_code, option_text, mapped_dosha, created_at, updated_at) VALUES ('7b3af8ef-3453-474e-9464-96c980c8b637', '0bfc55f1-d519-44bc-8871-7bb530d6f5c3', 3, 'q03_a3', 'Апетит слабкий або помірний. Травлення повільне, після їжі часто з''являється відчуття важкості.', 'kapha', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:05.017791+00');
INSERT INTO public.test_options (id, question_id, option_order, option_code, option_text, mapped_dosha, created_at, updated_at) VALUES ('a7dd056a-d37e-4f27-9652-4e8a2fcc8c3b', 'ff865691-03ab-4698-bcb7-96afbda4fd43', 1, 'q05_a1', 'У мене хороша короткочасна пам''ять, але з часом я легко забуваю деталі чи події.', 'vata', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:06.073477+00');
INSERT INTO public.test_options (id, question_id, option_order, option_code, option_text, mapped_dosha, created_at, updated_at) VALUES ('f794feaf-6d2b-427c-951d-da7d6201b711', 'ff865691-03ab-4698-bcb7-96afbda4fd43', 2, 'q05_a2', 'У мене ясна та чітка пам''ять. Я легко запам''ятовую потрібну інформацію, імена, дати чи факти.', 'pitta', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:06.194424+00');
INSERT INTO public.test_options (id, question_id, option_order, option_code, option_text, mapped_dosha, created_at, updated_at) VALUES ('81a69ffd-971f-4d51-be46-f4ec390d7d1f', 'ff865691-03ab-4698-bcb7-96afbda4fd43', 3, 'q05_a3', 'Мені потрібен час, щоб щось вивчити, але те, що я запам''ятав(ла), залишається зі мною надовго.', 'kapha', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:06.319556+00');
INSERT INTO public.test_options (id, question_id, option_order, option_code, option_text, mapped_dosha, created_at, updated_at) VALUES ('45eb0e2e-cf16-4fe6-9fa6-0e20d1dedf8d', 'eaa83583-8d69-44e1-98ab-0933492dcb01', 1, 'q06_a1', 'Я часто хвилююся, багато думаю про проблеми, схильний(а) до тривоги та сумнівів.', 'vata', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:06.736937+00');
INSERT INTO public.test_options (id, question_id, option_order, option_code, option_text, mapped_dosha, created_at, updated_at) VALUES ('fd420fa1-f54e-4e91-a3cb-78b52fecd817', '98cc575f-9fcc-4769-b0c7-ec7ca1b90b9b', 1, 'q08_a1', 'Мій сон часто чуткий та неспокійний. Мені буває важко заснути через думки, або прокидаюсь уночі.', 'vata', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:07.998832+00');
INSERT INTO public.test_options (id, question_id, option_order, option_code, option_text, mapped_dosha, created_at, updated_at) VALUES ('ed197a53-54f3-4434-ba9f-736e90d529ca', '98cc575f-9fcc-4769-b0c7-ec7ca1b90b9b', 2, 'q08_a2', 'Я сплю міцно і висипаюся за 7–8 годин. Швидко засинаю і прокидаюсь бадьорим(ою).', 'pitta', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:08.112119+00');
INSERT INTO public.test_options (id, question_id, option_order, option_code, option_text, mapped_dosha, created_at, updated_at) VALUES ('5f6fbf6f-7878-4627-9cac-a1ba60c3d690', '1b793012-38ed-425c-ba21-2adc9e7e939c', 1, 'q09_a1', 'Моя енергія нестабільна. Я дію спалахами: можу бути дуже активним(ою), але швидко втомлююсь.', 'vata', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:08.53468+00');
INSERT INTO public.test_options (id, question_id, option_order, option_code, option_text, mapped_dosha, created_at, updated_at) VALUES ('180a9896-d319-4d80-ad0d-80aac46f74d9', '1b793012-38ed-425c-ba21-2adc9e7e939c', 2, 'q09_a2', 'У мене хороший запас енергії та витривалість, але є схильність заганяти себе до виснаження.', 'pitta', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:08.65299+00');
INSERT INTO public.test_options (id, question_id, option_order, option_code, option_text, mapped_dosha, created_at, updated_at) VALUES ('d5e5cca7-4508-4109-a74a-ac447e43e9e1', 'c1a7ed0e-805a-4fa5-9341-46a67fc66d4d', 1, 'q10_a1', 'Від природи сухе, схильне до ламкості та посічених кінчиків. Часто неслухняне або пухнасте.', 'vata', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:09.001003+00');
INSERT INTO public.test_options (id, question_id, option_order, option_code, option_text, mapped_dosha, created_at, updated_at) VALUES ('dd4fb98e-e627-4b18-8138-2f055f5dcd6d', 'c1a7ed0e-805a-4fa5-9341-46a67fc66d4d', 2, 'q10_a2', 'Тонке, м''яке і пряме. Є схильність до раннього посивіння або порідіння.', 'pitta', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:09.299587+00');
INSERT INTO public.test_options (id, question_id, option_order, option_code, option_text, mapped_dosha, created_at, updated_at) VALUES ('c56ab1a5-c37d-474c-ad3b-0b4b9cf143c5', 'f32a6115-50da-4e56-ae57-710f58d5041d', 3, 'q07_a3', 'Кишечник працює стабільно і регулярно. Але іноді процес може бути повільним, з відчуттям важкості.', 'kapha', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:07.6067+00');
INSERT INTO public.test_options (id, question_id, option_order, option_code, option_text, mapped_dosha, created_at, updated_at) VALUES ('a3672108-579b-4165-9721-b3b49952984e', '98cc575f-9fcc-4769-b0c7-ec7ca1b90b9b', 3, 'q08_a3', 'У мене дуже глибокий сон, люблю спати довго. Зранку мені потрібно багато часу на розкачку.', 'kapha', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:08.23589+00');
INSERT INTO public.test_options (id, question_id, option_order, option_code, option_text, mapped_dosha, created_at, updated_at) VALUES ('36d3a477-07f0-4f1f-8ae7-418fc47164af', '1b793012-38ed-425c-ba21-2adc9e7e939c', 3, 'q09_a3', 'У мене висока витривалість. Важко почати, але якщо втягнувся(лась), можу працювати довго і стабільно.', 'kapha', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:08.775184+00');
INSERT INTO public.test_options (id, question_id, option_order, option_code, option_text, mapped_dosha, created_at, updated_at) VALUES ('b1b88829-231d-4ead-b1d7-5f1b58221998', 'd8807182-18fb-48fe-9d43-96ba2dc45211', 1, 'q11_a1', 'Шкіра переважно суха, тонка (крізь неї можуть просвічувати вени), легко мерзне.', 'vata', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:09.824+00');
INSERT INTO public.test_options (id, question_id, option_order, option_code, option_text, mapped_dosha, created_at, updated_at) VALUES ('dc1a3522-6b64-4ffb-864a-fe95cf6f1ae2', 'd8807182-18fb-48fe-9d43-96ba2dc45211', 3, 'q11_a3', 'Шкіра приємна на дотик, щільна та гладка. Добре утримує вологу, але іноді схильна до жирності.', 'kapha', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:10.226443+00');
INSERT INTO public.test_options (id, question_id, option_order, option_code, option_text, mapped_dosha, created_at, updated_at) VALUES ('a83f642c-e56b-424f-96b8-09481fd37aca', '2fce6e76-f886-4f85-a79e-6845b2e702c0', 3, 'q12_a3', 'Міцна тілобудова, широка кістка. Швидко набираю вагу, іноді важко її позбутися.', 'kapha', '2026-04-01 20:20:47.572032+00', '2026-09-09 12:25:11.601686+00');
